(329379,36598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si al hombre de la kandura no le gustaran los diseños, hoy no ... ningún acuerdo.'::text,'habría'::text,'habrá'::text,'hay'::text,'Si al hombre de la kandura no le gustaran los diseños, hoy no habría ningún acuerdo.'::text),
(329378,36598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''homme en kandura n''aimait pas les designs, il n''y ... aucun accord aujourd''hui.'::text,'aurait'::text,'aura'::text,'a'::text,'Si l''homme en kandura n''aimait pas les designs, il n''y aurait aucun accord aujourd''hui.'::text),
(329381,36598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanduralı adam tasarımları beğenmeseydi, bugün hiçbir anlaşma ...'::text,'olmazdı'::text,'olmayacak'::text,'yok'::text,'Kanduralı adam tasarımları beğenmeseydi, bugün hiçbir anlaşma olmazdı.'::text),
(329382,36598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a kandurás férfinak nem tetszenének a dizájnok, ma nem ... megállapodás.'::text,'lenne'::text,'lesz'::text,'van'::text,'Ha a kandurás férfinak nem tetszenének a dizájnok, ma nem lenne megállapodás.'::text),
(329385,36599,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Vereinbarung ... heute Morgen im Meeting um 10 Uhr unterschrieben.'::text,'wurde'::text,'wird'::text,'hat'::text,'Die Vereinbarung wurde heute Morgen im Meeting um 10 Uhr unterschrieben.'::text),
(329389,36599,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Угоду ... сьогодні вранці на нараді о 10:00.'::text,'було підписано'::text,'підписано'::text,'підписала'::text,'Угоду було підписано сьогодні вранці на нараді о 10:00.'::text),
