(329394,36600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Vereinbarung ... von zwei Menschen geschlossen, weil ein Mensch nicht allein Hände schütteln kann.'::text,'wird'::text,'schließt'::text,'schließend'::text,'Eine Vereinbarung wird von zwei Menschen geschlossen, weil ein Mensch nicht allein Hände schütteln kann.'::text),
