(329407,36601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усмішки й фінальне рукостискання свідчать про те, що угоду ... досягнуто.'::text,'точно було'::text,'можливо, було'::text,'не могло бути'::text,'Усмішки й фінальне рукостискання свідчать про те, що угоду точно було досягнуто.'::text),
