(329408,36601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gülümsemeler ve son el sıkışma, bir anlaşmaya ... gösteriyor.'::text,'varılmış olması gerektiğini'::text,'varılmış olabileceğini'::text,'varılmış olamayacağını'::text,'Gülümsemeler ve son el sıkışma, bir anlaşmaya varılmış olması gerektiğini gösteriyor.'::text),
