(329426,36603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu anlaşma olmadan şirketin her şeyi ... yemin etti!'::text,'kaybedeceğine'::text,'kaybedeceğine'::text,'kaybettiğine'::text,'Bu anlaşma olmadan şirketin her şeyi kaybedeceğine yemin etti!'::text),
