(401463,44607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az anya leült a váróteremben, és ...'::text,'a fia is'::text,'a fia is'::text,'a fia is'::text,'Az anya leült a váróteremben, és a fia is.'::text),
(401466,44608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Bis Mittag werde ich jede Zeitschrift in diesem Wartezimmer ...'::text,'gelesen haben'::text,'lesen'::text,'lesen'::text,'Albtraum! Bis Mittag werde ich jede Zeitschrift in diesem Wartezimmer gelesen haben.'::text),
(401470,44608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! До обіду я ... кожен журнал у цій приймальні.'::text,'прочитаю'::text,'прочитаю'::text,'читатиму'::text,'Жах! До обіду я прочитаю кожен журнал у цій приймальні.'::text),
(401469,44608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! Para el mediodía ... todas las revistas de esta sala de espera.'::text,'habré leído'::text,'leeré'::text,'estaré leyendo'::text,'¡Pesadilla! Para el mediodía habré leído todas las revistas de esta sala de espera.'::text),
(401468,44608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! D''ici midi, ... tous les magazines de cette salle d''attente.'::text,'j''aurai lu'::text,'je lirai'::text,'je serai en train de lire'::text,'Cauchemar ! D''ici midi, j''aurai lu tous les magazines de cette salle d''attente.'::text),
(401471,44608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Öğlene kadar bu bekleme salonundaki her dergiyi ...'::text,'okumuş olacağım'::text,'okuyacağım'::text,'okuyor olacağım'::text,'Kâbus! Öğlene kadar bu bekleme salonundaki her dergiyi okumuş olacağım.'::text),
(401472,44608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Délre ... az összes magazint ebben a váróban.'::text,'kiolvasom'::text,'elolvasom'::text,'olvasni fogom'::text,'Rémálom! Délre kiolvasom az összes magazint ebben a váróban.'::text),
(401475,44609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn wir zehn Minuten später gekommen wären, ... das Wartezimmer komplett voll gewesen!'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn wir zehn Minuten später gekommen wären, wäre das Wartezimmer komplett voll gewesen!'::text),
(401479,44609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ми прийшли на десять хвилин пізніше, приймальня ... повністю заповнена!'::text,'була б'::text,'буде'::text,'була'::text,'Якби ми прийшли на десять хвилин пізніше, приймальня була б повністю заповнена!'::text),
(401478,44609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si hubiéramos llegado diez minutos más tarde, la sala de espera ... completamente llena!'::text,'habría estado'::text,'estará'::text,'estaba'::text,'¡Si hubiéramos llegado diez minutos más tarde, la sala de espera habría estado completamente llena!'::text),
(401477,44609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si nous étions arrivés dix minutes plus tard, la salle d''attente ... complètement pleine !'::text,'aurait été'::text,'sera'::text,'était'::text,'Si nous étions arrivés dix minutes plus tard, la salle d''attente aurait été complètement pleine !'::text),
(401480,44609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dakika geç gelseydik, bekleme salonu tamamen ...!'::text,'dolu olurdu'::text,'dolu olacak'::text,'doluydu'::text,'On dakika geç gelseydik, bekleme salonu tamamen dolu olurdu!'::text),
(401481,44609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha tíz perccel később érkeztünk volna, a váró teljesen ...!'::text,'tele lett volna'::text,'tele lesz'::text,'tele volt'::text,'Ha tíz perccel később érkeztünk volna, a váró teljesen tele lett volna!'::text),
(401484,44610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge bestand darauf, zweimal auf die Klingel zu ..., und das ganze Wartezimmer wurde totenstill!'::text,'drücken'::text,'drücken'::text,'drücken'::text,'Der Junge bestand darauf, zweimal auf die Klingel zu drücken, und das ganze Wartezimmer wurde totenstill!'::text),
(401488,44610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець наполіг на тому, щоб ... на дзвінок двічі, і вся приймальня повністю затихла!'::text,'натиснути'::text,'натиснути'::text,'натиснути'::text,'Хлопець наполіг на тому, щоб натиснути на дзвінок двічі, і вся приймальня повністю затихла!'::text),
(401487,44610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El chico insistió en ... el timbre dos veces, y toda la sala de espera se quedó en completo silencio!'::text,'tocar'::text,'tocar'::text,'tocar'::text,'¡El chico insistió en tocar el timbre dos veces, y toda la sala de espera se quedó en completo silencio!'::text),
(401486,44610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon a tenu à ... deux fois sur la sonnette, et toute la salle d''attente est devenue complètement silencieuse !'::text,'appuyer'::text,'appuyer'::text,'appuyer'::text,'Le garçon a tenu à appuyer deux fois sur la sonnette, et toute la salle d''attente est devenue complètement silencieuse !'::text),
(401489,44610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk zile iki kez ... ısrar etti ve bütün bekleme salonu tamamen sustu!'::text,'basmakta'::text,'basmakta'::text,'basmakta'::text,'Çocuk zile iki kez basmakta ısrar etti ve bütün bekleme salonu tamamen sustu!'::text),
(401490,44610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú ragaszkodott hozzá, hogy kétszer ... a csengőt, és az egész váró teljesen elcsendesedett!'::text,'megnyomja'::text,'megnyomja'::text,'megnyomja'::text,'A fiú ragaszkodott hozzá, hogy kétszer megnyomja a csengőt, és az egész váró teljesen elcsendesedett!'::text),
(401493,44611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also sie meinte, der alte Mann ... seit dem Morgengrauen in dem Wartezimmer gewartet haben, er war so müde.'::text,'muss'::text,'sollte'::text,'kann nicht'::text,'Okay, also sie meinte, der alte Mann muss seit dem Morgengrauen in dem Wartezimmer gewartet haben, er war so müde.'::text),
(401497,44611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, вона сказала, що старий ... в тій приймальні з самого світанку, він був такий втомлений.'::text,'мабуть, чекав'::text,'мав би чекати'::text,'не міг чекати'::text,'Коротше, вона сказала, що старий мабуть, чекав в тій приймальні з самого світанку, він був такий втомлений.'::text),
(401496,44611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues dijo que el señor mayor ... en esa sala de espera desde el amanecer, estaba agotadísimo.'::text,'debía de llevar esperando'::text,'debería haber estado esperando'::text,'no podía llevar esperando'::text,'Vale, pues dijo que el señor mayor debía de llevar esperando en esa sala de espera desde el amanecer, estaba agotadísimo.'::text),
(401495,44611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, en gros elle a dit que le vieil homme ... dans cette salle d''attente depuis l''aube, il était trop fatigué.'::text,'devait attendre'::text,'aurait dû attendre'::text,'ne pouvait pas attendre'::text,'Bon, en gros elle a dit que le vieil homme devait attendre dans cette salle d''attente depuis l''aube, il était trop fatigué.'::text),
(401498,44611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neyse, dediğine göre yaşlı adam şafaktan beri o bekleme salonunda ..., çok yorgundu.'::text,'bekliyor olmalıymış'::text,'beklemesi gerekiyormuş'::text,'bekliyor olamazmış'::text,'Neyse, dediğine göre yaşlı adam şafaktan beri o bekleme salonunda bekliyor olmalıymış, çok yorgundu.'::text),
(401499,44611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval azt mondta, hogy az idős bácsi hajnal óta ... abban a váróban, annyira fáradt volt.'::text,'biztos várt'::text,'várnia kellett volna'::text,'biztos nem várt'::text,'Szóval azt mondta, hogy az idős bácsi hajnal óta biztos várt abban a váróban, annyira fáradt volt.'::text),
(401502,44612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, die Klinik hat das Wartezimmer letzten Monat rosa ... lassen.'::text,'streichen'::text,'streichen'::text,'streichen'::text,'Hör zu, sie hat mir erzählt, die Klinik hat das Wartezimmer letzten Monat rosa streichen lassen.'::text),
(401506,44612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що клініка минулого місяця ... приймальню в рожевий.'::text,'пофарбувала'::text,'пофарбувала'::text,'пофарбувала'::text,'Слухай, вона сказала, що клініка минулого місяця пофарбувала приймальню в рожевий.'::text),
(401505,44612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que la clínica mandó ... la sala de espera de rosa el mes pasado.'::text,'pintar'::text,'pintar'::text,'pintar'::text,'Oye, me dijo que la clínica mandó pintar la sala de espera de rosa el mes pasado.'::text),
(401504,44612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que la clinique avait fait ... la salle d''attente en rose le mois dernier.'::text,'peindre'::text,'peindre'::text,'peindre'::text,'Écoute, elle m''a dit que la clinique avait fait peindre la salle d''attente en rose le mois dernier.'::text),
(401507,44612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana kliniğin geçen ay bekleme salonunu pembeye ... söyledi.'::text,'boyattığını'::text,'boyattığını'::text,'boyattığını'::text,'Dinle, bana kliniğin geçen ay bekleme salonunu pembeye boyattığını söyledi.'::text),
(401508,44612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a klinika múlt hónapban rózsaszínre ... a várót.'::text,'festtette ki'::text,'festtette ki'::text,'festtette ki'::text,'Figyelj, azt mondta, hogy a klinika múlt hónapban rózsaszínre festtette ki a várót.'::text),
(401520,44614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wartezimmer, ... Stühle knallgelb sind, ist klein, aber sauber.'::text,'dessen'::text,'das'::text,'das'::text,'Das Wartezimmer, dessen Stühle knallgelb sind, ist klein, aber sauber.'::text),
(401524,44614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Приймальня, ... стільці яскраво-жовті, маленька, але чиста.'::text,'у якій'::text,'яка'::text,'що'::text,'Приймальня, у якій стільці яскраво-жовті, маленька, але чиста.'::text),
(401523,44614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sala de espera, ... sillas son amarillo chillón, es pequeña pero limpia.'::text,'cuyas'::text,'que'::text,'que'::text,'La sala de espera, cuyas sillas son amarillo chillón, es pequeña pero limpia.'::text),
(401522,44614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salle d''attente, ... les chaises sont jaune vif, est petite mais propre.'::text,'dont'::text,'qui'::text,'que'::text,'La salle d''attente, dont les chaises sont jaune vif, est petite mais propre.'::text),
(401525,44614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Sandalyeleri parlak sarı olan bekleme salonu küçük ama temiz.'::text,''::text,NULL::text,NULL::text,'Sandalyeleri parlak sarı olan bekleme salonu küçük ama temiz.'::text),
(401526,44614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A váró, ... székei élénksárgák, kicsi, de tiszta.'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A váró, amelynek a székei élénksárgák, kicsi, de tiszta.'::text),
(401529,44615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Wartezimmer ist ... mit einem Gehstock.'::text,'ein älterer Mann'::text,'ein älterer Mann'::text,'der ältere Mann'::text,'Im Wartezimmer ist ein älterer Mann mit einem Gehstock.'::text),
(401533,44615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У приймальні є ... з палицею.'::text,'літній чоловік'::text,'літній чоловік'::text,'літній чоловік'::text,'У приймальні є літній чоловік з палицею.'::text),
(401532,44615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la sala de espera hay ... con un bastón.'::text,'un señor mayor'::text,'un señor mayor'::text,'el señor mayor'::text,'En la sala de espera hay un señor mayor con un bastón.'::text),
(401531,44615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a ... avec une canne dans la salle d''attente.'::text,'un vieil homme'::text,'un vieil homme'::text,'le vieil homme'::text,'Il y a un vieil homme avec une canne dans la salle d''attente.'::text),
(401534,44615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekleme salonunda bastonlu ... var.'::text,'bir yaşlı adam'::text,'bir yaşlı adam'::text,'yaşlı adam'::text,'Bekleme salonunda bastonlu bir yaşlı adam var.'::text),
(401535,44615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A váróban van ... bottal.'::text,'egy idős férfi'::text,'egy idős férfi'::text,'az idős férfi'::text,'A váróban van egy idős férfi bottal.'::text),
(401538,44616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... einer 30-minütigen Verzögerung im Wartezimmer erreichte die Klinik trotzdem ihr Ziel.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz einer 30-minütigen Verzögerung im Wartezimmer erreichte die Klinik trotzdem ihr Ziel.'::text),
(401542,44616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... 30-хвилинну затримку в приймальні клініка все одно виконала свою ціль.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри 30-хвилинну затримку в приймальні клініка все одно виконала свою ціль.'::text),
(401541,44616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un retraso de 30 minutos en la sala de espera, la clínica cumplió aun así su objetivo.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de un retraso de 30 minutos en la sala de espera, la clínica cumplió aun así su objetivo.'::text),
(401540,44616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... un retard de 30 minutes dans la salle d''attente, la clinique a quand même atteint son objectif.'::text,'Malgré'::text,'Bien que'::text,'À cause d'''::text,'Malgré un retard de 30 minutes dans la salle d''attente, la clinique a quand même atteint son objectif.'::text),
(401543,44616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekleme salonundaki 30 dakikalık gecikmeye ..., klinik yine de hedefine ulaştı.'::text,'rağmen'::text,'rağmen'::text,'yüzünden'::text,'Bekleme salonundaki 30 dakikalık gecikmeye rağmen, klinik yine de hedefine ulaştı.'::text),
(401544,44616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A váróban lévő 30 perces késés ..., a klinika mégis elérte a célját.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A váróban lévő 30 perces késés ellenére, a klinika mégis elérte a célját.'::text),
(353991,39333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flammen ... schon seit einer ganzen Minute unter den Hotdogs hoch.'::text,'schlagen'::text,'schlagen'::text,'schlagen'::text,'Die Flammen schlagen schon seit einer ganzen Minute unter den Hotdogs hoch.'::text),
(353995,39333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полум''я ... під хот-догами вже цілу хвилину.'::text,'шугає'::text,'шугає'::text,'шугає'::text,'Полум''я шугає під хот-догами вже цілу хвилину.'::text),
(353994,39333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las llamas ... bajo los perritos calientes desde hace un minuto entero.'::text,'saltan'::text,'están saltando'::text,'saltan'::text,'Las llamas saltan bajo los perritos calientes desde hace un minuto entero.'::text),
(353993,39333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les flammes ... sous les hot-dogs depuis une bonne minute.'::text,'jaillissent'::text,'jaillissent'::text,'jaillissent'::text,'Les flammes jaillissent sous les hot-dogs depuis une bonne minute.'::text),
(353996,39333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alevler bir dakikadır sosisli sandviçlerin altında ...'::text,'yükseliyor'::text,'yükseliyor'::text,'yükselir'::text,'Alevler bir dakikadır sosisli sandviçlerin altında yükseliyor.'::text),
(353997,39333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lángok már egy teljes perce ... a hot dogok alatt.'::text,'csapnak fel'::text,'csapnak fel'::text,'csapnak fel'::text,'A lángok már egy teljes perce csapnak fel a hot dogok alatt.'::text),
(354000,39334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Grill ..., während er die Würstchen wendete.'::text,'ging in Flammen auf'::text,'ging gerade in Flammen auf'::text,'ist in Flammen aufgegangen'::text,'Der Grill ging in Flammen auf, während er die Würstchen wendete.'::text),
(354004,39334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гриль ... полум''ям, поки він перевертав сосиски.'::text,'спалахнув'::text,'спалахував'::text,'спалахнув'::text,'Гриль спалахнув полум''ям, поки він перевертав сосиски.'::text),
(354003,39334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La parrilla ... en llamas mientras él daba la vuelta a las salchichas.'::text,'estalló'::text,'estaba estallando'::text,'ha estallado'::text,'La parrilla estalló en llamas mientras él daba la vuelta a las salchichas.'::text),
(354002,39334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gril ... pendant qu''il retournait les saucisses.'::text,'s''est embrasé'::text,'s''embrasait'::text,'s''est embrasé'::text,'Le gril s''est embrasé pendant qu''il retournait les saucisses.'::text),
(354005,39334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sosisleri çevirirken ızgara ...'::text,'alev aldı'::text,'alev alıyordu'::text,'alev aldı'::text,'O sosisleri çevirirken ızgara alev aldı.'::text),
(354006,39334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A grill ..., miközben ő a kolbászokat forgatta.'::text,'lángra lobbant'::text,'épp lángra lobbant'::text,'lángra lobbant'::text,'A grill lángra lobbant, miközben ő a kolbászokat forgatta.'::text),
(354009,39335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... seit zehn Minuten Hotdogs durch diese Flammenwand. Alles unter Kontrolle, klar.'::text,'grillt'::text,'hat gegrillt'::text,'grillte'::text,'Er grillt seit zehn Minuten Hotdogs durch diese Flammenwand. Alles unter Kontrolle, klar.'::text),
(354013,39335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... хот-доги крізь цю стіну полум''я вже десять хвилин. Усе під контролем, звісно.'::text,'смажить'::text,'посмажив'::text,'смажив'::text,'Він смажить хот-доги крізь цю стіну полум''я вже десять хвилин. Усе під контролем, звісно.'::text),
(354012,39335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... perritos calientes a través de ese muro de llamas desde hace diez minutos. Todo bajo control, obvio.'::text,'asa'::text,'ha asado'::text,'asó'::text,'Él asa perritos calientes a través de ese muro de llamas desde hace diez minutos. Todo bajo control, obvio.'::text),
(354011,39335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ça fait dix minutes qu''il ... des hot-dogs à travers ce mur de flammes. Tout est sous contrôle, évidemment.'::text,'grille'::text,'a grillé'::text,'grillait'::text,'Ça fait dix minutes qu''il grille des hot-dogs à travers ce mur de flammes. Tout est sous contrôle, évidemment.'::text),
(354014,39335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, alev duvarının içinden sosisli sandviç ... on dakikadır. Her şey kontrol altında, tabii.'::text,'pişiriyor'::text,'pişirdi'::text,'pişirdi'::text,'O, alev duvarının içinden sosisli sandviç pişiriyor on dakikadır. Her şey kontrol altında, tabii.'::text),
(354015,39335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz perce ... hot dogokat azon a lángfalon át. Minden kontroll alatt, persze.'::text,'grillez'::text,'grillezett'::text,'grillezett'::text,'Tíz perce grillez hot dogokat azon a lángfalon át. Minden kontroll alatt, persze.'::text),
(354018,39336,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ohne Scheiß, der Marshmallow ... schon schwarz geworden, bevor die große Flamme überhaupt kam.'::text,'war'::text,'ist'::text,'wird'::text,'Bro, ohne Scheiß, der Marshmallow war schon schwarz geworden, bevor die große Flamme überhaupt kam.'::text),
(354022,39336,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, без жартів, маршмелоу ... ще до того, як з''явилося велике полум''я.'::text,'почорніло'::text,'почорніло'::text,'чорніє'::text,'Бро, без жартів, маршмелоу почорніло ще до того, як з''явилося велике полум''я.'::text),
(354021,39336,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sin mentir, el malvavisco ya se ... negro antes de que apareciera la llamarada.'::text,'había puesto'::text,'ha puesto'::text,'pone'::text,'Bro, sin mentir, el malvavisco ya se había puesto negro antes de que apareciera la llamarada.'::text),
(354020,39336,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, sans mentir, le marshmallow ... noir avant même que la grosse flamme arrive.'::text,'était devenu'::text,'est devenu'::text,'devient'::text,'Frérot, sans mentir, le marshmallow était devenu noir avant même que la grosse flamme arrive.'::text),
(354023,39336,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, yemin ederim, büyük alev daha ortaya çıkmadan marshmallow ...'::text,'kararmıştı'::text,'kararmış'::text,'kararıyor'::text,'Kanka, yemin ederim, büyük alev daha ortaya çıkmadan marshmallow kararmıştı.'::text),
(354024,39336,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, komolyan, a mályvacukor már ..., mielőtt a nagy láng egyáltalán megjelent.'::text,'megfeketedett'::text,'megfeketedett'::text,'feketedik'::text,'Tesó, komolyan, a mályvacukor már megfeketedett, mielőtt a nagy láng egyáltalán megjelent.'::text),
(354027,39337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, der Typ meinte, die Flamme ... total normal, aber alle sind irgendwie ausgeflippt.'::text,'sei'::text,'ist'::text,'wird'::text,'Alter, der Typ meinte, die Flamme sei total normal, aber alle sind irgendwie ausgeflippt.'::text),
(354031,39337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, той тип сказав, що полум''я ... абсолютно нормальне, але всі трохи офігіли.'::text,'було'::text,'є'::text,'буде'::text,'Чувак, той тип сказав, що полум''я було абсолютно нормальне, але всі трохи офігіли.'::text),
(354030,39337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el tipo dijo que la llama ... totalmente normal, pero todos flipamos un poco.'::text,'era'::text,'es'::text,'será'::text,'Tío, el tipo dijo que la llama era totalmente normal, pero todos flipamos un poco.'::text),
(354029,39337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, le gars a dit que la flamme ... totalement normale, mais tout le monde a un peu flippé.'::text,'était'::text,'est'::text,'sera'::text,'Mec, le gars a dit que la flamme était totalement normale, mais tout le monde a un peu flippé.'::text),
(354032,39337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, adam alevin tamamen normal ... söyledi ama herkes biraz panikledi.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Kanka, adam alevin tamamen normal olduğunu söyledi ama herkes biraz panikledi.'::text),
(354033,39337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a csávó azt mondta, hogy a láng teljesen normális ..., de mindenki kicsit kiakadt.'::text,'volt'::text,NULL::text,'lesz'::text,'Tesó, a csávó azt mondta, hogy a láng teljesen normális volt, de mindenki kicsit kiakadt.'::text),
(354036,39338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis 2024 ... er einen kleineren Grill, und Flammen standen nie auf der Agenda.'::text,'besaß'::text,'besaß'::text,'besaß'::text,'Bis 2024 besaß er einen kleineren Grill, und Flammen standen nie auf der Agenda.'::text),
(354040,39338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До 2024 року він ... менший гриль, і полум''я ніколи не стояло на порядку денному.'::text,'мав'::text,'мав'::text,'звик мати'::text,'До 2024 року він мав менший гриль, і полум''я ніколи не стояло на порядку денному.'::text),
(354039,39338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta 2024, ... tener una parrilla más pequeña, y las llamas nunca estuvieron en la agenda.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Hasta 2024, solía tener una parrilla más pequeña, y las llamas nunca estuvieron en la agenda.'::text),
(354038,39338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''en 2024, il ... un gril plus petit, et les flammes n''ont jamais été à l''ordre du jour.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Jusqu''en 2024, il avait un gril plus petit, et les flammes n''ont jamais été à l''ordre du jour.'::text),
(354041,39338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2024''e kadar daha küçük bir ızgarası ... ve alevler hiç gündemde değildi.'::text,'vardı'::text,'vardı'::text,'olmaya alışkındı'::text,'2024''e kadar daha küçük bir ızgarası vardı ve alevler hiç gündemde değildi.'::text),
(354042,39338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'2024-ig egy kisebb grillje ..., és a lángok sosem voltak napirenden.'::text,'volt'::text,'volt'::text,'volt'::text,'2024-ig egy kisebb grillje volt, és a lángok sosem voltak napirenden.'::text),
(354045,39339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Hotdogs ständig in der Flamme, weil Hotdogs ja heiß sein sollen.'::text,'wendet'::text,'wendet'::text,'wendet'::text,'Er wendet die Hotdogs ständig in der Flamme, weil Hotdogs ja heiß sein sollen.'::text),
(354049,39339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він усе ... хот-доги в полум''ї, бо хот-доги мають бути гарячими.'::text,'перевертає'::text,'перевертає'::text,'перевертає'::text,'Він усе перевертає хот-доги в полум''ї, бо хот-доги мають бути гарячими.'::text),
(354048,39339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él sigue ... los perritos calientes en la llama, porque los perritos calientes tienen que estar calientes.'::text,'girando'::text,'girando'::text,'girando'::text,'Él sigue girando los perritos calientes en la llama, porque los perritos calientes tienen que estar calientes.'::text),
(354047,39339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''arrête pas de ... les hot-dogs dans la flamme, parce que les hot-dogs, ça doit être chaud.'::text,'retourner'::text,'retourner'::text,'retourner'::text,'Il n''arrête pas de retourner les hot-dogs dans la flamme, parce que les hot-dogs, ça doit être chaud.'::text),
(354050,39339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sosisli sandviçleri alevin içinde ... duruyor, çünkü sosisli sandviçler sıcak olmalı.'::text,'çevirip'::text,'çevirip'::text,'çevirip'::text,'Sosisli sandviçleri alevin içinde çevirip duruyor, çünkü sosisli sandviçler sıcak olmalı.'::text),
(354051,39339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Folyton ... a hot dogokat a lángban, mert a hot dognak forrónak kell lennie.'::text,'forgatja'::text,'forgatja'::text,'forgatja'::text,'Folyton forgatja a hot dogokat a lángban, mert a hot dognak forrónak kell lennie.'::text),
(354063,39341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flammen fressen den Grill buchstäblich auf, und er ... die Würstchen, als wäre nichts passiert!'::text,'wendet immer noch'::text,'wendet immer noch'::text,'hat immer noch gewendet'::text,'Die Flammen fressen den Grill buchstäblich auf, und er wendet immer noch die Würstchen, als wäre nichts passiert!'::text),
(354067,39341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полум''я буквально пожирає гриль, а він ... сосиски, ніби нічого не сталося!'::text,'досі перевертає'::text,'досі перевертає'::text,'досі перевернув'::text,'Полум''я буквально пожирає гриль, а він досі перевертає сосиски, ніби нічого не сталося!'::text),
(354066,39341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las llamas se están comiendo literalmente la parrilla, y él ... las salchichas como si nada!'::text,'sigue girando'::text,'todavía gira'::text,'todavía ha girado'::text,'¡Las llamas se están comiendo literalmente la parrilla, y él sigue girando las salchichas como si nada!'::text),
(354065,39341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les flammes dévorent littéralement le gril, et il ... les saucisses comme si de rien n''était !'::text,'continue de retourner'::text,'retourne toujours'::text,'a toujours retourné'::text,'Les flammes dévorent littéralement le gril, et il continue de retourner les saucisses comme si de rien n''était !'::text),
(354068,39341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alevler resmen ızgarayı yiyip bitiriyor, o ise sanki hiçbir şey olmamış gibi sosisleri ...!'::text,'hâlâ çeviriyor'::text,'hâlâ çevirir'::text,'hâlâ çevirdi'::text,'Alevler resmen ızgarayı yiyip bitiriyor, o ise sanki hiçbir şey olmamış gibi sosisleri hâlâ çeviriyor!'::text),
(354069,39341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lángok szó szerint felfalják a grillt, ő meg ... a kolbászokat, mintha mi sem történt volna!'::text,'még mindig forgatja'::text,'még mindig forgatja'::text,'még mindig megforgatta'::text,'A lángok szó szerint felfalják a grillt, ő meg még mindig forgatja a kolbászokat, mintha mi sem történt volna!'::text),
(354072,39342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Verwandten ... eine Ewigkeit schweigend, bevor die Flamme endlich erlosch. Der reinste Albtraum!'::text,'starrten'::text,'starren'::text,'wurden angestarrt'::text,'Die Verwandten starrten eine Ewigkeit schweigend, bevor die Flamme endlich erlosch. Der reinste Albtraum!'::text),
(354076,39342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Родичі ... мовчки цілу вічність, перш ніж полум''я нарешті вщухло. Суцільний жах!'::text,'дивилися'::text,'дивляться'::text,'були роздивлені'::text,'Родичі дивилися мовчки цілу вічність, перш ніж полум''я нарешті вщухло. Суцільний жах!'::text),
(354075,39342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los parientes ... en silencio una eternidad antes de que la llama por fin se apagara. ¡Una pesadilla total!'::text,'habían estado mirando'::text,'han estado mirando'::text,'fueron mirados'::text,'Los parientes habían estado mirando en silencio una eternidad antes de que la llama por fin se apagara. ¡Una pesadilla total!'::text),
(354074,39342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les proches ... en silence pendant une éternité avant que la flamme ne retombe enfin. Un vrai cauchemar !'::text,'avaient regardé fixement'::text,'ont regardé fixement'::text,'ont été regardés'::text,'Les proches avaient regardé fixement en silence pendant une éternité avant que la flamme ne retombe enfin. Un vrai cauchemar !'::text),
(354077,39342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akrabalar ... sessizce, ta ki alev nihayet sönene kadar. Tam bir kâbus!'::text,'bakıp durmuştu'::text,'bakıp duruyor'::text,'bakıldı'::text,'Akrabalar bakıp durmuştu sessizce, ta ki alev nihayet sönene kadar. Tam bir kâbus!'::text),
(354078,39342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rokonok egy örökkévalóságig csendben ..., mielőtt a láng végre lelohadt. Tiszta rémálom!'::text,'bámultak'::text,'bámulnak'::text,'bámulva voltak'::text,'A rokonok egy örökkévalóságig csendben bámultak, mielőtt a láng végre lelohadt. Tiszta rémálom!'::text),
(374439,41605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen Mittag ... er in der weißen Gondel über die verschneiten Kiefern.'::text,'fährt'::text,'fährt'::text,'fährt'::text,'Morgen Mittag fährt er in der weißen Gondel über die verschneiten Kiefern.'::text),
(374443,41605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні він ... над засніженими соснами в білій гондолі.'::text,'їхатиме'::text,'поїде'::text,'їде'::text,'Завтра опівдні він їхатиме над засніженими соснами в білій гондолі.'::text),
(374442,41605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a mediodía ... sobre los pinos nevados en la góndola blanca.'::text,'estará pasando'::text,'pasará'::text,'pasa'::text,'Mañana a mediodía estará pasando sobre los pinos nevados en la góndola blanca.'::text),
(374441,41605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, il ... au-dessus des pins enneigés dans la télécabine blanche.'::text,'sera en train de passer'::text,'passera'::text,'passe'::text,'Demain à midi, il sera en train de passer au-dessus des pins enneigés dans la télécabine blanche.'::text),
(374444,41605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen beyaz gondolla karlı çamların üzerinden ...'::text,'geçiyor olacak'::text,'geçecek'::text,'geçiyor'::text,'Yarın öğlen beyaz gondolla karlı çamların üzerinden geçiyor olacak.'::text),
(374445,41605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben ... a havas fenyők fölött a fehér gondolában.'::text,'épp utazni fog'::text,'utazni fog'::text,'utazik'::text,'Holnap délben épp utazni fog a havas fenyők fölött a fehér gondolában.'::text),
(374448,41606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er glaubt, dass die Aussicht auf die Kiefern von der Bergstation aus noch besser ...'::text,'sein wird'::text,'sein wird'::text,'ist'::text,'Er glaubt, dass die Aussicht auf die Kiefern von der Bergstation aus noch besser sein wird.'::text),
(374452,41606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він думає, що вид на сосни з верхньої станції ... ще кращим.'::text,'буде'::text,'буде'::text,'є'::text,'Він думає, що вид на сосни з верхньої станції буде ще кращим.'::text),
(374451,41606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él cree que la vista de los pinos ... aún mejor desde la estación de arriba.'::text,'será'::text,'será'::text,'está siendo'::text,'Él cree que la vista de los pinos será aún mejor desde la estación de arriba.'::text),
(374450,41606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pense que la vue sur les pins ... encore meilleure depuis la station du sommet.'::text,'sera'::text,'sera'::text,'est'::text,'Il pense que la vue sur les pins sera encore meilleure depuis la station du sommet.'::text),
(374453,41606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çamların manzarasının üst istasyondan daha da güzel ... düşünüyor.'::text,'olacağını'::text,'olacağını'::text,'olduğunu'::text,'Çamların manzarasının üst istasyondan daha da güzel olacağını düşünüyor.'::text),
(374454,41606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy gondolja, hogy a fenyőkre nyíló kilátás a felső állomásról még jobb ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Úgy gondolja, hogy a fenyőkre nyíló kilátás a felső állomásról még jobb lesz.'::text),
(374457,41607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn Schnee auf Kiefern ..., sehen die irgendwie aus wie riesige Cupcakes, echt jetzt.'::text,'fällt'::text,'fiel'::text,'fallen wird'::text,'Bro, wenn Schnee auf Kiefern fällt, sehen die irgendwie aus wie riesige Cupcakes, echt jetzt.'::text),
(374461,41607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, коли на сосни ... сніг, вони такі типу гігантські кексики, реально.'::text,'падає'::text,'падав'::text,'падатиме'::text,'Бро, коли на сосни падає сніг, вони такі типу гігантські кексики, реально.'::text),
(374460,41607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, cuando ... nieve sobre los pinos, parecen como cupcakes gigantes, en serio.'::text,'cae'::text,'cayó'::text,'caerá'::text,'Bro, cuando cae nieve sobre los pinos, parecen como cupcakes gigantes, en serio.'::text),
(374459,41607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, quand la neige ... sur les pins, ils ressemblent un peu à des cupcakes géants, sérieux.'::text,'tombe'::text,'tombait'::text,'tombera'::text,'Frérot, quand la neige tombe sur les pins, ils ressemblent un peu à des cupcakes géants, sérieux.'::text),
(374462,41607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çamların üstüne kar ..., biraz dev cupcake gibi görünüyorlar, cidden.'::text,'yağarsa'::text,'yağdıysa'::text,'yağacaksa'::text,'Kanka, çamların üstüne kar yağarsa, biraz dev cupcake gibi görünüyorlar, cidden.'::text),
(374463,41607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha hó ... a fenyőkre, olyanok, mint az óriás cupcake-ek, komolyan.'::text,'esik'::text,'esett'::text,'fog esni'::text,'Tesó, ha hó esik a fenyőkre, olyanok, mint az óriás cupcake-ek, komolyan.'::text),
(374466,41608,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, wenn die Gondel jetzt stehen bleibt, ... er mit den Kiefern fest, irgendwie.'::text,'sitzt'::text,'säße'::text,'saß'::text,'Yo, wenn die Gondel jetzt stehen bleibt, sitzt er mit den Kiefern fest, irgendwie.'::text),
(374470,41608,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йоу, якщо ця гондола зараз зупиниться, він ... там із соснами, чесно кажучи.'::text,'застрягне'::text,'застряг би'::text,'застряг'::text,'Йоу, якщо ця гондола зараз зупиниться, він застрягне там із соснами, чесно кажучи.'::text),
(374469,41608,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, si esta góndola se para ahora, ... atrapado con los pinos, en plan.'::text,'se quedará'::text,'se quedaría'::text,'se quedó'::text,'Ey, si esta góndola se para ahora, se quedará atrapado con los pinos, en plan.'::text),
(374468,41608,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, si cette télécabine s''arrête maintenant, il ... coincé avec les pins, un peu.'::text,'sera'::text,'serait'::text,'était'::text,'Yo, si cette télécabine s''arrête maintenant, il sera coincé avec les pins, un peu.'::text),
(374471,41608,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, bu gondol şimdi durursa, çamlarla birlikte mahsur ..., açıkçası.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Yo, bu gondol şimdi durursa, çamlarla birlikte mahsur kalacak, açıkçası.'::text),
(374472,41608,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, ha ez a gondola most megáll, ott ... a fenyőkkel, kicsit.'::text,'ragad'::text,'ragadna'::text,'ragadt'::text,'Jó, ha ez a gondola most megáll, ott ragad a fenyőkkel, kicsit.'::text),
(374475,41609,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Resort 500 Kiefern mehr pflanzen würde, ... das Budget für die Skipiste höher.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn das Resort 500 Kiefern mehr pflanzen würde, wäre das Budget für die Skipiste höher.'::text),
(374479,41609,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби курорт посадив ще 500 сосен, бюджет лижного схилу ... вищим.'::text,'був би'::text,'буде'::text,'був'::text,'Якби курорт посадив ще 500 сосен, бюджет лижного схилу був би вищим.'::text),
(374478,41609,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la estación plantara 500 pinos más, el presupuesto de la pista ... más alto.'::text,'sería'::text,'será'::text,'era'::text,'Si la estación plantara 500 pinos más, el presupuesto de la pista sería más alto.'::text),
(374477,41609,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la station plantait 500 pins de plus, le budget de la piste ... plus élevé.'::text,'serait'::text,'sera'::text,'était'::text,'Si la station plantait 500 pins de plus, le budget de la piste serait plus élevé.'::text),
(374480,41609,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesis 500 çam daha dikseydi, kayak pistinin bütçesi daha yüksek ...'::text,'olurdu'::text,'olacak'::text,'oldu'::text,'Tesis 500 çam daha dikseydi, kayak pistinin bütçesi daha yüksek olurdu.'::text),
(374481,41609,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az üdülőhely 500-zal több fenyőt ültetne, a sípálya költségvetése magasabb ...'::text,'lenne'::text,'lesz'::text,'volt'::text,'Ha az üdülőhely 500-zal több fenyőt ültetne, a sípálya költségvetése magasabb lenne.'::text),
(374484,41610,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Kiefern ... mit Schnee bedeckt, also sind es verschneite Kiefern.'::text,'sind'::text,'bedecken'::text,'bedeckten'::text,'Diese Kiefern sind mit Schnee bedeckt, also sind es verschneite Kiefern.'::text),
(374488,41610,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці сосни ... снігом, тож це засніжені сосни.'::text,'вкриті'::text,'вкривають'::text,'вкрили'::text,'Ці сосни вкриті снігом, тож це засніжені сосни.'::text),
(374487,41610,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estos pinos ... de nieve, así que son pinos nevados.'::text,'están cubiertos'::text,'cubren'::text,'cubrieron'::text,'Estos pinos están cubiertos de nieve, así que son pinos nevados.'::text),
(374486,41610,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces pins ... de neige, donc ce sont des pins enneigés.'::text,'sont couverts'::text,'couvrent'::text,'ont couvert'::text,'Ces pins sont couverts de neige, donc ce sont des pins enneigés.'::text),
(374489,41610,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu çamlar karla ..., yani karlı çamlar.'::text,'kaplı'::text,'kaplar'::text,'kapladı'::text,'Bu çamlar karla kaplı, yani karlı çamlar.'::text),
(374490,41610,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezeket a fenyőket hó ..., tehát ezek havas fenyők.'::text,'borítja'::text,'borítja'::text,'borította'::text,'Ezeket a fenyőket hó borítja, tehát ezek havas fenyők.'::text),
(374493,41611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kiefern unter der Gondel ... von dickem Schnee niedergedrückt, wie es in dieser Höhe typisch ist.'::text,'werden'::text,'drücken'::text,'drückend'::text,'Die Kiefern unter der Gondel werden von dickem Schnee niedergedrückt, wie es in dieser Höhe typisch ist.'::text),
(374497,41611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сосни під гондолою ... товстим шаром снігу, як це типово на такій висоті.'::text,'придавлені'::text,'придавлюють'::text,'придавлюючи'::text,'Сосни під гондолою придавлені товстим шаром снігу, як це типово на такій висоті.'::text),
(374496,41611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los pinos bajo la góndola ... por la nieve espesa, como es típico a esta altitud.'::text,'están cargados'::text,'cargan'::text,'cargando'::text,'Los pinos bajo la góndola están cargados por la nieve espesa, como es típico a esta altitud.'::text),
(374495,41611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les pins sous la télécabine ... par une épaisse couche de neige, comme c''est typique à cette altitude.'::text,'sont alourdis'::text,'alourdissent'::text,'alourdissant'::text,'Les pins sous la télécabine sont alourdis par une épaisse couche de neige, comme c''est typique à cette altitude.'::text),
(374498,41611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gondolun altındaki çamlar, bu rakımda tipik olduğu üzere, kalın kar tarafından ...'::text,'aşağı bastırılıyor'::text,'aşağı bastırıyor'::text,'aşağı bastırarak'::text,'Gondolun altındaki çamlar, bu rakımda tipik olduğu üzere, kalın kar tarafından aşağı bastırılıyor.'::text),
(374499,41611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gondola alatti fenyőket vastag hó ..., ahogy az ebben a magasságban jellemző.'::text,'húzza le'::text,'lehúzza'::text,'lehúzva'::text,'A gondola alatti fenyőket vastag hó húzza le, ahogy az ebben a magasságban jellemző.'::text),
(374502,41612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... gerade den besten Tag haben; du hörst gar nicht auf, die Kiefern zu filmen.'::text,'musst'::text,'kannst nicht'::text,'solltest'::text,'Ehrlich, du musst gerade den besten Tag haben; du hörst gar nicht auf, die Kiefern zu filmen.'::text),
(374506,41612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у тебе ... найкращий день; ти не перестаєш знімати сосни.'::text,'мабуть'::text,'точно не'::text,'мав би бути'::text,'Чесно, у тебе мабуть найкращий день; ти не перестаєш знімати сосни.'::text),
(374505,41612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... estar teniendo el mejor día; no has parado de grabar los pinos.'::text,'debes de'::text,'no puedes'::text,'deberías'::text,'La verdad, debes de estar teniendo el mejor día; no has parado de grabar los pinos.'::text),
(374504,41612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... passer la meilleure journée ; tu n''as pas arrêté de filmer les pins.'::text,'dois'::text,'ne peux pas'::text,'devrais'::text,'Franchement, tu dois passer la meilleure journée ; tu n''as pas arrêté de filmer les pins.'::text),
(374507,41612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, en güzel gününü ...; çamları çekmeyi hiç bırakmadın.'::text,'yaşıyor olmalısın'::text,'yaşıyor olamazsın'::text,'yaşıyor olmalıydın'::text,'Açıkçası, en güzel gününü yaşıyor olmalısın; çamları çekmeyi hiç bırakmadın.'::text),
(374508,41612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ma ... a legjobb napod van; meg sem álltál a fenyők filmezésével.'::text,'biztos'::text,'biztos nem'::text,'kéne, hogy'::text,'Őszintén, ma biztos a legjobb napod van; meg sem álltál a fenyők filmezésével.'::text),
(374511,41613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als du gesagt hast, dass die Kiefern von hier oben fantastisch ..., hattest du so recht, ehrlich.'::text,'aussehen würden'::text,'aussehen werden'::text,'ausgesehen hätten'::text,'Als du gesagt hast, dass die Kiefern von hier oben fantastisch aussehen würden, hattest du so recht, ehrlich.'::text),
(374515,41613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти сказав, що сосни звідси, згори, ... неймовірно, ти був такий правий, чесно.'::text,'виглядатимуть'::text,'виглядатимуть'::text,'виглядали б'::text,'Коли ти сказав, що сосни звідси, згори, виглядатимуть неймовірно, ти був такий правий, чесно.'::text),
(374514,41613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando dijiste que los pinos se ... increíbles desde aquí arriba, tenías toda la razón, no te voy a mentir.'::text,'verían'::text,'verán'::text,'habrían visto'::text,'Cuando dijiste que los pinos se verían increíbles desde aquí arriba, tenías toda la razón, no te voy a mentir.'::text),
(374513,41613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand tu as dit que les pins ... incroyables d''ici, tu avais tellement raison, je vais pas mentir.'::text,'seraient'::text,'seront'::text,'auraient été'::text,'Quand tu as dit que les pins seraient incroyables d''ici, tu avais tellement raison, je vais pas mentir.'::text),
(374516,41613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çamların buradan harika ... söylediğinde çok haklıydın, yalan yok.'::text,'görüneceğini'::text,'görüneceğini'::text,'görünmüş olacağını'::text,'Çamların buradan harika görüneceğini söylediğinde çok haklıydın, yalan yok.'::text),
(374517,41613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor azt mondtad, hogy innen fentről csodásan ... a fenyők, nagyon igazad volt, nem hazudok.'::text,'fognak kinézni'::text,'fognak kinézni'::text,'néztek volna ki'::text,'Amikor azt mondtad, hogy innen fentről csodásan fognak kinézni a fenyők, nagyon igazad volt, nem hazudok.'::text),
(374529,41615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er genießt es, in der kleinen roten Seilbahn über die Kiefern zu ...'::text,'fahren'::text,'fahren'::text,'fahren'::text,'Er genießt es, in der kleinen roten Seilbahn über die Kiefern zu fahren.'::text),
(374533,41615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому подобається ... над соснами в маленькій червоній канатці.'::text,'їздити'::text,'їздити'::text,'їздити'::text,'Йому подобається їздити над соснами в маленькій червоній канатці.'::text),
(374532,41615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A él le encanta ... sobre los pinos en el pequeño teleférico rojo.'::text,'pasar'::text,'pasar'::text,'pasar'::text,'A él le encanta pasar sobre los pinos en el pequeño teleférico rojo.'::text),
(374531,41615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il adore ... au-dessus des pins dans la petite cabine rouge.'::text,'passer'::text,'passer'::text,'passer'::text,'Il adore passer au-dessus des pins dans la petite cabine rouge.'::text),
(374534,41615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük kırmızı teleferikle çamların üzerinden ... seviyor.'::text,'geçmeyi'::text,'geçmeyi'::text,'geçmeyi'::text,'Küçük kırmızı teleferikle çamların üzerinden geçmeyi seviyor.'::text),
(374535,41615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szeret ... a fenyők fölött a kis piros kabinos felvonóval.'::text,'utazni'::text,'utazni'::text,'utazni'::text,'Szeret utazni a fenyők fölött a kis piros kabinos felvonóval.'::text),
(376221,41803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Kollegen werden ihn im Meeting auch loben, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Seine Kollegen werden ihn im Meeting auch loben, oder?'::text),
(376225,41803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колеги теж похвалять його на нараді, ...?'::text,'так'::text,'так'::text,'так'::text,'Колеги теж похвалять його на нараді, так?'::text),
(376224,41803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus compañeros también lo van a elogiar en la reunión, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Sus compañeros también lo van a elogiar en la reunión, ¿verdad?'::text),
(376223,41803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses collègues vont le féliciter à la réunion aussi, ... ?'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Ses collègues vont le féliciter à la réunion aussi, n''est-ce pas ?'::text),
(376226,41803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş arkadaşları toplantıda onu da övecek, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'İş arkadaşları toplantıda onu da övecek, değil mi?'::text),
(376227,41803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kollégái is meg fogják dicsérni a megbeszélésen, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'A kollégái is meg fogják dicsérni a megbeszélésen, ugye?'::text),
(376239,41805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team ... sein Diagramm zehn Minuten lang, bevor das Budgetmeeting begann.'::text,'lobte'::text,'lobt'::text,'lobte'::text,'Das Team lobte sein Diagramm zehn Minuten lang, bevor das Budgetmeeting begann.'::text),
(376243,41805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда ... його графік десять хвилин, перш ніж почалася нарада щодо бюджету.'::text,'хвалила'::text,'хвалить'::text,'хвалила'::text,'Команда хвалила його графік десять хвилин, перш ніж почалася нарада щодо бюджету.'::text),
(376242,41805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo ... su gráfico durante diez minutos antes de que empezara la reunión de presupuesto.'::text,'había estado elogiando'::text,'ha estado elogiando'::text,'estaba elogiando'::text,'El equipo había estado elogiando su gráfico durante diez minutos antes de que empezara la reunión de presupuesto.'::text),
(376241,41805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe ... son graphique pendant dix minutes avant le début de la réunion budgétaire.'::text,'avait encensé'::text,'a encensé'::text,'encensait'::text,'L''équipe avait encensé son graphique pendant dix minutes avant le début de la réunion budgétaire.'::text),
(376244,41805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe toplantısı başlamadan önce ekip on dakika boyunca onun grafiğini ...'::text,'övüp durmuştu'::text,'övüp duruyor'::text,'övüyordu'::text,'Bütçe toplantısı başlamadan önce ekip on dakika boyunca onun grafiğini övüp durmuştu.'::text),
(376245,41805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat tíz percig ... a grafikonját, mielőtt elkezdődött a költségvetési megbeszélés.'::text,'dicsérte'::text,'dicséri'::text,'dicsérte'::text,'A csapat tíz percig dicsérte a grafikonját, mielőtt elkezdődött a költségvetési megbeszélés.'::text),
(376248,41806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Freitag wird ihn sein Manager vor dem ganzen Büro ...'::text,'gelobt haben'::text,'loben'::text,'loben'::text,'Bis Freitag wird ihn sein Manager vor dem ganzen Büro gelobt haben.'::text),
(376252,41806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До п''ятниці менеджер ... його перед усім офісом.'::text,'похвалить'::text,'похвалить'::text,'хвалитиме'::text,'До п''ятниці менеджер похвалить його перед усім офісом.'::text),
(376251,41806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el viernes, su jefe lo ... delante de toda la oficina.'::text,'habrá elogiado'::text,'elogiará'::text,'estará elogiando'::text,'Para el viernes, su jefe lo habrá elogiado delante de toda la oficina.'::text),
(376250,41806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici vendredi, son manager ... devant tout le bureau.'::text,'l''aura félicité'::text,'le félicitera'::text,'sera en train de le féliciter'::text,'D''ici vendredi, son manager l''aura félicité devant tout le bureau.'::text),
(376253,41806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cumaya kadar müdürü onu bütün ofisin önünde ...'::text,'övmüş olacak'::text,'övecek'::text,'övüyor olacak'::text,'Cumaya kadar müdürü onu bütün ofisin önünde övmüş olacak.'::text),
(376254,41806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Péntekre a főnöke ... őt az egész iroda előtt.'::text,'megdicséri'::text,'megdicséri'::text,'dicsérni fogja'::text,'Péntekre a főnöke megdicséri őt az egész iroda előtt.'::text),
(376266,41808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Diagramm abgestürzt wäre, ... ihn niemand gelobt. Das wäre ein totaler Albtraum gewesen!'::text,'hätte'::text,'würde'::text,'hat'::text,'Wenn das Diagramm abgestürzt wäre, hätte ihn niemand gelobt. Das wäre ein totaler Albtraum gewesen!'::text),
(376270,41808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби графік обвалився, ніхто ... його. Це був би повний жах!'::text,'не похвалив би'::text,'не хвалив би'::text,'не похвалив'::text,'Якби графік обвалився, ніхто не похвалив би його. Це був би повний жах!'::text),
(376269,41808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el gráfico se hubiera desplomado, ... nadie. ¡Habría sido una pesadilla total!'::text,'no lo habría elogiado'::text,'no lo elogiaría'::text,'no lo elogió'::text,'Si el gráfico se hubiera desplomado, no lo habría elogiado nadie. ¡Habría sido una pesadilla total!'::text),
(376268,41808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le graphique s''était effondré, personne ne ... : ça aurait été un vrai cauchemar !'::text,'l''aurait félicité'::text,'le féliciterait'::text,'l''a félicité'::text,'Si le graphique s''était effondré, personne ne l''aurait félicité : ça aurait été un vrai cauchemar !'::text),
(376271,41808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grafik çökseydi, kimse ... onu. Tam bir kâbus olurdu!'::text,'övmezdi'::text,'övmezdi'::text,'övmedi'::text,'Grafik çökseydi, kimse övmezdi onu. Tam bir kâbus olurdu!'::text),
(376272,41808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a grafikon összeomlott volna, senki sem ... őt. Totális rémálom lett volna!'::text,'dicsérte volna meg'::text,'dicsérné meg'::text,'dicsérte meg'::text,'Ha a grafikon összeomlott volna, senki sem dicsérte volna meg őt. Totális rémálom lett volna!'::text),
(376275,41809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie ihn nicht so laut gelobt hätte, ... er jetzt immer noch völlig unsichtbar!'::text,'wäre'::text,'wäre'::text,'wird'::text,'Wenn sie ihn nicht so laut gelobt hätte, wäre er jetzt immer noch völlig unsichtbar!'::text),
(376279,41809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не похвалила його так голосно, він і зараз ... зовсім непомітним!'::text,'досі був би'::text,'досі був би'::text,'досі буде'::text,'Якби вона не похвалила його так голосно, він і зараз досі був би зовсім непомітним!'::text),
(376278,41809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si no lo hubiera elogiado tan alto, ahora mismo ... completamente invisible!'::text,'seguiría siendo'::text,'habría seguido siendo'::text,'seguirá siendo'::text,'¡Si no lo hubiera elogiado tan alto, ahora mismo seguiría siendo completamente invisible!'::text),
(376277,41809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne l''avait pas félicité aussi fort, il ... encore complètement invisible en ce moment !'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si elle ne l''avait pas félicité aussi fort, il serait encore complètement invisible en ce moment !'::text),
(376280,41809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onu bu kadar yüksek sesle övmeseydi, şu an hâlâ tamamen görünmez ...!'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Onu bu kadar yüksek sesle övmeseydi, şu an hâlâ tamamen görünmez olurdu!'::text),
(376281,41809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem dicsérte volna meg ilyen hangosan, most is teljesen láthatatlan ...!'::text,'lenne'::text,'lett volna'::text,'lesz'::text,'Ha nem dicsérte volna meg ilyen hangosan, most is teljesen láthatatlan lenne!'::text),
(376284,41810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er soll vom ganzen Büro ... worden sein, weil er das Projekt vor der totalen Katastrophe gerettet hat!'::text,'gelobt'::text,'loben'::text,'lobend'::text,'Er soll vom ganzen Büro gelobt worden sein, weil er das Projekt vor der totalen Katastrophe gerettet hat!'::text),
(376288,41810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, що весь офіс ... його за те, що він урятував проєкт від повної катастрофи!'::text,'похвалив'::text,'хвалить'::text,'хвалить'::text,'Кажуть, що весь офіс похвалив його за те, що він урятував проєкт від повної катастрофи!'::text),
(376287,41810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dicen que ... por toda la oficina por salvar el proyecto de un desastre total!'::text,'fue elogiado'::text,'elogiar'::text,'elogiando'::text,'¡Dicen que fue elogiado por toda la oficina por salvar el proyecto de un desastre total!'::text),
(376286,41810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit qu''il ... par tout le bureau pour avoir sauvé le projet d''un désastre total !'::text,'a été félicité'::text,'félicite'::text,'félicitant'::text,'On dit qu''il a été félicité par tout le bureau pour avoir sauvé le projet d''un désastre total !'::text),
(376289,41810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Projeyi tam bir felaketten kurtardığı için bütün ofis tarafından ... söyleniyor!'::text,'övüldüğü'::text,'övdüğü'::text,'övmesi'::text,'Projeyi tam bir felaketten kurtardığı için bütün ofis tarafından övüldüğü söyleniyor!'::text),
(376290,41810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag az egész iroda ... őt, amiért megmentette a projektet a teljes katasztrófától!'::text,'megdicsérte'::text,'dicséri'::text,'dicsérve'::text,'Állítólag az egész iroda megdicsérte őt, amiért megmentette a projektet a teljes katasztrófától!'::text),
(376293,41811,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, angeblich hat sie vorgeschlagen, ihn vor dem ganzen Team zu ...'::text,'loben'::text,'loben'::text,'loben'::text,'Süße, angeblich hat sie vorgeschlagen, ihn vor dem ganzen Team zu loben.'::text),
(376297,41811,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона запропонувала ... його перед усією командою.'::text,'похвалити'::text,'похвалити'::text,'похвалити'::text,'Подруго, кажуть, вона запропонувала похвалити його перед усією командою.'::text),
(376296,41811,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que ella propuso ... delante de todo el equipo.'::text,'elogiarlo'::text,'elogiarlo'::text,'elogiarlo'::text,'Tía, parece que ella propuso elogiarlo delante de todo el equipo.'::text),
(376295,41811,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment elle a proposé de le ... devant toute l''équipe.'::text,'féliciter'::text,'féliciter'::text,'féliciter'::text,'Meuf, apparemment elle a proposé de le féliciter devant toute l''équipe.'::text),
(376298,41811,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya o, onu bütün ekibin önünde ... önermiş.'::text,'övmeyi'::text,'övmeyi'::text,'övmeyi'::text,'Kızım, güya o, onu bütün ekibin önünde övmeyi önermiş.'::text),
(376299,41811,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azt javasolta, hogy ... meg őt az egész csapat előtt.'::text,'dicsérjék'::text,'dicsérjék'::text,'dicsérjék'::text,'Csajszi, állítólag azt javasolta, hogy dicsérjék meg őt az egész csapat előtt.'::text),
(376302,41812,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Idee ... funktioniert haben, sonst hätte ihn das Team nicht gelobt.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Seine Idee muss funktioniert haben, sonst hätte ihn das Team nicht gelobt.'::text),
(376306,41812,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його ідея ..., інакше команда б його не похвалила.'::text,'напевно спрацювала'::text,'не могла спрацювати'::text,'мала б спрацювати'::text,'Його ідея напевно спрацювала, інакше команда б його не похвалила.'::text),
(376305,41812,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su idea ... funcionado, o el equipo no lo habría elogiado.'::text,'debe de haber'::text,'no puede haber'::text,'debería haber'::text,'Su idea debe de haber funcionado, o el equipo no lo habría elogiado.'::text),
(376304,41812,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son idée ... marché, sinon l''équipe ne l''aurait pas félicité.'::text,'a dû'::text,'n''a pas pu'::text,'aurait dû'::text,'Son idée a dû marché, sinon l''équipe ne l''aurait pas félicité.'::text),
(376307,41812,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun fikri ..., yoksa ekip onu övmezdi.'::text,'işe yaramış olmalı'::text,'işe yaramış olamaz'::text,'işe yaramalıydı'::text,'Onun fikri işe yaramış olmalı, yoksa ekip onu övmezdi.'::text),
(376308,41812,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ötlete ..., különben a csapat nem dicsérte volna meg.'::text,'biztosan működött'::text,'nem működhetett'::text,'működnie kellett volna'::text,'Az ötlete biztosan működött, különben a csapat nem dicsérte volna meg.'::text),
(376311,41813,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Team hat nicht nur ... sein Diagramm gelobt, sondern ihm auch applaudiert.'::text,''::text,NULL::text,NULL::text,'Das Team hat nicht nur sein Diagramm gelobt, sondern ihm auch applaudiert.'::text),
(376315,41813,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Команда не лише ... похвалила його графік, а й зааплодувала йому.'::text,''::text,NULL::text,NULL::text,'Команда не лише похвалила його графік, а й зааплодувала йому.'::text),
(376314,41813,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El equipo no solo ... elogió su gráfico, sino que también le aplaudió.'::text,''::text,NULL::text,NULL::text,'El equipo no solo elogió su gráfico, sino que también le aplaudió.'::text),
(376313,41813,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non seulement l''équipe ... a salué son graphique, mais elle l''a aussi applaudi.'::text,''::text,NULL::text,NULL::text,'Non seulement l''équipe a salué son graphique, mais elle l''a aussi applaudi.'::text),
(376316,41813,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip sadece onun grafiğini ... övmekle kalmadı, ona alkış da tuttu.'::text,''::text,NULL::text,NULL::text,'Ekip sadece onun grafiğini övmekle kalmadı, ona alkış da tuttu.'::text),
(376317,41813,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapat nemcsak ... megdicsérte a grafikonját, hanem meg is tapsolta.'::text,''::text,NULL::text,NULL::text,'A csapat nemcsak megdicsérte a grafikonját, hanem meg is tapsolta.'::text),
(364062,40452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... schon den ganzen Abend auf seinem Schoß, weil sein Schoß eben da ist, wo er war.'::text,'liegt'::text,'liegt'::text,'liegt'::text,'Der Hund liegt schon den ganzen Abend auf seinem Schoß, weil sein Schoß eben da ist, wo er war.'::text),
(364066,40452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Собака ... у нього на колінах увесь вечір, бо його коліна — там, де він був.'::text,'лежить'::text,'лежить'::text,'лежить'::text,'Собака лежить у нього на колінах увесь вечір, бо його коліна — там, де він був.'::text),
(364065,40452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... en su regazo toda la noche, porque su regazo es donde ha estado.'::text,'lleva tumbado'::text,'está tumbado'::text,'se tumba'::text,'El perro lleva tumbado en su regazo toda la noche, porque su regazo es donde ha estado.'::text),
(364064,40452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... sur ses genoux toute la soirée, parce que ses genoux, c''est là où il a été.'::text,'est couché'::text,'est couché'::text,'se couche'::text,'Le chien est couché sur ses genoux toute la soirée, parce que ses genoux, c''est là où il a été.'::text),
(364067,40452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek bütün akşam onun kucağında ..., çünkü onun kucağı köpeğin olduğu yer.'::text,'yatıyor'::text,'yatıyor'::text,'yatar'::text,'Köpek bütün akşam onun kucağında yatıyor, çünkü onun kucağı köpeğin olduğu yer.'::text),
(364068,40452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya egész este az ölében ..., mert az öle az, ahol eddig volt.'::text,'fekszik'::text,'fekszik'::text,'fekszik'::text,'A kutya egész este az ölében fekszik, mert az öle az, ahol eddig volt.'::text),
(364071,40453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann brachte den Retriever dazu, sich auf seinen Schoß zu ..., ein Verhalten, das diese Art typischerweise genießt.'::text,'legen'::text,'legen'::text,'legen'::text,'Der Mann brachte den Retriever dazu, sich auf seinen Schoß zu legen, ein Verhalten, das diese Art typischerweise genießt.'::text),
(364075,40453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік умовив ретривера ... йому на коліна — поведінка, яка зазвичай подобається цьому виду.'::text,'лягти'::text,'лягти'::text,'лягти'::text,'Чоловік умовив ретривера лягти йому на коліна — поведінка, яка зазвичай подобається цьому виду.'::text),
(364074,40453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre consiguió que el retriever se ... en su regazo, un comportamiento que la especie suele disfrutar.'::text,'tumbara'::text,'tumbara'::text,'tumbara'::text,'El hombre consiguió que el retriever se tumbara en su regazo, un comportamiento que la especie suele disfrutar.'::text),
(364073,40453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a amené le retriever à se ... sur ses genoux, un comportement que l''espèce apprécie généralement.'::text,'coucher'::text,'coucher'::text,'coucher'::text,'L''homme a amené le retriever à se coucher sur ses genoux, un comportement que l''espèce apprécie généralement.'::text),
(364076,40453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam retriever''ı kucağına ... ikna etti; bu, türün genellikle keyif aldığı bir davranıştır.'::text,'yatmaya'::text,'yatmaya'::text,'yatmaya'::text,'Adam retriever''ı kucağına yatmaya ikna etti; bu, türün genellikle keyif aldığı bir davranıştır.'::text),
(364077,40453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi rávette a retrievert, hogy ... az ölébe, ami olyan viselkedés, amelyet ez a faj jellemzően élvez.'::text,'feküdjön'::text,'feküdjön'::text,'feküdjön'::text,'A férfi rávette a retrievert, hogy feküdjön az ölébe, ami olyan viselkedés, amelyet ez a faj jellemzően élvez.'::text),
(364080,40454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünscht sich, dass dieser Hund seinen Schoß nie wieder ..., sonst bricht ihm das Herz!'::text,'verlassen würde'::text,'verlassen wird'::text,'verlässt'::text,'Er wünscht sich, dass dieser Hund seinen Schoß nie wieder verlassen würde, sonst bricht ihm das Herz!'::text),
(364084,40454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче, щоб той пес більше ніколи не ... з його колін, інакше його серце точно розіб''ється!'::text,'злазив'::text,'злізе'::text,'злазить'::text,'Він хоче, щоб той пес більше ніколи не злазив з його колін, інакше його серце точно розіб''ється!'::text),
(364083,40454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él desea que ese perro no ... nunca más de su regazo, o se le romperá el corazón por completo!'::text,'se baje'::text,'se bajará'::text,'se baja'::text,'¡Él desea que ese perro no se baje nunca más de su regazo, o se le romperá el corazón por completo!'::text),
(364082,40454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voudrait que ce chien ne ... plus jamais ses genoux, sinon son cœur va carrément se briser !'::text,'quitte'::text,'quittera'::text,'quitte'::text,'Il voudrait que ce chien ne quitte plus jamais ses genoux, sinon son cœur va carrément se briser !'::text),
(364085,40454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köpeğin kucağından bir daha asla ... istiyor, yoksa kalbi resmen paramparça olacak!'::text,'ayrılmamasını'::text,'ayrılmayacağını'::text,'ayrılmadığını'::text,'O köpeğin kucağından bir daha asla ayrılmamasını istiyor, yoksa kalbi resmen paramparça olacak!'::text),
(364086,40454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt szeretné, ha az a kutya soha többé nem ... le az öléből, különben teljesen összetörik a szíve!'::text,'szállna'::text,'fog szállni'::text,'száll'::text,'Azt szeretné, ha az a kutya soha többé nem szállna le az öléből, különben teljesen összetörik a szíve!'::text),
(364098,40456,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ist ihm auf den Schoß gesprungen, und jetzt kann er nie wieder ... gehen!'::text,'ins Bett'::text,'ins Bett'::text,'in ein Bett'::text,'Der Hund ist ihm auf den Schoß gesprungen, und jetzt kann er nie wieder ins Bett gehen!'::text),
(364102,40456,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес стрибнув йому на коліна, і тепер він більше ніколи не зможе піти ...!'::text,'спати'::text,'до ліжка'::text,'до ліжка'::text,'Пес стрибнув йому на коліна, і тепер він більше ніколи не зможе піти спати!'::text),
(364101,40456,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El perro se le subió al regazo y ahora nunca más podrá irse a ...!'::text,'la cama'::text,'la cama'::text,'una cama'::text,'¡El perro se le subió al regazo y ahora nunca más podrá irse a la cama!'::text),
(364100,40456,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien a sauté sur ses genoux, et maintenant il ne pourra plus jamais aller ... !'::text,'se coucher'::text,'au lit'::text,'dans un lit'::text,'Le chien a sauté sur ses genoux, et maintenant il ne pourra plus jamais aller se coucher !'::text),
(364103,40456,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek kucağına atladı ve artık bir daha asla ... gidemeyecek!'::text,'yatmaya'::text,'yatağa'::text,'bir yatağa'::text,'Köpek kucağına atladı ve artık bir daha asla yatmaya gidemeyecek!'::text),
(364104,40456,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya az ölébe ugrott, és most soha többé nem mehet ...!'::text,'aludni'::text,'az ágyba'::text,'egy ágyba'::text,'A kutya az ölébe ugrott, és most soha többé nem mehet aludni!'::text),
(364107,40457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Hund schwer war, ließ er ihn quer auf seinem Schoß liegen.'::text,'Obwohl'::text,'Trotz'::text,'Aufgrund'::text,'Obwohl der Hund schwer war, ließ er ihn quer auf seinem Schoß liegen.'::text),
(364111,40457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... пес був важкий, він дозволив йому лежати в себе на колінах.'::text,'Хоча'::text,'Попри'::text,'Завдяки'::text,'Хоча пес був важкий, він дозволив йому лежати в себе на колінах.'::text),
(364110,40457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el perro pesaba mucho, lo dejó tumbado sobre su regazo.'::text,'Aunque'::text,'A pesar de'::text,'Debido a'::text,'Aunque el perro pesaba mucho, lo dejó tumbado sobre su regazo.'::text),
(364109,40457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le chien soit lourd, il l''a laissé s''allonger sur ses genoux.'::text,'Bien que'::text,'Malgré'::text,'En raison de'::text,'Bien que le chien soit lourd, il l''a laissé s''allonger sur ses genoux.'::text),
(364112,40457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek ağır ..., onun kucağında boylu boyunca yatmasına izin verdi.'::text,'olsa da'::text,'olmasına rağmen'::text,'olduğu için'::text,'Köpek ağır olsa da, onun kucağında boylu boyunca yatmasına izin verdi.'::text),
(364113,40457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kutya nehéz volt, hagyta, hogy keresztben feküdjön az ölében.'::text,'Bár'::text,'Annak ellenére'::text,'Mivel'::text,'Bár a kutya nehéz volt, hagyta, hogy keresztben feküdjön az ölében.'::text),
(364116,40458,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir erzählt, er wusste, dass der Hund in der Sekunde, in der er sich hinsetzt, auf seinen Schoß ...'::text,'klettern würde'::text,'klettern wird'::text,'klettert'::text,'Hör zu, er hat mir erzählt, er wusste, dass der Hund in der Sekunde, in der er sich hinsetzt, auf seinen Schoß klettern würde.'::text),
(364120,40458,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він мені сказав, що знав: пес ... йому на коліна тієї ж секунди, як він сяде.'::text,'залізе'::text,'залізе'::text,'залазить'::text,'Слухай, він мені сказав, що знав: пес залізе йому на коліна тієї ж секунди, як він сяде.'::text),
(364119,40458,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que sabía que el perro se le ... al regazo en cuanto se sentara.'::text,'subiría'::text,'subirá'::text,'sube'::text,'Oye, me dijo que sabía que el perro se le subiría al regazo en cuanto se sentara.'::text),
(364118,40458,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il savait que le chien ... sur ses genoux à la seconde où il s''assiérait.'::text,'grimperait'::text,'grimpera'::text,'grimpe'::text,'Écoute, il m''a dit qu''il savait que le chien grimperait sur ses genoux à la seconde où il s''assiérait.'::text),
(364121,40458,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana oturduğu anda köpeğin kucağına ... bildiğini söyledi.'::text,'tırmanacağını'::text,'tırmanacağını'::text,'tırmandığını'::text,'Dinle, bana oturduğu anda köpeğin kucağına tırmanacağını bildiğini söyledi.'::text),
(364122,40458,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, tudta, hogy a kutya abban a pillanatban az ölébe ..., ahogy leül.'::text,'mászik'::text,'fog mászni'::text,'mászik'::text,'Figyelj, azt mondta, tudta, hogy a kutya abban a pillanatban az ölébe mászik, ahogy leül.'::text),
(364125,40459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... jetzt quer auf seinem Schoß, und er lächelt.'::text,'liegt'::text,'liegt'::text,'hat gelegen'::text,'Der Hund liegt jetzt quer auf seinem Schoß, und er lächelt.'::text),
(364129,40459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес зараз ... в нього на колінах, і він усміхається.'::text,'лежить'::text,'лежить'::text,'лежав'::text,'Пес зараз лежить в нього на колінах, і він усміхається.'::text),
(364128,40459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... ahora sobre su regazo, y él sonríe.'::text,'está tumbado'::text,'se tumba'::text,'ha estado tumbado'::text,'El perro está tumbado ahora sobre su regazo, y él sonríe.'::text),
(364127,40459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... maintenant en travers de ses genoux, et il sourit.'::text,'est allongé'::text,'s''allonge'::text,'a été allongé'::text,'Le chien est allongé maintenant en travers de ses genoux, et il sourit.'::text),
(364130,40459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek şimdi onun kucağında boylu boyunca ... ve o gülümsüyor.'::text,'yatıyor'::text,'yatar'::text,'yatmış'::text,'Köpek şimdi onun kucağında boylu boyunca yatıyor ve o gülümsüyor.'::text),
(364131,40459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya most keresztben ... az ölében, ő pedig mosolyog.'::text,'fekszik'::text,'fekszik'::text,'feküdt'::text,'A kutya most keresztben fekszik az ölében, ő pedig mosolyog.'::text),
(364134,40460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Decke über seinen Schoß gebreitet, bevor der Hund hochkletterte.'::text,'hatte'::text,'hat'::text,'war'::text,'Er hatte die Decke über seinen Schoß gebreitet, bevor der Hund hochkletterte.'::text),
(364138,40460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... ковдру на коліна, перш ніж пес заліз.'::text,'розстелив'::text,'розстелив'::text,'був розстелений'::text,'Він розстелив ковдру на коліна, перш ніж пес заліз.'::text),
(364137,40460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la manta sobre su regazo antes de que el perro subiera.'::text,'había extendido'::text,'ha extendido'::text,'fue extendido'::text,'Él había extendido la manta sobre su regazo antes de que el perro subiera.'::text),
(364136,40460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... la couverture sur ses genoux avant que le chien ne monte.'::text,'avait étalé'::text,'a étalé'::text,'était étalé'::text,'Il avait étalé la couverture sur ses genoux avant que le chien ne monte.'::text),
(364139,40460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpek yukarı tırmanmadan önce battaniyeyi kucağına ...'::text,'sermişti'::text,'serdi'::text,'serilmişti'::text,'Köpek yukarı tırmanmadan önce battaniyeyi kucağına sermişti.'::text),
(364140,40460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még mielőtt a kutya felmászott, ő már ... a takarót az ölére.'::text,'elterítette'::text,'elterítette'::text,'el volt terítve'::text,'Még mielőtt a kutya felmászott, ő már elterítette a takarót az ölére.'::text),
(364143,40461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In einer Minute ... der Hund auf seinem Schoß.'::text,'schläft'::text,'schläft'::text,'wird geschlafen haben'::text,'In einer Minute schläft der Hund auf seinem Schoß.'::text),
(364147,40461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'За хвилину пес уже ... в нього на колінах.'::text,'спатиме'::text,'спить'::text,'спатиме'::text,'За хвилину пес уже спатиме в нього на колінах.'::text),
(364146,40461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En un minuto, el perro ... dormido en su regazo.'::text,'estará'::text,'está siendo'::text,'habrá estado'::text,'En un minuto, el perro estará dormido en su regazo.'::text),
(364145,40461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans une minute, le chien ... endormi sur ses genoux.'::text,'sera'::text,'est en train d''être'::text,'aura été'::text,'Dans une minute, le chien sera endormi sur ses genoux.'::text),
(364148,40461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dakika içinde köpek onun kucağında uyuyor ...'::text,'olacak'::text,'oluyor'::text,'olmuş olacak'::text,'Bir dakika içinde köpek onun kucağında uyuyor olacak.'::text),
(364149,40461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy perc múlva a kutya már ... az ölében.'::text,'aludni fog'::text,'alszik'::text,'elaludt'::text,'Egy perc múlva a kutya már aludni fog az ölében.'::text),
(394203,43801,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... auf dem Sofa, als seine Freunde kamen, um ihn zu unterstützen, wie Freunde das typischerweise tun.'::text,'weinte'::text,'weinte'::text,'hat geweint'::text,'Er weinte auf dem Sofa, als seine Freunde kamen, um ihn zu unterstützen, wie Freunde das typischerweise tun.'::text),
(394207,43801,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на дивані, коли прийшли друзі, щоб підтримати його, як зазвичай роблять друзі.'::text,'плакав'::text,'заплакав'::text,'плакав'::text,'Він плакав на дивані, коли прийшли друзі, щоб підтримати його, як зазвичай роблять друзі.'::text),
(394206,43801,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... en el sofá cuando llegaron sus amigos para darle apoyo, como suelen hacer los amigos.'::text,'estaba llorando'::text,'lloró'::text,'ha llorado'::text,'Él estaba llorando en el sofá cuando llegaron sus amigos para darle apoyo, como suelen hacer los amigos.'::text),
(394205,43801,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur le canapé quand ses amis sont arrivés pour le soutenir, comme le font généralement les amis.'::text,'pleurait'::text,'a pleuré'::text,'a pleuré'::text,'Il pleurait sur le canapé quand ses amis sont arrivés pour le soutenir, comme le font généralement les amis.'::text),
(394208,43801,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları, arkadaşların genelde yaptığı gibi destek olmak için geldiğinde o kanepede ...'::text,'ağlıyordu'::text,'ağladı'::text,'ağladı'::text,'Arkadaşları, arkadaşların genelde yaptığı gibi destek olmak için geldiğinde o kanepede ağlıyordu.'::text),
(394209,43801,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a kanapén, amikor a barátai megérkeztek, hogy támogassák, ahogy a barátok általában teszik.'::text,'éppen sírt'::text,'sírt'::text,'sírt'::text,'Ő éppen sírt a kanapén, amikor a barátai megérkeztek, hogy támogassák, ahogy a barátok általában teszik.'::text),
(394212,43802,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Freunde ... ihn schon seit Stunden, und er ist immer noch völlig am Boden zerstört!'::text,'unterstützen'::text,'unterstützen'::text,'unterstützen'::text,'Seine Freunde unterstützen ihn schon seit Stunden, und er ist immer noch völlig am Boden zerstört!'::text),
(394216,43802,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі ... його вже кілька годин, а він досі геть розбитий!'::text,'підтримують'::text,'підтримують'::text,'підтримують'::text,'Друзі підтримують його вже кілька годин, а він досі геть розбитий!'::text),
(394215,43802,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sus amigos ... apoyo desde hace horas, y él sigue completamente destrozado!'::text,'le dan'::text,'le están dando'::text,'le dan'::text,'¡Sus amigos le dan apoyo desde hace horas, y él sigue completamente destrozado!'::text),
(394214,43802,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses amis le ... depuis des heures, et il a toujours le cœur complètement brisé !'::text,'soutiennent'::text,'soutiennent'::text,'soutiennent'::text,'Ses amis le soutiennent depuis des heures, et il a toujours le cœur complètement brisé !'::text),
(394217,43802,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları saatlerdir ona destek ... ve o hâlâ tamamen perişan!'::text,'oluyor'::text,'oluyor'::text,'olur'::text,'Arkadaşları saatlerdir ona destek oluyor ve o hâlâ tamamen perişan!'::text),
(394218,43802,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátai órák óta ... őt, és még mindig teljesen összetört!'::text,'támogatják'::text,'támogatják'::text,'támogatják'::text,'A barátai órák óta támogatják őt, és még mindig teljesen összetört!'::text),
(394221,43803,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... in seinen Tee, als seine Freunde mit Unterstützung kamen. Die schlimmste Nacht aller Zeiten!'::text,'weinte'::text,'weinte'::text,'hat geweint'::text,'Er weinte in seinen Tee, als seine Freunde mit Unterstützung kamen. Die schlimmste Nacht aller Zeiten!'::text),
(394225,43803,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... в чай, коли друзі прийшли з підтримкою. Найгірша ніч у житті!'::text,'плакав'::text,'заплакав'::text,'плакав'::text,'Він плакав в чай, коли друзі прийшли з підтримкою. Найгірша ніч у житті!'::text),
(394224,43803,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... en su té cuando sus amigos llegaron a apoyarlo. ¡La peor noche de la historia!'::text,'estaba llorando'::text,'lloró'::text,'ha llorado'::text,'Él estaba llorando en su té cuando sus amigos llegaron a apoyarlo. ¡La peor noche de la historia!'::text),
(394223,43803,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans son thé quand ses amis sont venus le soutenir. La pire nuit de tous les temps !'::text,'pleurait'::text,'a pleuré'::text,'a pleuré'::text,'Il pleurait dans son thé quand ses amis sont venus le soutenir. La pire nuit de tous les temps !'::text),
(394226,43803,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çayına ..., arkadaşları destek olmaya geldiğinde. Hayatının en kötü gecesi!'::text,'ağlıyordu'::text,'ağladı'::text,'ağladı'::text,'O çayına ağlıyordu, arkadaşları destek olmaya geldiğinde. Hayatının en kötü gecesi!'::text),
(394227,43803,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a teájába ..., amikor a barátai támogatni jöttek. Minden idők legrosszabb éjszakája!'::text,'épp sírt'::text,'sírt'::text,'sírt'::text,'Ő a teájába épp sírt, amikor a barátai támogatni jöttek. Minden idők legrosszabb éjszakája!'::text),
(394230,43804,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vier Freunde ... heute Abend, um ihn zu unterstützen, und das ist echt das Beste überhaupt!'::text,'kamen'::text,'kamen'::text,'kommen'::text,'Vier Freunde kamen heute Abend, um ihn zu unterstützen, und das ist echt das Beste überhaupt!'::text),
(394234,43804,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Четверо друзів ... сьогодні ввечері, щоб підтримати його, і це просто найкраще, що може бути!'::text,'прийшли'::text,'приходили'::text,'приходять'::text,'Четверо друзів прийшли сьогодні ввечері, щоб підтримати його, і це просто найкраще, що може бути!'::text),
(394233,43804,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuatro amigos ... esta noche a darle apoyo, y es lo mejor del mundo!'::text,'han venido'::text,'han estado viniendo'::text,'vienen'::text,'¡Cuatro amigos han venido esta noche a darle apoyo, y es lo mejor del mundo!'::text),
(394232,43804,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quatre amis ... ce soir pour le soutenir, et c''est carrément la meilleure chose au monde !'::text,'sont venus'::text,'sont venus'::text,'viennent'::text,'Quatre amis sont venus ce soir pour le soutenir, et c''est carrément la meilleure chose au monde !'::text),
(394235,43804,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam dört arkadaşı destek olmak için ... ve bu kesinlikle dünyanın en güzel şeyi!'::text,'geldi'::text,'gelip duruyor'::text,'geliyor'::text,'Bu akşam dört arkadaşı destek olmak için geldi ve bu kesinlikle dünyanın en güzel şeyi!'::text),
(394236,43804,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Négy barát ... ma este, hogy támogassa, és ez abszolút a legjobb dolog a világon!'::text,'eljött'::text,'jár ide'::text,'jön'::text,'Négy barát eljött ma este, hogy támogassa, és ez abszolút a legjobb dolog a világon!'::text),
(394239,43805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, er ... seinen Job verloren, kurz bevor seine Freunde mit Unterstützung aufgetaucht sind.'::text,'hatte'::text,'hat'::text,'hat'::text,'Bestie, ich hab gehört, er hatte seinen Job verloren, kurz bevor seine Freunde mit Unterstützung aufgetaucht sind.'::text),
(394243,43805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що він ... роботу якраз перед тим, як друзі прийшли його підтримати.'::text,'втратив'::text,'втратив'::text,'втрачає'::text,'Подруго, я чула, що він втратив роботу якраз перед тим, як друзі прийшли його підтримати.'::text),
(394242,43805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, oí que él ... su trabajo justo antes de que sus amigos aparecieran para apoyarlo.'::text,'había perdido'::text,'ha perdido'::text,'pierde'::text,'Amiga, oí que él había perdido su trabajo justo antes de que sus amigos aparecieran para apoyarlo.'::text),
(394241,43805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''il ... son boulot juste avant que ses amis débarquent pour le soutenir.'::text,'avait perdu'::text,'a perdu'::text,'perd'::text,'Ma belle, j''ai entendu dire qu''il avait perdu son boulot juste avant que ses amis débarquent pour le soutenir.'::text),
(394244,43805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki arkadaşları destek olmaya gelmeden hemen önce o işini ...'::text,'kaybetmişti'::text,'kaybetti'::text,'kaybediyor'::text,'Kanka, duydum ki arkadaşları destek olmaya gelmeden hemen önce o işini kaybetmişti.'::text),
(394245,43805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy ... az állását, épp mielőtt a barátai megjelentek, hogy támogassák.'::text,'elvesztette'::text,'elvesztette'::text,'elveszíti'::text,'Csajszi, azt hallottam, hogy elvesztette az állását, épp mielőtt a barátai megjelentek, hogy támogassák.'::text),
(394248,43806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er heute Abend mehr Unterstützung braucht, ... seine Freunde bei ihm.'::text,'bleiben'::text,'blieben'::text,'blieben'::text,'Wenn er heute Abend mehr Unterstützung braucht, bleiben seine Freunde bei ihm.'::text),
(394252,43806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо йому сьогодні ввечері знадобиться більше підтримки, друзі ... з ним.'::text,'залишаться'::text,'залишилися б'::text,'залишилися'::text,'Якщо йому сьогодні ввечері знадобиться більше підтримки, друзі залишаться з ним.'::text),
(394251,43806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si esta noche necesita más apoyo, sus amigos se ... con él.'::text,'quedarán'::text,'quedarían'::text,'quedaron'::text,'Si esta noche necesita más apoyo, sus amigos se quedarán con él.'::text),
(394250,43806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il a besoin de plus de soutien ce soir, ses amis ... avec lui.'::text,'resteront'::text,'resteraient'::text,'sont restés'::text,'S''il a besoin de plus de soutien ce soir, ses amis resteront avec lui.'::text),
(394253,43806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam daha fazla desteğe ihtiyacı olursa, arkadaşları onun yanında ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Bu akşam daha fazla desteğe ihtiyacı olursa, arkadaşları onun yanında kalacak.'::text),
(394254,43806,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma este több támogatásra van szüksége, a barátai vele ...'::text,'maradnak'::text,'maradnának'::text,'maradtak'::text,'Ha ma este több támogatásra van szüksége, a barátai vele maradnak.'::text),
(394257,43807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er keine Freunde hätte, ... er allein auf diesem Sofa, ganz ohne Unterstützung.'::text,'säße'::text,'sitzt'::text,'saß'::text,'Wenn er keine Freunde hätte, säße er allein auf diesem Sofa, ganz ohne Unterstützung.'::text),
(394261,43807,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби в нього не було друзів, він ... сам на тому дивані без жодної підтримки.'::text,'сидів би'::text,'сидітиме'::text,'сидів'::text,'Якби в нього не було друзів, він сидів би сам на тому дивані без жодної підтримки.'::text),
(394260,43807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no tuviera amigos, ... solo en ese sofá sin ningún apoyo.'::text,'estaría sentado'::text,'estará sentado'::text,'estaba sentado'::text,'Si no tuviera amigos, estaría sentado solo en ese sofá sin ningún apoyo.'::text),
(394259,43807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas d''amis, il ... seul sur ce canapé sans aucun soutien.'::text,'serait assis'::text,'sera assis'::text,'était assis'::text,'S''il n''avait pas d''amis, il serait assis seul sur ce canapé sans aucun soutien.'::text),
(394262,43807,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç arkadaşı olmasaydı, o kanepede hiçbir destek olmadan tek başına ...'::text,'otururdu'::text,'oturacak'::text,'oturdu'::text,'Hiç arkadaşı olmasaydı, o kanepede hiçbir destek olmadan tek başına otururdu.'::text),
(394263,43807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lennének barátai, egyedül ... azon a kanapén, mindenféle támogatás nélkül.'::text,'ülne'::text,'fog ülni'::text,'ült'::text,'Ha nem lennének barátai, egyedül ülne azon a kanapén, mindenféle támogatás nélkül.'::text),
(394266,43808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... der junge Mann von vier Freunden unterstützt.'::text,'wurde'::text,'wird'::text,'hat'::text,'Gestern Abend wurde der junge Mann von vier Freunden unterstützt.'::text),
(394270,43808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері молодому чоловікові ... підтримку четверо друзів.'::text,'надали'::text,'надають'::text,'надав'::text,'Учора ввечері молодому чоловікові надали підтримку четверо друзів.'::text),
(394269,43808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche, al joven le ... apoyo cuatro amigos.'::text,'dieron'::text,'dan'::text,'dio'::text,'Anoche, al joven le dieron apoyo cuatro amigos.'::text),
(394268,43808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, le jeune homme ... par quatre amis.'::text,'a été soutenu'::text,'est soutenu'::text,'a soutenu'::text,'Hier soir, le jeune homme a été soutenu par quatre amis.'::text),
(394271,43808,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün akşam genç adama dört arkadaşı tarafından destek ...'::text,'verildi'::text,'veriliyor'::text,'verdi'::text,'Dün akşam genç adama dört arkadaşı tarafından destek verildi.'::text),
(394272,43808,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este a fiatalembert négy barátja ...'::text,'támogatta'::text,'támogatja'::text,'támogatta'::text,'Tegnap este a fiatalembert négy barátja támogatta.'::text),
(394284,43810,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er weint in seinen Tee, also ... er heute Abend viel Unterstützung brauchen.'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Er weint in seinen Tee, also muss er heute Abend viel Unterstützung brauchen.'::text),
(394288,43810,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він плаче в чай, тож йому сьогодні ввечері ... потрібна велика підтримка.'::text,'напевно'::text,'точно не'::text,'не можна'::text,'Він плаче в чай, тож йому сьогодні ввечері напевно потрібна велика підтримка.'::text),
(394287,43810,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está llorando en su té, así que ... necesitar mucho apoyo esta noche.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Está llorando en su té, así que debe de necesitar mucho apoyo esta noche.'::text),
(394286,43810,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pleure dans son thé, donc il ... avoir besoin de beaucoup de soutien ce soir.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Il pleure dans son thé, donc il doit avoir besoin de beaucoup de soutien ce soir.'::text),
(394289,43810,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çayına ağlıyor, yani bu akşam çok desteğe ihtiyacı ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Çayına ağlıyor, yani bu akşam çok desteğe ihtiyacı olmalı.'::text),
(394290,43810,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A teájába sír, szóval ma este ... sok támogatásra van szüksége.'::text,'biztosan'::text,'biztosan nem'::text,'nem szabad, hogy'::text,'A teájába sír, szóval ma este biztosan sok támogatásra van szüksége.'::text),
(342111,38013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Was für ein Albtraum! Seine Freunde trösten ihn alle gleichzeitig, ...?'::text,'oder'::text,'oder'::text,'oder'::text,'Was für ein Albtraum! Seine Freunde trösten ihn alle gleichzeitig, oder?'::text),
(342115,38013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оце жах! Друзі втішають його всі разом, ...?'::text,'так'::text,'так'::text,'так'::text,'Оце жах! Друзі втішають його всі разом, так?'::text),
(342114,38013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué pesadilla! Sus amigos lo están consolando todos a la vez, ¿...?'::text,'verdad'::text,'verdad'::text,'verdad'::text,'¡Qué pesadilla! Sus amigos lo están consolando todos a la vez, ¿verdad?'::text),
(342113,38013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quel cauchemar ! Ses amis le consolent tous en même temps, ... ?'::text,'pas vrai'::text,'pas vrai'::text,'pas vrai'::text,'Quel cauchemar ! Ses amis le consolent tous en même temps, pas vrai ?'::text),
(342116,38013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne kâbus ama! Arkadaşları onu hep birlikte teselli ediyor, ...?'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Ne kâbus ama! Arkadaşları onu hep birlikte teselli ediyor, değil mi?'::text),
(342117,38013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Micsoda rémálom! A barátai mind egyszerre vigasztalják, ...?'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Micsoda rémálom! A barátai mind egyszerre vigasztalják, ugye?'::text),
(342129,38015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, dass seine Freunde ihn bis Mitternacht komplett ...'::text,'getröstet haben werden'::text,'trösten werden'::text,'trösten werden'::text,'Bestie, ich hab gehört, dass seine Freunde ihn bis Mitternacht komplett getröstet haben werden.'::text),
(342133,38015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що до півночі друзі повністю його ...'::text,'втішать'::text,'втішать'::text,'втішатимуть'::text,'Подруго, я чула, що до півночі друзі повністю його втішать.'::text),
(342132,38015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, oí que para medianoche sus amigos lo ... del todo.'::text,'habrán consolado'::text,'consolarán'::text,'estarán consolando'::text,'Amiga, oí que para medianoche sus amigos lo habrán consolado del todo.'::text),
(342131,38015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire que d''ici minuit, ses amis ... complètement.'::text,'l''auront consolé'::text,'le consoleront'::text,'seront en train de le consoler'::text,'Ma belle, j''ai entendu dire que d''ici minuit, ses amis l''auront consolé complètement.'::text),
(342134,38015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki gece yarısına kadar arkadaşları onu tamamen ...'::text,'teselli etmiş olacak'::text,'teselli edecek'::text,'teselli ediyor olacak'::text,'Kanka, duydum ki gece yarısına kadar arkadaşları onu tamamen teselli etmiş olacak.'::text),
(342135,38015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy éjfélre a barátai teljesen ... őt.'::text,'megvigasztalják'::text,'megvigasztalják'::text,'vigasztalni fogják'::text,'Csajszi, azt hallottam, hogy éjfélre a barátai teljesen megvigasztalják őt.'::text),
(342138,38016,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn seine Freunde nicht vorbeigekommen wären, ... ihn in dieser Nacht niemand getröstet.'::text,'hätte'::text,'würde'::text,'hat'::text,'Wenn seine Freunde nicht vorbeigekommen wären, hätte ihn in dieser Nacht niemand getröstet.'::text),
(342142,38016,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби друзі не прийшли, ніхто ... його тієї ночі.'::text,'не втішив би'::text,'не втішав би'::text,'не втішив'::text,'Якби друзі не прийшли, ніхто не втішив би його тієї ночі.'::text),
(342141,38016,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sus amigos no hubieran venido, nadie lo ... esa noche.'::text,'habría consolado'::text,'consolaría'::text,'consoló'::text,'Si sus amigos no hubieran venido, nadie lo habría consolado esa noche.'::text),
(342140,38016,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ses amis n''étaient pas passés, personne ne ... cette nuit-là.'::text,'l''aurait consolé'::text,'le consolerait'::text,'l''a consolé'::text,'Si ses amis n''étaient pas passés, personne ne l''aurait consolé cette nuit-là.'::text),
(342143,38016,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları gelmeseydi, o gece kimse onu ...'::text,'teselli etmezdi'::text,'teselli etmezdi'::text,'teselli etmedi'::text,'Arkadaşları gelmeseydi, o gece kimse onu teselli etmezdi.'::text),
(342144,38016,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a barátai nem jöttek volna át, azon az éjszakán senki sem ... őt.'::text,'vigasztalta volna meg'::text,'vigasztalná meg'::text,'vigasztalta meg'::text,'Ha a barátai nem jöttek volna át, azon az éjszakán senki sem vigasztalta volna meg őt.'::text),
(342147,38017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihn seine Freunde gestern Abend nicht getröstet hätten, ... er jetzt immer noch weinen.'::text,'würde'::text,'hätte'::text,'wird'::text,'Wenn ihn seine Freunde gestern Abend nicht getröstet hätten, würde er jetzt immer noch weinen.'::text),
(342151,38017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби друзі не втішили його вчора ввечері, він і зараз ...'::text,'досі плакав би'::text,'досі плакав би'::text,'досі плакатиме'::text,'Якби друзі не втішили його вчора ввечері, він і зараз досі плакав би.'::text),
(342150,38017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si sus amigos no lo hubieran consolado anoche, ahora ... llorando todavía.'::text,'estaría'::text,'habría estado'::text,'estará'::text,'Si sus amigos no lo hubieran consolado anoche, ahora estaría llorando todavía.'::text),
(342149,38017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ses amis ne l''avaient pas consolé hier soir, il ... encore en train de pleurer maintenant.'::text,'serait'::text,'aurait été'::text,'sera'::text,'Si ses amis ne l''avaient pas consolé hier soir, il serait encore en train de pleurer maintenant.'::text),
(342152,38017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşları dün gece onu teselli etmeseydi, şu an hâlâ ağlıyor ...'::text,'olurdu'::text,'olmuş olurdu'::text,'olacak'::text,'Arkadaşları dün gece onu teselli etmeseydi, şu an hâlâ ağlıyor olurdu.'::text),
(342153,38017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a barátai tegnap este nem vigasztalták volna meg, most is még mindig ...'::text,'sírna'::text,'sírt volna'::text,'sírni fog'::text,'Ha a barátai tegnap este nem vigasztalták volna meg, most is még mindig sírna.'::text),
(342156,38018,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er soll gestern Abend von vier Freunden gleichzeitig ...'::text,'getröstet worden sein'::text,'getröstet werden'::text,'getröstet werdend'::text,'Er soll gestern Abend von vier Freunden gleichzeitig getröstet worden sein.'::text),
(342160,38018,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, його вчора ввечері ... одразу четверо друзів.'::text,'втішили'::text,'втішають'::text,'втішали'::text,'Кажуть, його вчора ввечері втішили одразу четверо друзів.'::text),
(342159,38018,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dicen que anoche ... cuatro amigos a la vez.'::text,'lo consolaron'::text,'lo consuelan'::text,'lo estaban consolando'::text,'Dicen que anoche lo consolaron cuatro amigos a la vez.'::text),
(342158,38018,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit qu''il ... par quatre amis à la fois hier soir.'::text,'a été consolé'::text,'est consolé'::text,'étant consolé'::text,'On dit qu''il a été consolé par quatre amis à la fois hier soir.'::text),
(342161,38018,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece dört arkadaşı tarafından aynı anda ... söyleniyor.'::text,'teselli edildiği'::text,'teselli edilmesi'::text,'teselli ediliyor olduğu'::text,'Dün gece dört arkadaşı tarafından aynı anda teselli edildiği söyleniyor.'::text),
(342162,38018,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állítólag tegnap este négy barátja egyszerre ... őt.'::text,'vigasztalta'::text,'vigasztalja'::text,'vigasztalta'::text,'Állítólag tegnap este négy barátja egyszerre vigasztalta őt.'::text),
(342165,38019,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er dankte seinen Freunden dafür, dass sie ihn ..., als er so traurig war.'::text,'getröstet haben'::text,'trösten'::text,'getröstet haben'::text,'Er dankte seinen Freunden dafür, dass sie ihn getröstet haben, als er so traurig war.'::text),
(342169,38019,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він подякував друзям за те, що вони ... його, коли йому було так сумно.'::text,'втішили'::text,'втішити'::text,'втішили'::text,'Він подякував друзям за те, що вони втішили його, коли йому було так сумно.'::text),
(342168,38019,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les dio las gracias a sus amigos por ... cuando estaba tan triste.'::text,'consolarlo'::text,'consolarlo'::text,'consolarlo'::text,'Les dio las gracias a sus amigos por consolarlo cuando estaba tan triste.'::text),
(342167,38019,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a remercié ses amis de ... quand il était si triste.'::text,'l''avoir consolé'::text,'le consoler'::text,'l''avoir consolé'::text,'Il a remercié ses amis de l''avoir consolé quand il était si triste.'::text),
(342170,38019,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O çok üzgünken onu ... için arkadaşlarına teşekkür etti.'::text,'teselli ettikleri'::text,'teselli etmek'::text,'teselli ettikleri'::text,'O çok üzgünken onu teselli ettikleri için arkadaşlarına teşekkür etti.'::text),
(342171,38019,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megköszönte a barátainak, hogy ..., amikor annyira szomorú volt.'::text,'megvigasztalták'::text,'megvigasztalják'::text,'megvigasztalták'::text,'Megköszönte a barátainak, hogy megvigasztalták, amikor annyira szomorú volt.'::text),
(342183,38021,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch nie ... ich so viele Freunde gleichzeitig eine Person trösten sehen.'::text,'habe'::text,'habe'::text,'habe'::text,'Noch nie habe ich so viele Freunde gleichzeitig eine Person trösten sehen.'::text),
(342187,38021,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... стільки друзів, які одночасно втішають одну людину.'::text,'я не бачив'::text,'я не бачив'::text,'я не бачив'::text,'Ніколи я не бачив стільки друзів, які одночасно втішають одну людину.'::text),
(342186,38021,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... a tantos amigos consolar a una persona al mismo tiempo.'::text,'he visto'::text,'he visto'::text,'vi'::text,'Nunca he visto a tantos amigos consolar a una persona al mismo tiempo.'::text),
(342185,38021,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... autant d''amis consoler une seule personne en même temps.'::text,'n''ai-je vu'::text,'je n''ai vu'::text,'je ne vis'::text,'Jamais n''ai-je vu autant d''amis consoler une seule personne en même temps.'::text),
(342188,38021,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hiç bu kadar çok arkadaşın aynı anda bir kişiyi teselli ettiğini ...'::text,'görmedim'::text,'görmedim'::text,'görmedim'::text,'Hiç bu kadar çok arkadaşın aynı anda bir kişiyi teselli ettiğini görmedim.'::text),
(342189,38021,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még soha ... ennyi barátot, akik egyszerre vigasztalnak egy embert.'::text,'nem láttam'::text,'nem láttam'::text,'nem láttam'::text,'Még soha nem láttam ennyi barátot, akik egyszerre vigasztalnak egy embert.'::text),
(342192,38022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die junge Frau bringt die anderen dazu, ihn zu ..., woraufhin es zu einer Gruppenumarmung kommt.'::text,'trösten'::text,'trösten'::text,'trösten'::text,'Die junge Frau bringt die anderen dazu, ihn zu trösten, woraufhin es zu einer Gruppenumarmung kommt.'::text),
(342196,38022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молода жінка змушує інших ... його, після чого відбувається групове обійняття.'::text,'втішити'::text,'втішити'::text,'втішати'::text,'Молода жінка змушує інших втішити його, після чого відбувається групове обійняття.'::text),
(342195,38022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La joven consigue que los demás lo ..., y a continuación se produce un abrazo grupal.'::text,'consuelen'::text,'consuelen'::text,'estén consolando'::text,'La joven consigue que los demás lo consuelen, y a continuación se produce un abrazo grupal.'::text),
(342194,38022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jeune femme amène les autres à le ..., et une étreinte collective s''ensuit.'::text,'consoler'::text,'consoler'::text,'consoler'::text,'La jeune femme amène les autres à le consoler, et une étreinte collective s''ensuit.'::text),
(342197,38022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç kadın diğerlerinin onu ... sağlıyor ve ardından bir grup sarılması gerçekleşiyor.'::text,'teselli etmesini'::text,'teselli etmesini'::text,'teselli etmesini'::text,'Genç kadın diğerlerinin onu teselli etmesini sağlıyor ve ardından bir grup sarılması gerçekleşiyor.'::text),
(342198,38022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal nő ráveszi a többieket, hogy ... őt, majd csoportos ölelés következik.'::text,'vigasztalják'::text,'vigasztalják'::text,'vigasztalják'::text,'A fiatal nő ráveszi a többieket, hogy vigasztalják őt, majd csoportos ölelés következik.'::text),
(342201,38023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wünschte, er ... mit dem Weinen aufgehört, bevor alle kamen, um ihn zu trösten. Was für eine Katastrophe!'::text,'hätte'::text,'hätte'::text,'würde'::text,'Er wünschte, er hätte mit dem Weinen aufgehört, bevor alle kamen, um ihn zu trösten. Was für eine Katastrophe!'::text),
(342205,38023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він шкодує, що не ... плакати до того, як усі прийшли його втішати. Оце катастрофа!'::text,'перестав'::text,'перестав'::text,'перестане'::text,'Він шкодує, що не перестав плакати до того, як усі прийшли його втішати. Оце катастрофа!'::text),
(342204,38023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él desearía ... de llorar antes de que todos vinieran a consolarlo. ¡Qué desastre!'::text,'haber dejado'::text,'dejar'::text,'dejar'::text,'Él desearía haber dejado de llorar antes de que todos vinieran a consolarlo. ¡Qué desastre!'::text),
(342203,38023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il aimerait ... de pleurer avant que tout le monde vienne le consoler. Quelle catastrophe !'::text,'avoir arrêté'::text,'arrêter'::text,'arrêter'::text,'Il aimerait avoir arrêté de pleurer avant que tout le monde vienne le consoler. Quelle catastrophe !'::text),
(342206,38023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes onu teselli etmeye gelmeden önce ağlamayı ... diliyor. Tam bir felaket!'::text,'bırakmış olmayı'::text,'bırakmayı'::text,'bırakmayı'::text,'Herkes onu teselli etmeye gelmeden önce ağlamayı bırakmış olmayı diliyor. Tam bir felaket!'::text),
(342207,38023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt kívánja, bárcsak ... a sírást, mielőtt mindenki odajött vigasztalni. Micsoda katasztrófa!'::text,'abbahagyta volna'::text,'abbahagyná'::text,'abbahagyná'::text,'Azt kívánja, bárcsak abbahagyta volna a sírást, mielőtt mindenki odajött vigasztalni. Micsoda katasztrófa!'::text),
(344352,38262,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, der Radfahrer hat mir erzählt, die Mannschaft ... im perfekten Takt, als er vorbeifuhr.'::text,'ruderte gerade'::text,'ruderte'::text,'hat gerudert'::text,'Süße, der Radfahrer hat mir erzählt, die Mannschaft ruderte gerade im perfekten Takt, als er vorbeifuhr.'::text),
(344356,38262,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, велосипедист розповів мені, що екіпаж ... в ідеальному ритмі, коли він проїжджав повз.'::text,'веслував'::text,'веслував'::text,'веслував'::text,'Подруго, велосипедист розповів мені, що екіпаж веслував в ідеальному ритмі, коли він проїжджав повз.'::text),
(344355,38262,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el ciclista me dijo que la tripulación ... en perfecta sincronía cuando él pasó.'::text,'estaba remando'::text,'remó'::text,'ha remado'::text,'Tía, el ciclista me dijo que la tripulación estaba remando en perfecta sincronía cuando él pasó.'::text),
(344354,38262,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le cycliste m''a dit que l''équipage ... en parfaite synchronisation quand il est passé.'::text,'ramait'::text,'a ramé'::text,'a ramé'::text,'Meuf, le cycliste m''a dit que l''équipage ramait en parfaite synchronisation quand il est passé.'::text),
(344357,38262,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bisikletli bana, yanlarından geçerken ekibin mükemmel bir uyumla ... söyledi.'::text,'kürek çektiğini'::text,'kürek çektiğini'::text,'kürek çekmiş olduğunu'::text,'Kızım, bisikletli bana, yanlarından geçerken ekibin mükemmel bir uyumla kürek çektiğini söyledi.'::text),
(344358,38262,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a biciklis azt mondta, hogy a legénység tökéletes ütemben ..., amikor elhajtott mellettük.'::text,'evezett'::text,'evezett'::text,'evezett'::text,'Csajszi, a biciklis azt mondta, hogy a legénység tökéletes ütemben evezett, amikor elhajtott mellettük.'::text),
(344361,38263,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, angeblich ... diese Mannschaft seit März jeden Morgen zusammen.'::text,'trainiert'::text,'trainiert'::text,'trainiert'::text,'Bestie, angeblich trainiert diese Mannschaft seit März jeden Morgen zusammen.'::text),
(344365,38263,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, цей екіпаж ... разом щоранку ще з березня.'::text,'тренується'::text,'тренується'::text,'тренується'::text,'Подруго, кажуть, цей екіпаж тренується разом щоранку ще з березня.'::text),
(344364,38263,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que esa tripulación ... junta todas las mañanas desde marzo.'::text,'lleva entrenando'::text,'está entrenando'::text,'entrena'::text,'Amiga, parece que esa tripulación lleva entrenando junta todas las mañanas desde marzo.'::text),
(344363,38263,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment cet équipage ... ensemble tous les matins depuis mars.'::text,'s''entraîne'::text,'s''entraîne'::text,'s''entraîne'::text,'Ma belle, apparemment cet équipage s''entraîne ensemble tous les matins depuis mars.'::text),
(344366,38263,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, güya o ekip marttan beri her sabah birlikte ...'::text,'antrenman yapıyor'::text,'antrenman yapıyor'::text,'antrenman yapar'::text,'Kanka, güya o ekip marttan beri her sabah birlikte antrenman yapıyor.'::text),
(344367,38263,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az a legénység március óta minden reggel együtt ...'::text,'edz'::text,'edz'::text,'edz'::text,'Csajszi, állítólag az a legénység március óta minden reggel együtt edz.'::text),
(344379,38265,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... in dieser Saison mit dieser Mannschaft zehn Rennen gewonnen.'::text,'hast'::text,'hast'::text,'hast'::text,'Ehrlich, du hast in dieser Saison mit dieser Mannschaft zehn Rennen gewonnen.'::text),
(344383,38265,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... десять гонок із цим екіпажем цього сезону.'::text,'виграв'::text,'вигравав'::text,'виграєш'::text,'Чесно, ти виграв десять гонок із цим екіпажем цього сезону.'::text),
(344382,38265,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ... diez regatas con esta tripulación esta temporada.'::text,'has ganado'::text,'has estado ganando'::text,'estás ganando'::text,'La verdad, has ganado diez regatas con esta tripulación esta temporada.'::text),
(344381,38265,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... dix courses avec cet équipage cette saison.'::text,'as gagné'::text,'as gagné'::text,'gagnes'::text,'Franchement, tu as gagné dix courses avec cet équipage cette saison.'::text),
(344384,38265,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bu sezon bu ekiple on yarış ...'::text,'kazandın'::text,'kazanıp duruyorsun'::text,'kazanıyorsun'::text,'Açıkçası, bu sezon bu ekiple on yarış kazandın.'::text),
(344385,38265,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ebben a szezonban tíz versenyt ... ezzel a legénységgel.'::text,'nyertél'::text,'nyertél'::text,'nyersz'::text,'Őszintén, ebben a szezonban tíz versenyt nyertél ezzel a legénységgel.'::text),
(344388,38266,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du bist der Steuermann, ... Kommandos die ganze Mannschaft im Takt halten.'::text,'dessen'::text,'der'::text,'das'::text,'Ehrlich gesagt, du bist der Steuermann, dessen Kommandos die ganze Mannschaft im Takt halten.'::text),
(344392,38266,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти той стерновий, ... команди тримають увесь екіпаж у ритмі.'::text,'чиї'::text,'який'::text,'що'::text,'Не буду брехати, ти той стерновий, чиї команди тримають увесь екіпаж у ритмі.'::text),
(344391,38266,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, eres el timonel ... órdenes mantienen a toda la tripulación al compás.'::text,'cuyas'::text,'que'::text,'el cual'::text,'No te voy a mentir, eres el timonel cuyas órdenes mantienen a toda la tripulación al compás.'::text),
(344390,38266,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, t''es le barreur ... les ordres gardent tout l''équipage en rythme.'::text,'dont'::text,'qui'::text,'que'::text,'Je vais pas mentir, t''es le barreur dont les ordres gardent tout l''équipage en rythme.'::text),
(344393,38266,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, ... komutları bütün ekibi uyum içinde tutan dümenci sensin.'::text,''::text,NULL::text,NULL::text,'Yalan yok, komutları bütün ekibi uyum içinde tutan dümenci sensin.'::text),
(344394,38266,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te vagy a kormányos, ... vezényszavai az egész legénységet ütemben tartják.'::text,'akinek a'::text,'aki'::text,'ami'::text,'Nem hazudok, te vagy a kormányos, akinek a vezényszavai az egész legénységet ütemben tartják.'::text),
(344397,38267,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Acht Ruderer und ein Steuermann bilden ... dieses Boots.'::text,'die Mannschaft'::text,'eine Mannschaft'::text,'Mannschaft'::text,'Acht Ruderer und ein Steuermann bilden die Mannschaft dieses Boots.'::text),
(344401,38267,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вісім веслярів і один стерновий складають ... цього човна.'::text,'екіпаж'::text,'екіпаж'::text,'екіпаж'::text,'Вісім веслярів і один стерновий складають екіпаж цього човна.'::text),
(344400,38267,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ocho remeros y un timonel forman ... de este barco.'::text,'la tripulación'::text,'una tripulación'::text,'tripulación'::text,'Ocho remeros y un timonel forman la tripulación de este barco.'::text),
(344399,38267,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Huit rameurs et un barreur forment ... de ce bateau.'::text,'l''équipage'::text,'un équipage'::text,'équipage'::text,'Huit rameurs et un barreur forment l''équipage de ce bateau.'::text),
(344402,38267,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sekiz kürekçi ve bir dümenci bu teknenin ... oluşturuyor.'::text,'mürettebatını'::text,'bir mürettebatını'::text,'mürettebatını'::text,'Sekiz kürekçi ve bir dümenci bu teknenin mürettebatını oluşturuyor.'::text),
(344403,38267,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyolc evezős és egy kormányos alkotja ennek a hajónak ...'::text,'a legénységét'::text,'egy legénységét'::text,'legénységét'::text,'Nyolc evezős és egy kormányos alkotja ennek a hajónak a legénységét.'::text),
(344415,38269,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Start wusste die Mannschaft, dass sie an diesem Morgen schneller als je zuvor ...'::text,'rudern würde'::text,'rudern wird'::text,'gerudert ist'::text,'Am Start wusste die Mannschaft, dass sie an diesem Morgen schneller als je zuvor rudern würde.'::text),
(344419,38269,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На старті екіпаж знав, що того ранку ... швидше, ніж будь-коли.'::text,'веслуватиме'::text,'веслуватиме'::text,'веслував'::text,'На старті екіпаж знав, що того ранку веслуватиме швидше, ніж будь-коли.'::text),
(344418,38269,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la salida, la tripulación sabía que esa mañana ... más rápido que nunca.'::text,'remaría'::text,'remará'::text,'ha remado'::text,'En la salida, la tripulación sabía que esa mañana remaría más rápido que nunca.'::text),
(344417,38269,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au départ, l''équipage savait qu''il ... plus vite que jamais ce matin-là.'::text,'ramerait'::text,'ramera'::text,'a ramé'::text,'Au départ, l''équipage savait qu''il ramerait plus vite que jamais ce matin-là.'::text),
(344420,38269,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Startta ekip o sabah her zamankinden hızlı kürek ... biliyordu.'::text,'çekeceğini'::text,'çekeceğini'::text,'çektiğini'::text,'Startta ekip o sabah her zamankinden hızlı kürek çekeceğini biliyordu.'::text),
(344421,38269,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rajtnál a legénység tudta, hogy aznap reggel gyorsabban ..., mint valaha.'::text,'fog evezni'::text,'fog evezni'::text,'evezett'::text,'A rajtnál a legénység tudta, hogy aznap reggel gyorsabban fog evezni, mint valaha.'::text),
(344424,38270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die Mannschaft, als hinge ihre ganze Zukunft davon ab!'::text,'rudert'::text,'rudert'::text,'hat gerudert'::text,'Gerade rudert die Mannschaft, als hinge ihre ganze Zukunft davon ab!'::text),
(344428,38270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз екіпаж ..., ніби від цього залежить усе їхнє майбутнє!'::text,'веслує'::text,'веслує'::text,'веслував'::text,'Прямо зараз екіпаж веслує, ніби від цього залежить усе їхнє майбутнє!'::text),
(344427,38270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ahora mismo la tripulación ... como si de ello dependiera todo su futuro!'::text,'está remando'::text,'rema'::text,'ha remado'::text,'¡Ahora mismo la tripulación está remando como si de ello dependiera todo su futuro!'::text),
(344426,38270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, l''équipage ... comme si tout son avenir en dépendait !'::text,'est en train de ramer'::text,'rame'::text,'a ramé'::text,'En ce moment, l''équipage est en train de ramer comme si tout son avenir en dépendait !'::text),
(344429,38270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an ekip, sanki bütün gelecekleri buna bağlıymış gibi kürek ...!'::text,'çekiyor'::text,'çeker'::text,'çekti'::text,'Şu an ekip, sanki bütün gelecekleri buna bağlıymış gibi kürek çekiyor!'::text),
(344430,38270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most úgy ... a legénység, mintha az egész jövőjük múlna rajta!'::text,'evez'::text,'evez'::text,'evezett'::text,'Épp most úgy evez a legénység, mintha az egész jövőjük múlna rajta!'::text),
(344433,38271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mannschaft ... stundenlang gerudert, vor dieser letzten, wütenden Faust in der Luft!'::text,'hatte'::text,'hat'::text,'ist'::text,'Die Mannschaft hatte stundenlang gerudert, vor dieser letzten, wütenden Faust in der Luft!'::text),
(344437,38271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екіпаж ... годинами до того останнього, шаленого кулака в повітрі!'::text,'веслував'::text,'веслує'::text,'веслує'::text,'Екіпаж веслував годинами до того останнього, шаленого кулака в повітрі!'::text),
(344436,38271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La tripulación ... durante horas antes de ese último y furioso puño en alto!'::text,'había estado remando'::text,'ha estado remando'::text,'está remando'::text,'¡La tripulación había estado remando durante horas antes de ese último y furioso puño en alto!'::text),
(344435,38271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipage ... pendant des heures avant ce dernier poing rageur levé en l''air !'::text,'avait ramé'::text,'a ramé'::text,'rame'::text,'L''équipage avait ramé pendant des heures avant ce dernier poing rageur levé en l''air !'::text),
(344438,38271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O son, öfkeli yumruk havaya kalkmadan önce ekip saatlerdir kürek ...!'::text,'çekiyordu'::text,'çekiyor'::text,'çekiyor'::text,'O son, öfkeli yumruk havaya kalkmadan önce ekip saatlerdir kürek çekiyordu!'::text),
(344439,38271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legénység órák óta ... az utolsó, dühös, levegőbe emelt ököl előtt!'::text,'evezett'::text,'evez'::text,'evez'::text,'A legénység órák óta evezett az utolsó, dühös, levegőbe emelt ököl előtt!'::text),
(344442,38272,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... diese Mannschaft jede gegnerische Mannschaft auf dem Fluss. Totale Rache!'::text,'schlägt'::text,'schlägt'::text,'schlägt'::text,'Bis Sonnenuntergang schlägt diese Mannschaft jede gegnerische Mannschaft auf dem Fluss. Totale Rache!'::text),
(344446,38272,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця цей екіпаж ... кожен суперницький екіпаж на річці. Повна помста!'::text,'переможе'::text,'переможе'::text,'перемагає'::text,'До заходу сонця цей екіпаж переможе кожен суперницький екіпаж на річці. Повна помста!'::text),
(344445,38272,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del atardecer, esta tripulación ... a todas las tripulaciones rivales del río. ¡Venganza total!'::text,'habrá vencido'::text,'vencerá'::text,'vence'::text,'Antes del atardecer, esta tripulación habrá vencido a todas las tripulaciones rivales del río. ¡Venganza total!'::text),
(344444,38272,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, cet équipage ... tous les équipages rivaux sur la rivière. Vengeance totale !'::text,'aura battu'::text,'battra'::text,'bat'::text,'D''ici le coucher du soleil, cet équipage aura battu tous les équipages rivaux sur la rivière. Vengeance totale !'::text),
(344447,38272,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar bu ekip ... nehirdeki bütün rakip ekipleri. Tam bir intikam!'::text,'yenmiş olacak'::text,'yenecek'::text,'yeniyor'::text,'Gün batımına kadar bu ekip yenmiş olacak nehirdeki bütün rakip ekipleri. Tam bir intikam!'::text),
(344448,38272,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtára ez a legénység ... a folyó összes rivális legénységét. Totális bosszú!'::text,'legyőzi'::text,'legyőzi'::text,'legyőzi'::text,'Napnyugtára ez a legénység legyőzi a folyó összes rivális legénységét. Totális bosszú!'::text),
(341121,37903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, ich hab gehört, die Mannschaft ... sich schon vom Ufer abgestoßen, bevor sie überhaupt das erste Kommando gab.'::text,'hatte'::text,'hat'::text,'hat'::text,'Süße, ich hab gehört, die Mannschaft hatte sich schon vom Ufer abgestoßen, bevor sie überhaupt das erste Kommando gab.'::text),
(341125,37903,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що екіпаж ... від берега ще до того, як вона дала першу команду.'::text,'відштовхнувся'::text,'відштовхнувся'::text,'відштовхується'::text,'Подруго, я чула, що екіпаж відштовхнувся від берега ще до того, як вона дала першу команду.'::text)
