from (values
(341124,37903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, oí que la tripulación ya ... antes de que ella diera la primera orden.'::text,'había zarpado'::text,'ha zarpado'::text,'zarpa'::text,'Tía, oí que la tripulación ya había zarpado antes de que ella diera la primera orden.'::text),
(341123,37903,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, j''ai entendu dire que l''équipage ... avant même qu''elle donne le premier ordre.'::text,'était parti'::text,'est parti'::text,'part'::text,'Meuf, j''ai entendu dire que l''équipage était parti avant même qu''elle donne le premier ordre.'::text),
(341126,37903,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki o daha ilk komutu vermeden ekip kıyıdan ...'::text,'ayrılmıştı'::text,'ayrıldı'::text,'ayrılıyor'::text,'Kızım, duydum ki o daha ilk komutu vermeden ekip kıyıdan ayrılmıştı.'::text),
(341127,37903,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy a legénység már ..., mielőtt ő kiadta volna az első vezényszót.'::text,'ellökte magát a parttól'::text,'ellökte magát a parttól'::text,'ellöki magát a parttól'::text,'Csajszi, azt hallottam, hogy a legénység már ellökte magát a parttól, mielőtt ő kiadta volna az első vezényszót.'::text),
(341139,37905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich ein Kommando so lässig rufen könnte wie du, ... ich auch eine Mannschaft.'::text,'leitete'::text,'leite'::text,'leite'::text,'Wenn ich ein Kommando so lässig rufen könnte wie du, leitete ich auch eine Mannschaft.'::text),
(341143,37905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я вмів вигукувати команду так само круто, як ти, я теж ... екіпаж.'::text,'вів би'::text,'поведу'::text,'веду'::text,'Якби я вмів вигукувати команду так само круто, як ти, я теж вів би екіпаж.'::text),
(341142,37905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si pudiera gritar una orden tan fluida como la tuya, yo también ... una tripulación.'::text,'dirigiría'::text,'dirigiré'::text,'dirijo'::text,'Si pudiera gritar una orden tan fluida como la tuya, yo también dirigiría una tripulación.'::text),
(341141,37905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si je pouvais crier un ordre aussi fluide que toi, je ... un équipage, moi aussi.'::text,'dirigerais'::text,'dirigerai'::text,'dirige'::text,'Si je pouvais crier un ordre aussi fluide que toi, je dirigerais un équipage, moi aussi.'::text),
(341144,37905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin kadar akıcı bir komut bağırabilseydim, ben de bir ekibi ...'::text,'yönetirdim'::text,'yöneteceğim'::text,'yönetiyorum'::text,'Senin kadar akıcı bir komut bağırabilseydim, ben de bir ekibi yönetirdim.'::text),
(341145,37905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha olyan lazán tudnék vezényszót kiáltani, mint te, én is ... egy legénységet.'::text,'vezetnék'::text,'vezetni fogok'::text,'vezetek'::text,'Ha olyan lazán tudnék vezényszót kiáltani, mint te, én is vezetnék egy legénységet.'::text),
(341148,37906,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... jedes Kommando in voller Lautstärke gebrüllt. Sehr entspannend, klar.'::text,'wurde'::text,'wird'::text,'hat'::text,'Heute Morgen wurde jedes Kommando in voller Lautstärke gebrüllt. Sehr entspannend, klar.'::text),
(341152,37906,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці кожну команду ... на повну гучність. Дуже розслабляє, звісно.'::text,'вигукували'::text,'вигукують'::text,'вигукнула'::text,'Сьогодні вранці кожну команду вигукували на повну гучність. Дуже розслабляє, звісно.'::text),
(341151,37906,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana, cada orden ... a todo volumen. Muy relajante, obvio.'::text,'se gritó'::text,'se grita'::text,'gritó'::text,'Esta mañana, cada orden se gritó a todo volumen. Muy relajante, obvio.'::text),
(341150,37906,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, chaque ordre ... à plein volume. Très reposant, évidemment.'::text,'a été crié'::text,'est crié'::text,'a crié'::text,'Ce matin, chaque ordre a été crié à plein volume. Très reposant, évidemment.'::text),
(341153,37906,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah her komut ... son ses. Çok rahatlatıcı, tabii.'::text,'bağırıldı'::text,'bağırılıyor'::text,'bağırdı'::text,'Bu sabah her komut bağırıldı son ses. Çok rahatlatıcı, tabii.'::text),
(341154,37906,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel minden vezényszót ... teljes hangerővel. Nagyon pihentető, persze.'::text,'kiabáltak'::text,'kiabálnak'::text,'kiabált'::text,'Ma reggel minden vezényszót kiabáltak teljes hangerővel. Nagyon pihentető, persze.'::text),
(341157,37907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Steuerfrau ... jedes Kommando über das Mikrofon ihres Headsets.'::text,'gibt'::text,'bekommt'::text,'gebend'::text,'Die Steuerfrau gibt jedes Kommando über das Mikrofon ihres Headsets.'::text),
(341161,37907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стернова ... кожну команду через мікрофон гарнітури.'::text,'дає'::text,'отримує'::text,'даючи'::text,'Стернова дає кожну команду через мікрофон гарнітури.'::text),
(341160,37907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La timonel ... cada orden por el micrófono del casco.'::text,'da'::text,'recibe'::text,'dando'::text,'La timonel da cada orden por el micrófono del casco.'::text),
(341159,37907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La barreuse ... chaque ordre dans le micro de son casque.'::text,'donne'::text,'reçoit'::text,'donnant'::text,'La barreuse donne chaque ordre dans le micro de son casque.'::text),
(341162,37907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dümenci her komutu başlığının mikrofonundan ...'::text,'veriyor'::text,'alıyor'::text,'vererek'::text,'Dümenci her komutu başlığının mikrofonundan veriyor.'::text),
(341163,37907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kormányos minden vezényszót a headset mikrofonján keresztül ...'::text,'ad ki'::text,'kap'::text,'kiadva'::text,'A kormányos minden vezényszót a headset mikrofonján keresztül ad ki.'::text),
(341166,37908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Mannschaft bewegt sich im perfekten Takt, also ... sie jedes Kommando klar hören.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Die Mannschaft bewegt sich im perfekten Takt, also muss sie jedes Kommando klar hören.'::text),
(341170,37908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екіпаж рухається в ідеальному ритмі, тож вони ... кожну команду чітко.'::text,'напевно чують'::text,'можливо, чують'::text,'не можуть чути'::text,'Екіпаж рухається в ідеальному ритмі, тож вони напевно чують кожну команду чітко.'::text),
(341169,37908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tripulación se mueve en perfecta sincronía, así que ... oír cada orden con claridad.'::text,'deben de'::text,'podrían'::text,'no pueden'::text,'La tripulación se mueve en perfecta sincronía, así que deben de oír cada orden con claridad.'::text),
(341168,37908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipage bouge en parfaite synchronisation, donc ils ... entendre chaque ordre clairement.'::text,'doivent'::text,'pourraient'::text,'ne peuvent pas'::text,'L''équipage bouge en parfaite synchronisation, donc ils doivent entendre chaque ordre clairement.'::text),
(341171,37908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip mükemmel bir uyumla hareket ediyor, yani her komutu net bir şekilde ...'::text,'duyuyor olmalı'::text,'duyuyor olabilir'::text,'duyuyor olamaz'::text,'Ekip mükemmel bir uyumla hareket ediyor, yani her komutu net bir şekilde duyuyor olmalı.'::text),
(341172,37908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legénység tökéletes ütemben mozog, szóval ... tisztán hallanak minden vezényszót.'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'A legénység tökéletes ütemben mozog, szóval biztosan tisztán hallanak minden vezényszót.'::text),
(341175,37909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jake ist der Ruderer, für ... das Kommando gedacht ist.'::text,'den'::text,'das'::text,'dessen'::text,'Jake ist der Ruderer, für den das Kommando gedacht ist.'::text),
(341179,37909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Джейк — це веслувальник, для ... призначена ця команда.'::text,'якого'::text,'якого'::text,'чий'::text,'Джейк — це веслувальник, для якого призначена ця команда.'::text),
(341178,37909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jake es el remero para ... es la orden.'::text,'quien'::text,'el cual'::text,'cuyo'::text,'Jake es el remero para quien es la orden.'::text),
(341177,37909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jake est le rameur à ... l''ordre est destiné.'::text,'qui'::text,'laquelle'::text,'dont'::text,'Jake est le rameur à qui l''ordre est destiné.'::text),
(341180,37909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jake, ... komutun kendisi için verildiği kürekçi.'::text,''::text,NULL::text,NULL::text,'Jake, komutun kendisi için verildiği kürekçi.'::text),
(341181,37909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jake az az evezős, ... a vezényszó szól.'::text,'akinek'::text,'aminek'::text,'akinek a'::text,'Jake az az evezős, akinek a vezényszó szól.'::text),
(341184,37910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schrie, die Mannschaft ... ihrem Kommando folgen oder alles verlieren!'::text,'müsse'::text,'muss'::text,'muss'::text,'Sie schrie, die Mannschaft müsse ihrem Kommando folgen oder alles verlieren!'::text),
(341188,37910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кричала, що екіпаж ... виконати її команду, інакше втратить усе!'::text,'мусив'::text,'мусить'::text,'мусить'::text,'Вона кричала, що екіпаж мусив виконати її команду, інакше втратить усе!'::text),
(341187,37910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que la tripulación ... seguir su orden o lo perdería todo!'::text,'tenía que'::text,'tiene que'::text,'debe'::text,'¡Gritó que la tripulación tenía que seguir su orden o lo perdería todo!'::text),
(341186,37910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a hurlé que l''équipage ... suivre son ordre ou tout perdre !'::text,'devait'::text,'doit'::text,'doit'::text,'Elle a hurlé que l''équipage devait suivre son ordre ou tout perdre !'::text),
(341189,37910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekibin komutuna ..., yoksa her şeyi kaybedeceğini haykırdı!'::text,'uymak zorunda olduğunu'::text,'uymak zorunda olduğunu'::text,'uyması gerektiğini'::text,'Ekibin komutuna uymak zorunda olduğunu, yoksa her şeyi kaybedeceğini haykırdı!'::text),
(341190,37910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt üvöltötte, hogy a legénységnek ... a vezényszavát, különben mindent elveszít!'::text,'követnie kellett'::text,'követnie kell'::text,'követnie kell'::text,'Azt üvöltötte, hogy a legénységnek követnie kellett a vezényszavát, különben mindent elveszít!'::text),
(341193,37911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Wintermorgen ... sie dasselbe Kommando, bis die Mannschaft zusammenbrach!'::text,'brüllte'::text,'brüllte'::text,'brüllte'::text,'Jeden Wintermorgen brüllte sie dasselbe Kommando, bis die Mannschaft zusammenbrach!'::text),
(341197,37911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щозимового ранку вона ... ту саму команду, поки екіпаж не падав без сил!'::text,'вигукувала'::text,'вигукувала'::text,'звикла вигукувати'::text,'Щозимового ранку вона вигукувала ту саму команду, поки екіпаж не падав без сил!'::text),
(341196,37911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada mañana de invierno ... la misma orden hasta que la tripulación se derrumbaba!'::text,'gritaba'::text,'solía gritar'::text,'estaba acostumbrada a gritar'::text,'¡Cada mañana de invierno gritaba la misma orden hasta que la tripulación se derrumbaba!'::text),
(341195,37911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque matin d''hiver, elle ... le même ordre jusqu''à ce que l''équipage s''effondre !'::text,'criait'::text,'avait l''habitude de crier'::text,'était habituée à crier'::text,'Chaque matin d''hiver, elle criait le même ordre jusqu''à ce que l''équipage s''effondre !'::text),
(341198,37911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her kış sabahı ekip yığılıp kalana kadar aynı komutu ...!'::text,'bağırırdı'::text,'bağırırdı'::text,'bağırmaya alışkındı'::text,'Her kış sabahı ekip yığılıp kalana kadar aynı komutu bağırırdı!'::text),
(341199,37911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden téli reggel ugyanazt a vezényszót ..., amíg a legénység össze nem esett!'::text,'kiabálta'::text,'kiabálta'::text,'megszokta kiabálni'::text,'Minden téli reggel ugyanazt a vezényszót kiabálta, amíg a legénység össze nem esett!'::text),
(341202,37912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, Jake hat mir gesagt, er hat es satt, jeden Morgen dasselbe Kommando zu ...'::text,'hören'::text,'hören'::text,'hören'::text,'Bestie, Jake hat mir gesagt, er hat es satt, jeden Morgen dasselbe Kommando zu hören.'::text),
(341206,37912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, Джейк сказав мені, що втомився ... ту саму команду щоранку.'::text,'слухати'::text,'слухати'::text,'слухати'::text,'Подруго, Джейк сказав мені, що втомився слухати ту саму команду щоранку.'::text),
(341205,37912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, Jake me dijo que está harto de ... la misma orden cada mañana.'::text,'oír'::text,'oír'::text,'oír'::text,'Amiga, Jake me dijo que está harto de oír la misma orden cada mañana.'::text),
(341204,37912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, Jake m''a dit qu''il en a marre ... le même ordre tous les matins.'::text,'d''entendre'::text,'d''entendre'::text,'d''entendre'::text,'Ma belle, Jake m''a dit qu''il en a marre d''entendre le même ordre tous les matins.'::text),
(341207,37912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, Jake bana her sabah aynı komutu ... bıktığını söyledi.'::text,'duymaktan'::text,'duymaktan'::text,'duymaktan'::text,'Kanka, Jake bana her sabah aynı komutu duymaktan bıktığını söyledi.'::text),
(341208,37912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, Jake azt mondta, elege van abból, hogy minden reggel ugyanazt a vezényszót ...'::text,'hallja'::text,'hallja'::text,'hallja'::text,'Csajszi, Jake azt mondta, elege van abból, hogy minden reggel ugyanazt a vezényszót hallja.'::text),
(364458,40496,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das riesige Gesetzbuch zum Rednerpult und legte es ab. Ein winziges Büchlein, klar.'::text,'trug'::text,'trug gerade'::text,'hat getragen'::text,'Sie trug das riesige Gesetzbuch zum Rednerpult und legte es ab. Ein winziges Büchlein, klar.'::text),
(364462,40496,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... величезну книгу законів до кафедри й поклала її. Крихітна книжечка, звісно.'::text,'віднесла'::text,'несла'::text,'віднесла'::text,'Вона віднесла величезну книгу законів до кафедри й поклала її. Крихітна книжечка, звісно.'::text),
(364461,40496,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el enorme libro de leyes hasta el atril y lo dejó. Un librito diminuto, obvio.'::text,'llevó'::text,'estaba llevando'::text,'ha llevado'::text,'Ella llevó el enorme libro de leyes hasta el atril y lo dejó. Un librito diminuto, obvio.'::text),
(364460,40496,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... l''énorme livre de lois jusqu''au pupitre et l''a posé. Un tout petit livre, évidemment.'::text,'a porté'::text,'portait'::text,'a porté'::text,'Elle a porté l''énorme livre de lois jusqu''au pupitre et l''a posé. Un tout petit livre, évidemment.'::text),
(364463,40496,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, dev kanun kitabını kürsüye ... ve bıraktı. Minicik bir kitap, tabii.'::text,'taşıdı'::text,'taşıyordu'::text,'taşıdı'::text,'O, dev kanun kitabını kürsüye taşıdı ve bıraktı. Minicik bir kitap, tabii.'::text),
(364464,40496,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a hatalmas törvénykönyvet a pulthoz, és letette. Egy apró kis könyv, persze.'::text,'vitte'::text,'épp vitte'::text,'vitte'::text,'Ő vitte a hatalmas törvénykönyvet a pulthoz, és letette. Egy apró kis könyv, persze.'::text),
(364467,40497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Gesetz ... seit Jahrhunderten unverändert. Ein sehr modernes Dokument, eindeutig.'::text,'ist'::text,'bleibt'::text,'blieb'::text,'Dieses Gesetz ist seit Jahrhunderten unverändert. Ein sehr modernes Dokument, eindeutig.'::text),
(364471,40497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей закон ... незмінним уже багато століть. Дуже сучасний документ, очевидно.'::text,'лишається'::text,'лишається'::text,'лишався'::text,'Цей закон лишається незмінним уже багато століть. Дуже сучасний документ, очевидно.'::text),
(364470,40497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta ley ... sin cambios durante siglos. Un documento modernísimo, claramente.'::text,'ha seguido'::text,'ha estado siguiendo'::text,'siguió'::text,'Esta ley ha seguido sin cambios durante siglos. Un documento modernísimo, claramente.'::text),
(364469,40497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette loi ... inchangée depuis des siècles. Un document très moderne, clairement.'::text,'est restée'::text,'reste'::text,'est restée'::text,'Cette loi est restée inchangée depuis des siècles. Un document très moderne, clairement.'::text),
(364473,40497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a törvény évszázadok óta ... változatlan. Nagyon modern dokumentum, egyértelműen.'::text,'maradt'::text,'marad'::text,'maradt'::text,'Ez a törvény évszázadok óta maradt változatlan. Nagyon modern dokumentum, egyértelműen.'::text),
(364476,40498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kinder ... schon angefangen zu singen, bevor sie das Gesetzbuch öffnete.'::text,'hatten'::text,'haben'::text,'haben'::text,'Die Kinder hatten schon angefangen zu singen, bevor sie das Gesetzbuch öffnete.'::text),
(364480,40498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Діти ... співати ще до того, як вона відкрила книгу законів.'::text,'почали'::text,'почали'::text,'починають'::text,'Діти почали співати ще до того, як вона відкрила книгу законів.'::text),
(364479,40498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los niños ... a cantar antes de que ella abriera el libro de leyes.'::text,'habían empezado'::text,'han empezado'::text,'empiezan'::text,'Los niños habían empezado a cantar antes de que ella abriera el libro de leyes.'::text),
(364478,40498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les enfants ... à chanter avant qu''elle ouvre le livre de lois.'::text,'avaient commencé'::text,'ont commencé'::text,'commencent'::text,'Les enfants avaient commencé à chanter avant qu''elle ouvre le livre de lois.'::text),
(364481,40498,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kanun kitabını açmadan önce çocuklar şarkı söylemeye ...'::text,'başlamıştı'::text,'başladı'::text,'başlıyor'::text,'O kanun kitabını açmadan önce çocuklar şarkı söylemeye başlamıştı.'::text),
(364482,40498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyerekek már ... énekelni, mielőtt kinyitotta a törvénykönyvet.'::text,'elkezdtek'::text,'elkezdtek'::text,'elkezdenek'::text,'A gyerekek már elkezdtek énekelni, mielőtt kinyitotta a törvénykönyvet.'::text),
(364485,40499,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie die Seiten zu schnell umblättert, ... das alte Gesetz beschädigt.'::text,'wird'::text,'würde'::text,'wurde'::text,'Wenn sie die Seiten zu schnell umblättert, wird das alte Gesetz beschädigt.'::text),
(364489,40499,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона гортатиме сторінки занадто швидко, старий закон ... пошкоджено.'::text,'буде'::text,'було б'::text,'було'::text,'Якщо вона гортатиме сторінки занадто швидко, старий закон буде пошкоджено.'::text),
(364488,40499,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si pasa las páginas demasiado rápido, la vieja ley ...'::text,'se dañará'::text,'se dañaría'::text,'se dañó'::text,'Si pasa las páginas demasiado rápido, la vieja ley se dañará.'::text),
(364487,40499,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle tourne les pages trop vite, la vieille loi ... abîmée.'::text,'sera'::text,'serait'::text,'a été'::text,'Si elle tourne les pages trop vite, la vieille loi sera abîmée.'::text),
(364490,40499,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sayfaları çok hızlı çevirirse, eski kanun ...'::text,'zarar görecek'::text,'zarar görürdü'::text,'zarar gördü'::text,'Sayfaları çok hızlı çevirirse, eski kanun zarar görecek.'::text),
(364491,40499,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha túl gyorsan lapoz, a régi törvény ...'::text,'megsérül'::text,'megsérülne'::text,'megsérült'::text,'Ha túl gyorsan lapoz, a régi törvény megsérül.'::text),
(364503,40501,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Gesetz ... vor Jahrhunderten von Hand geschrieben, und ein einziger Tropfen Tee könnte es zerstören!'::text,'wurde'::text,'schrieb'::text,'wird'::text,'Dieses Gesetz wurde vor Jahrhunderten von Hand geschrieben, und ein einziger Tropfen Tee könnte es zerstören!'::text),
(364507,40501,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей закон ... від руки багато століть тому, і одна крапля чаю може його знищити!'::text,'написали'::text,'написав'::text,'пишуть'::text,'Цей закон написали від руки багато століть тому, і одна крапля чаю може його знищити!'::text),
(364506,40501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta ley ... a mano hace siglos, y una sola gota de té podría destruirla!'::text,'fue escrita'::text,'escribió'::text,'es escrita'::text,'¡Esta ley fue escrita a mano hace siglos, y una sola gota de té podría destruirla!'::text),
(364505,40501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette loi ... à la main il y a des siècles, et une seule goutte de thé pourrait la détruire !'::text,'a été écrite'::text,'a écrit'::text,'est écrite'::text,'Cette loi a été écrite à la main il y a des siècles, et une seule goutte de thé pourrait la détruire !'::text),
(364508,40501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kanun yüzyıllar önce elle ... ve tek bir damla çay onu mahvedebilir!'::text,'yazıldı'::text,'yazdı'::text,'yazılıyor'::text,'Bu kanun yüzyıllar önce elle yazıldı ve tek bir damla çay onu mahvedebilir!'::text),
(364509,40501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezt a törvényt évszázadokkal ezelőtt kézzel ..., és egyetlen csepp tea tönkreteheti!'::text,'írták'::text,'írta'::text,'írják'::text,'Ezt a törvényt évszázadokkal ezelőtt kézzel írták, és egyetlen csepp tea tönkreteheti!'::text),
(364512,40502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau mit den Handschuhen ... das Gesetzbuch auf, und der ganze Saal hielt den Atem an!'::text,'schlug'::text,'wurde geschlagen'::text,'schlagend'::text,'Die Frau mit den Handschuhen schlug das Gesetzbuch auf, und der ganze Saal hielt den Atem an!'::text),
(364516,40502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка в рукавичках ... книгу законів, і вся зала затамувала подих!'::text,'розгорнула'::text,'була розгорнута'::text,'розгортаючи'::text,'Жінка в рукавичках розгорнула книгу законів, і вся зала затамувала подих!'::text),
(364515,40502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La mujer de los guantes ... el libro de leyes, y toda la sala contuvo la respiración!'::text,'abrió'::text,'fue abierta'::text,'abriendo'::text,'¡La mujer de los guantes abrió el libro de leyes, y toda la sala contuvo la respiración!'::text),
(364514,40502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme gantée ... le livre de lois, et toute la salle a retenu son souffle !'::text,'a ouvert'::text,'a été ouverte'::text,'ouvrant'::text,'La femme gantée a ouvert le livre de lois, et toute la salle a retenu son souffle !'::text),
(364517,40502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eldivenli kadın kanun kitabını ... ve bütün salon nefesini tuttu!'::text,'açtı'::text,'açıldı'::text,'açarak'::text,'Eldivenli kadın kanun kitabını açtı ve bütün salon nefesini tuttu!'::text),
(364518,40502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kesztyűs nő ... a törvénykönyvet, és az egész terem visszatartotta a lélegzetét!'::text,'kinyitotta'::text,'ki lett nyitva'::text,'kinyitva'::text,'A kesztyűs nő kinyitotta a törvénykönyvet, és az egész terem visszatartotta a lélegzetét!'::text),
(364521,40503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemand fasst es ohne Handschuhe an! Dieses Gesetz ... nicht einfach irgendein gewöhnliches Dokument sein!'::text,'kann'::text,'darf'::text,'sollte'::text,'Niemand fasst es ohne Handschuhe an! Dieses Gesetz kann nicht einfach irgendein gewöhnliches Dokument sein!'::text),
(364525,40503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не торкається його без рукавичок! Цей закон ... бути просто якимось звичайним документом!'::text,'не може'::text,'не повинен'::text,'не мав би'::text,'Ніхто не торкається його без рукавичок! Цей закон не може бути просто якимось звичайним документом!'::text),
(364524,40503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nadie lo toca sin guantes! ¡Esta ley ... ser un documento cualquiera!'::text,'no puede'::text,'no debe'::text,'no debería'::text,'¡Nadie lo toca sin guantes! ¡Esta ley no puede ser un documento cualquiera!'::text),
(364523,40503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne n''y touche sans gants ! Cette loi ne ... pas être un simple document ordinaire !'::text,'peut'::text,'doit'::text,'devrait'::text,'Personne n''y touche sans gants ! Cette loi ne peut pas être un simple document ordinaire !'::text),
(364526,40503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse ona eldivensiz dokunmuyor! Bu kanun sıradan bir belge ...!'::text,'olamaz'::text,'olmamalı'::text,'olmamalı'::text,'Kimse ona eldivensiz dokunmuyor! Bu kanun sıradan bir belge olamaz!'::text),
(364527,40503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki nem nyúl hozzá kesztyű nélkül! Ez a törvény ... csak egy közönséges dokumentum!'::text,'nem lehet'::text,'nem szabad, hogy legyen'::text,'nem kéne, hogy legyen'::text,'Senki nem nyúl hozzá kesztyű nélkül! Ez a törvény nem lehet csak egy közönséges dokumentum!'::text),
(364530,40504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, die Frau, ... das Gesetzbuch getragen hat, hat mir gesagt, dass es eine Tonne wiegt.'::text,'die'::text,'was'::text,'deren'::text,'Bestie, die Frau, die das Gesetzbuch getragen hat, hat mir gesagt, dass es eine Tonne wiegt.'::text),
(364534,40504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, жінка, ... несла книгу законів, сказала мені, що вона важить тонну.'::text,'яка'::text,'що'::text,'чия'::text,'Подруго, жінка, яка несла книгу законів, сказала мені, що вона важить тонну.'::text),
(364533,40504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, la mujer ... llevó el libro de leyes me dijo que pesa una tonelada.'::text,'que'::text,'la cual'::text,'cuya'::text,'Amiga, la mujer que llevó el libro de leyes me dijo que pesa una tonelada.'::text),
(364532,40504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, la femme ... a porté le livre de lois m''a dit qu''il pèse une tonne.'::text,'qui'::text,'que'::text,'dont'::text,'Ma belle, la femme qui a porté le livre de lois m''a dit qu''il pèse une tonne.'::text),
(364535,40504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... kanun kitabını taşıyan kadın bana kitabın bir ton olduğunu söyledi.'::text,''::text,NULL::text,NULL::text,'Kanka, kanun kitabını taşıyan kadın bana kitabın bir ton olduğunu söyledi.'::text),
(364536,40504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a nő, ... a törvénykönyvet vitte, azt mondta, hogy egy tonna.'::text,'aki'::text,'ami'::text,'akinek a'::text,'Csajszi, a nő, aki a törvénykönyvet vitte, azt mondta, hogy egy tonna.'::text),
(364539,40505,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, sie ... nach dem Lied das ganze Gesetz laut vorlesen.'::text,'würde'::text,'wird'::text,'ist'::text,'Hör zu, sie hat gesagt, sie würde nach dem Lied das ganze Gesetz laut vorlesen.'::text),
(364543,40505,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що після пісні ... весь закон уголос.'::text,'прочитає'::text,'прочитає'::text,'читає'::text,'Слухай, вона сказала, що після пісні прочитає весь закон уголос.'::text),
(364542,40505,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, dijo que ... toda la ley en voz alta después de la canción.'::text,'leería'::text,'leerá'::text,'está leyendo'::text,'Oye, dijo que leería toda la ley en voz alta después de la canción.'::text),
(364541,40505,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit qu''elle ... toute la loi à voix haute après la chanson.'::text,'lirait'::text,'lira'::text,'lit'::text,'Écoute, elle a dit qu''elle lirait toute la loi à voix haute après la chanson.'::text),
(364544,40505,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, şarkıdan sonra bütün kanunu yüksek sesle ... söyledi.'::text,'okuyacağını'::text,'okuyacağını'::text,NULL::text,'Dinle, şarkıdan sonra bütün kanunu yüksek sesle okuyacağını söyledi.'::text),
(364545,40505,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a dal után hangosan ... az egész törvényt.'::text,'fel fogja olvasni'::text,'fel fogja olvasni'::text,NULL::text,'Figyelj, azt mondta, hogy a dal után hangosan fel fogja olvasni az egész törvényt.'::text),
(364548,40506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Süße, angeblich ... dieses Gesetzbuch mal einem Sultan.'::text,'gehörte'::text,'gehörte'::text,'gehörte'::text,'Süße, angeblich gehörte dieses Gesetzbuch mal einem Sultan.'::text),
(364552,40506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, ця книга законів колись ... султанові.'::text,'належала'::text,'належала'::text,'звикла належати'::text,'Подруго, кажуть, ця книга законів колись належала султанові.'::text),
(364551,40506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que este libro de leyes ... pertenecer a un sultán.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Tía, parece que este libro de leyes solía pertenecer a un sultán.'::text),
(364550,40506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ce livre de lois ... à un sultan.'::text,'appartenait'::text,'appartenait'::text,'avait l''habitude d''appartenir'::text,'Meuf, apparemment ce livre de lois appartenait à un sultan.'::text),
(364553,40506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, güya bu kanun kitabı eskiden bir sultana ...'::text,'aitmiş'::text,'aitmiş'::text,'ait olmaya alışkınmış'::text,'Kızım, güya bu kanun kitabı eskiden bir sultana aitmiş.'::text),
(364554,40506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag ez a törvénykönyv régen egy szultáné ...'::text,'volt'::text,'volt'::text,'volt'::text,'Csajszi, állítólag ez a törvénykönyv régen egy szultáné volt.'::text),
(342966,38108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du schwörst, dass du nur noch zehn Arbeiten ..., und ehrlich, ich glaub dir.'::text,'korrigieren wirst'::text,'korrigieren wirst'::text,'korrigierst'::text,'Du schwörst, dass du nur noch zehn Arbeiten korrigieren wirst, und ehrlich, ich glaub dir.'::text),
(342970,38108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти присягаєшся, що ... лише ще десять робіт, і чесно, я тобі вірю.'::text,'перевіриш'::text,'перевірятимеш'::text,'перевіряєш'::text,'Ти присягаєшся, що перевіриш лише ще десять робіт, і чесно, я тобі вірю.'::text),
(342969,38108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Juras que solo ... diez exámenes más, y la verdad, te creo.'::text,'corregirás'::text,'estarás corrigiendo'::text,'estás corrigiendo'::text,'Juras que solo corregirás diez exámenes más, y la verdad, te creo.'::text),
(342968,38108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu jures que tu ... seulement dix copies de plus, et franchement, je te crois.'::text,'corrigeras'::text,'seras en train de corriger'::text,'corriges'::text,'Tu jures que tu corrigeras seulement dix copies de plus, et franchement, je te crois.'::text),
(342971,38108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sadece on kâğıt daha ... yemin ediyorsun ve açıkçası sana inanıyorum.'::text,'kontrol edeceğine'::text,'kontrol ediyor olacağına'::text,'kontrol ettiğine'::text,'Sadece on kâğıt daha kontrol edeceğine yemin ediyorsun ve açıkçası sana inanıyorum.'::text),
(342972,38108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megesküszöl, hogy már csak tíz dolgozatot ..., és őszintén, hiszek neked.'::text,'javítasz ki'::text,'fogsz javítani'::text,'javítasz'::text,'Megesküszöl, hogy már csak tíz dolgozatot javítasz ki, és őszintén, hiszek neked.'::text),
(342975,38109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie eine Arbeit ..., landen zwei weitere auf dem Stapel. Makelloses System.'::text,'korrigiert'::text,'korrigierte'::text,'korrigieren wird'::text,'Wenn sie eine Arbeit korrigiert, landen zwei weitere auf dem Stapel. Makelloses System.'::text),
(342979,38109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вона ... одну роботу, на купу падають ще дві. Бездоганна система.'::text,'перевіряє'::text,'перевірила'::text,'перевірить'::text,'Коли вона перевіряє одну роботу, на купу падають ще дві. Бездоганна система.'::text),
(342978,38109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella ... un examen, caen dos más en la pila. Sistema impecable.'::text,'corrige'::text,'corrigió'::text,'corregirá'::text,'Si ella corrige un examen, caen dos más en la pila. Sistema impecable.'::text),
(342977,38109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle ... une copie, deux autres atterrissent sur la pile. Système parfait.'::text,'corrige'::text,'a corrigé'::text,'corrigera'::text,'Quand elle corrige une copie, deux autres atterrissent sur la pile. Système parfait.'::text),
(342980,38109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir kâğıdı ..., yığına iki tane daha geliyor. Kusursuz sistem.'::text,'kontrol ettiğinde'::text,'kontrol ettiyse'::text,'kontrol edecek olursa'::text,'Bir kâğıdı kontrol ettiğinde, yığına iki tane daha geliyor. Kusursuz sistem.'::text),
(342981,38109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ... egy dolgozatot, két újabb landol a kupacon. Hibátlan rendszer.'::text,'kijavít'::text,'kijavított'::text,'ki fog javítani'::text,'Ha kijavít egy dolgozatot, két újabb landol a kupacon. Hibátlan rendszer.'::text),
(342984,38110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat in einer Stunde nur drei Arbeiten korrigiert, ...? Toller Fortschritt.'::text,'oder'::text,'oder'::text,'oder'::text,'Sie hat in einer Stunde nur drei Arbeiten korrigiert, oder? Toller Fortschritt.'::text),
(342988,38110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона за годину перевірила лише три роботи, ...? Чудовий прогрес.'::text,'так'::text,'так'::text,'так'::text,'Вона за годину перевірила лише три роботи, так? Чудовий прогрес.'::text),
(342987,38110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Solo ha corregido tres exámenes en una hora, ¿...? Gran progreso.'::text,'verdad'::text,'verdad'::text,'verdad'::text,'Solo ha corregido tres exámenes en una hora, ¿verdad? Gran progreso.'::text),
(342986,38110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''a corrigé que trois copies en une heure, ... ? Beau progrès.'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'n''est-ce pas'::text,'Elle n''a corrigé que trois copies en une heure, n''est-ce pas ? Beau progrès.'::text),
(342989,38110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saatte sadece üç kâğıt kontrol etti, ...? Harika ilerleme.'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'Bir saatte sadece üç kâğıt kontrol etti, değil mi? Harika ilerleme.'::text),
(342990,38110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy óra alatt csak három dolgozatot javított ki, ...? Szép haladás.'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Egy óra alatt csak három dolgozatot javított ki, ugye? Szép haladás.'::text),
(342993,38111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat noch nicht mal die Hälfte der Arbeiten korrigiert, und ...'::text,'ihr Kollege auch nicht'::text,'ihr Kollege auch nicht'::text,'ihr Kollege schon'::text,'Sie hat noch nicht mal die Hälfte der Arbeiten korrigiert, und ihr Kollege auch nicht.'::text),
(342997,38111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ще не перевірила й половини робіт, і ...'::text,'її колега теж ні'::text,'її колега теж ні'::text,'її колега теж'::text,'Вона ще не перевірила й половини робіт, і її колега теж ні.'::text),
(342996,38111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todavía no ha corregido ni la mitad de los exámenes, y ...'::text,'su compañero tampoco'::text,'su compañero tampoco'::text,'su compañero también'::text,'Todavía no ha corregido ni la mitad de los exámenes, y su compañero tampoco.'::text),
(342995,38111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''a pas encore corrigé la moitié des copies, et ...'::text,'son collègue non plus'::text,'son collègue non plus'::text,'son collègue aussi'::text,'Elle n''a pas encore corrigé la moitié des copies, et son collègue non plus.'::text),
(342998,38111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâğıtların yarısını bile henüz kontrol etmedi, ...'::text,'meslektaşı da etmedi'::text,'meslektaşı da etmedi'::text,'meslektaşı etti'::text,'Kâğıtların yarısını bile henüz kontrol etmedi, meslektaşı da etmedi.'::text),
(342999,38111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még a dolgozatok felét sem javította ki, és ...'::text,'a kollégája sem'::text,'a kollégája sem'::text,'a kollégája is'::text,'Még a dolgozatok felét sem javította ki, és a kollégája sem.'::text),
(343011,38113,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie früher angefangen hätte, ... sie alle Arbeiten vor dem Ergebnistermin korrigiert.'::text,'hätte'::text,'würde'::text,'hat'::text,'Wenn sie früher angefangen hätte, hätte sie alle Arbeiten vor dem Ergebnistermin korrigiert.'::text),
(343015,38113,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона почала раніше, то ... всі роботи ще до терміну результатів.'::text,'перевірила б'::text,'перевіряла б'::text,'перевірила'::text,'Якби вона почала раніше, то перевірила б всі роботи ще до терміну результатів.'::text),
(343014,38113,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera empezado antes, ... todos los exámenes antes de la fecha de los resultados.'::text,'habría corregido'::text,'corregiría'::text,'corrigió'::text,'Si hubiera empezado antes, habría corregido todos los exámenes antes de la fecha de los resultados.'::text),
(343013,38113,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle avait commencé plus tôt, elle ... toutes les copies avant la date des résultats.'::text,'aurait corrigé'::text,'corrigerait'::text,'a corrigé'::text,'Si elle avait commencé plus tôt, elle aurait corrigé toutes les copies avant la date des résultats.'::text),
(343016,38113,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha erken başlasaydı, sonuç tarihinden önce bütün kâğıtları kontrol ...'::text,'etmiş olurdu'::text,'ederdi'::text,'etti'::text,'Daha erken başlasaydı, sonuç tarihinden önce bütün kâğıtları kontrol etmiş olurdu.'::text),
(343017,38113,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha korábban kezdte volna, az eredmények határideje előtt ... az összes dolgozatot.'::text,'kijavította volna'::text,'kijavítaná'::text,'kijavította'::text,'Ha korábban kezdte volna, az eredmények határideje előtt kijavította volna az összes dolgozatot.'::text),
(343020,38114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Chef erinnerte sie daran, alle 400 Arbeiten bis zur Deadline zu ...'::text,'korrigieren'::text,'korrigieren'::text,'korrigieren'::text,'Ihr Chef erinnerte sie daran, alle 400 Arbeiten bis zur Deadline zu korrigieren.'::text),
(343024,38114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Шеф нагадав їй ... всі 400 робіт до дедлайну.'::text,'перевірити'::text,'перевірку'::text,'перевірені'::text,'Шеф нагадав їй перевірити всі 400 робіт до дедлайну.'::text),
(343023,38114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su jefe le recordó ... los 400 exámenes antes de la fecha límite.'::text,'corregir'::text,'corregir'::text,'corregidos'::text,'Su jefe le recordó corregir los 400 exámenes antes de la fecha límite.'::text),
(343022,38114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son chef lui a rappelé de ... les 400 copies avant la date limite.'::text,'corriger'::text,'corriger'::text,'corrigées'::text,'Son chef lui a rappelé de corriger les 400 copies avant la date limite.'::text),
(343025,38114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patronu ona 400 kâğıdın hepsini son teslim tarihine kadar ... hatırlattı.'::text,'kontrol etmesini'::text,'kontrol etmesini'::text,'kontrol edilmiş'::text,'Patronu ona 400 kâğıdın hepsini son teslim tarihine kadar kontrol etmesini hatırlattı.'::text),
(343026,38114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A főnöke emlékeztette, hogy mind a 400 dolgozatot ... a határidőig.'::text,'javítsa ki'::text,'javítsa ki'::text,'kijavítva'::text,'A főnöke emlékeztette, hogy mind a 400 dolgozatot javítsa ki a határidőig.'::text),
(343029,38115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jede Woche mehr Arbeiten korrigieren sollen; jetzt türmen sich die Stapel über ihr.'::text,'hätte'::text,'muss'::text,'kann nicht'::text,'Sie hätte jede Woche mehr Arbeiten korrigieren sollen; jetzt türmen sich die Stapel über ihr.'::text),
(343033,38115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй ... перевіряти більше робіт щотижня; тепер купи височіють над нею.'::text,'слід було'::text,'напевно, довелося'::text,'не могла'::text,'Їй слід було перевіряти більше робіт щотижня; тепер купи височіють над нею.'::text),
(343032,38115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... corregido más exámenes cada semana; ahora las pilas se alzan sobre ella.'::text,'Debería haber'::text,'Debe de haber'::text,'No puede haber'::text,'Debería haber corregido más exámenes cada semana; ahora las pilas se alzan sobre ella.'::text),
(343031,38115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... corriger plus de copies chaque semaine ; maintenant les piles la dominent.'::text,'aurait dû'::text,'a dû'::text,'n''a pas pu'::text,'Elle aurait dû corriger plus de copies chaque semaine ; maintenant les piles la dominent.'::text),
(343034,38115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her hafta daha fazla kâğıt kontrol ...; şimdi yığınlar tepesinde yükseliyor.'::text,'etmeliydi'::text,'etmiş olmalı'::text,'etmiş olamaz'::text,'Her hafta daha fazla kâğıt kontrol etmeliydi; şimdi yığınlar tepesinde yükseliyor.'::text),
(343035,38115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden héten több dolgozatot ... kijavítania; most a kupacok tornyosulnak fölötte.'::text,'kellett volna'::text,'kellett'::text,'nem kellett'::text,'Minden héten több dolgozatot kellett volna kijavítania; most a kupacok tornyosulnak fölötte.'::text),
(343038,38116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bemerkenswerterweise lässt die Dozentin keine einzige Arbeit von einem Assistenten ...'::text,'korrigieren'::text,'korrigieren'::text,'korrigiert'::text,'Bemerkenswerterweise lässt die Dozentin keine einzige Arbeit von einem Assistenten korrigieren.'::text),
(343042,38116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Примітно, що викладачка не доручає асистентові ... жодної роботи.'::text,'перевіряти'::text,'перевіряти'::text,'перевірену'::text,'Примітно, що викладачка не доручає асистентові перевіряти жодної роботи.'::text),
(343041,38116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Curiosamente, la profesora no hace que un asistente ... ninguno de los exámenes.'::text,'corrija'::text,'corrija'::text,'corregido'::text,'Curiosamente, la profesora no hace que un asistente corrija ninguno de los exámenes.'::text),
(343040,38116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fait remarquable, la chargée de cours ne fait ... aucune des copies par un assistant.'::text,'corriger'::text,'corriger'::text,'corrigées'::text,'Fait remarquable, la chargée de cours ne fait corriger aucune des copies par un assistant.'::text),
(343043,38116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlginç bir şekilde, öğretim görevlisi kâğıtların hiçbirini bir asistana ...'::text,'kontrol ettirmiyor'::text,'kontrol ettirmiyor'::text,'kontrol edilmiş'::text,'İlginç bir şekilde, öğretim görevlisi kâğıtların hiçbirini bir asistana kontrol ettirmiyor.'::text),
(343044,38116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelemre méltó, hogy az oktató egyetlen dolgozatot sem ... ki asszisztenssel.'::text,'javíttat'::text,'javíttat'::text,'kijavítva'::text,'Figyelemre méltó, hogy az oktató egyetlen dolgozatot sem javíttat ki asszisztenssel.'::text),
(343047,38117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... stundenlang Arbeiten korrigiert, als du dich endlich zurückgelehnt hast. Respekt.'::text,'hattest'::text,'hast'::text,'hast'::text,'Du hattest stundenlang Arbeiten korrigiert, als du dich endlich zurückgelehnt hast. Respekt.'::text),
(343051,38117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... роботи годинами, коли нарешті відкинулася на спинку. Респект.'::text,'перевіряла'::text,'перевіряла'::text,'перевіряєш'::text,'Ти перевіряла роботи годинами, коли нарешті відкинулася на спинку. Респект.'::text),
(343050,38117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... exámenes durante horas cuando por fin te recostaste. Respeto.'::text,'Habías estado corrigiendo'::text,'Has estado corrigiendo'::text,'Estás corrigiendo'::text,'Habías estado corrigiendo exámenes durante horas cuando por fin te recostaste. Respeto.'::text),
(343049,38117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... des copies depuis des heures quand tu t''es enfin adossée. Respect.'::text,'corrigeais'::text,'corriges'::text,'corriges'::text,'Tu corrigeais des copies depuis des heures quand tu t''es enfin adossée. Respect.'::text),
(343052,38117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saatlerdir kâğıt ... ki sonunda arkana yaslandın. Saygı duyuyorum.'::text,'kontrol ediyordun'::text,'kontrol ediyorsun'::text,'kontrol ediyorsun'::text,'Saatlerdir kâğıt kontrol ediyordun ki sonunda arkana yaslandın. Saygı duyuyorum.'::text),
(343053,38117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órák óta ... dolgozatokat, amikor végre hátradőltél. Respekt.'::text,'javítottál'::text,'javítasz'::text,'javítasz'::text,'Órák óta javítottál dolgozatokat, amikor végre hátradőltél. Respekt.'::text),
(384555,42729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich hab gehört, sie ... einen geheimen Deal, als der Geiger vorbeiging.'::text,'machten gerade'::text,'machten'::text,'haben gemacht'::text,'Rate mal, ich hab gehört, sie machten gerade einen geheimen Deal, als der Geiger vorbeiging.'::text),
(384559,42729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що вони ... таємну угоду, коли повз пройшов скрипаль.'::text,'укладали'::text,'уклали'::text,'уклали'::text,'Уяви, я чула, що вони укладали таємну угоду, коли повз пройшов скрипаль.'::text),
(384558,42729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, oí que ... un trato secreto cuando pasó el violinista.'::text,'estaban cerrando'::text,'cerraron'::text,'han cerrado'::text,'Adivina, oí que estaban cerrando un trato secreto cuando pasó el violinista.'::text),
(384557,42729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu dire qu''ils ... un accord secret quand le violoniste est passé.'::text,'concluaient'::text,'ont conclu'::text,'ont conclu'::text,'Devine quoi, j''ai entendu dire qu''ils concluaient un accord secret quand le violoniste est passé.'::text),
(384560,42729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, duydum ki kemancı yanlarından geçerken gizli bir anlaşma ...'::text,'yapıyorlarmış'::text,'yapmışlar'::text,'yapmışlar'::text,'Tahmin et ne oldu, duydum ki kemancı yanlarından geçerken gizli bir anlaşma yapıyorlarmış.'::text),
(384561,42729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy titkos üzletet ..., amikor a hegedűs elment mellettük.'::text,'épp kötöttek'::text,'kötöttek'::text,'megkötötték'::text,'Képzeld, azt hallottam, hogy titkos üzletet épp kötöttek, amikor a hegedűs elment mellettük.'::text),
(384564,42730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... seit Monaten geheime Treffen in diesem Diner.'::text,'haben'::text,'haben'::text,'haben'::text,'Bestie, ich hab gehört, sie haben seit Monaten geheime Treffen in diesem Diner.'::text),
(384568,42730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вони ... таємні зустрічі в тій закусочній уже кілька місяців.'::text,'проводять'::text,'проводять'::text,'проводять'::text,'Подруго, я чула, що вони проводять таємні зустрічі в тій закусочній уже кілька місяців.'::text),
(384567,42730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, oí que ... reuniones secretas en ese restaurante desde hace meses.'::text,'tienen'::text,'están teniendo'::text,'tienen'::text,'Amiga, oí que tienen reuniones secretas en ese restaurante desde hace meses.'::text),
(384566,42730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''ils ... des réunions secrètes dans ce diner depuis des mois.'::text,'ont'::text,'ont'::text,'ont'::text,'Ma belle, j''ai entendu dire qu''ils ont des réunions secrètes dans ce diner depuis des mois.'::text),
(384569,42730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki aylardır o lokantada gizli toplantılar ...'::text,'yapıyorlarmış'::text,'yapıyorlarmış'::text,'yaparlarmış'::text,'Kanka, duydum ki aylardır o lokantada gizli toplantılar yapıyorlarmış.'::text),
(384570,42730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy hónapok óta titkos találkozókat ... abban az étteremben.'::text,'tartanak'::text,'tartanak'::text,'tartanak'::text,'Csajszi, azt hallottam, hogy hónapok óta titkos találkozókat tartanak abban az étteremben.'::text),
(384573,42731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat gesagt, dass, während sie ihren geheimen Deal ..., ein Geiger direkt zu ihnen kam.'::text,'abschlossen'::text,'abschlossen'::text,'abgeschlossen haben'::text,'Rate mal, sie hat gesagt, dass, während sie ihren geheimen Deal abschlossen, ein Geiger direkt zu ihnen kam.'::text),
(384577,42731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала, що поки вони ... свою таємну угоду, до них просто підійшов скрипаль.'::text,'укладали'::text,'уклали'::text,'уклали'::text,'Уяви, вона сказала, що поки вони укладали свою таємну угоду, до них просто підійшов скрипаль.'::text),
(384576,42731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, dijo que mientras ... su trato secreto, un violinista se les acercó.'::text,'cerraban'::text,'cerraron'::text,'han cerrado'::text,'Adivina, dijo que mientras cerraban su trato secreto, un violinista se les acercó.'::text),
(384575,42731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit que pendant qu''ils ... leur accord secret, un violoniste est arrivé droit sur eux.'::text,'concluaient'::text,'ont conclu'::text,'ont conclu'::text,'Devine quoi, elle a dit que pendant qu''ils concluaient leur accord secret, un violoniste est arrivé droit sur eux.'::text),
(384578,42731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin et ne oldu, dediğine göre onlar gizli anlaşmalarını ... bir kemancı dosdoğru yanlarına gelmiş.'::text,'yaparken'::text,'yapınca'::text,'yapmışken'::text,'Tahmin et ne oldu, dediğine göre onlar gizli anlaşmalarını yaparken bir kemancı dosdoğru yanlarına gelmiş.'::text),
(384579,42731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy miközben ... a titkos üzletüket, egy hegedűs egyenesen odament hozzájuk.'::text,'kötötték'::text,'megkötötték'::text,'megkötötték'::text,'Képzeld, azt mondta, hogy miközben kötötték a titkos üzletüket, egy hegedűs egyenesen odament hozzájuk.'::text),
(384582,42732,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die beiden ... dieses Jahr in diesem Diner drei geheime Deals abgeschlossen.'::text,'haben'::text,'haben'::text,'haben'::text,'Die beiden haben dieses Jahr in diesem Diner drei geheime Deals abgeschlossen.'::text),
(384586,42732,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці двоє цього року ... в цій закусочній три таємні угоди.'::text,'уклали'::text,'укладали'::text,'укладають'::text,'Ці двоє цього року уклали в цій закусочній три таємні угоди.'::text),
(384585,42732,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esos dos ... tres tratos secretos en este restaurante este año.'::text,'han cerrado'::text,'han estado cerrando'::text,'están cerrando'::text,'Esos dos han cerrado tres tratos secretos en este restaurante este año.'::text),
(384584,42732,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces deux-là ... trois accords secrets dans ce diner cette année.'::text,'ont conclu'::text,'ont conclu'::text,'concluent'::text,'Ces deux-là ont conclu trois accords secrets dans ce diner cette année.'::text),
(384587,42732,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İkisi bu yıl bu lokantada üç gizli anlaşma ...'::text,'yaptı'::text,'yapıp duruyor'::text,'yapıyor'::text,'İkisi bu yıl bu lokantada üç gizli anlaşma yaptı.'::text),
(384588,42732,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők ketten idén három titkos üzletet ... ebben az étteremben.'::text,'kötöttek'::text,'kötöttek'::text,'kötnek'::text,'Ők ketten idén három titkos üzletet kötöttek ebben az étteremben.'::text),
(384591,42733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie sich die Hand gaben, ... der Mann das geheime Geld unter der Tischdecke versteckt.'::text,'hatte'::text,'hat'::text,'hat'::text,'Bevor sie sich die Hand gaben, hatte der Mann das geheime Geld unter der Tischdecke versteckt.'::text),
(384595,42733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж вони потиснули руки, чоловік ... таємні гроші під скатертину.'::text,'сховав'::text,'сховав'::text,'ховає'::text,'Перш ніж вони потиснули руки, чоловік сховав таємні гроші під скатертину.'::text),
(384594,42733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de darse la mano, el hombre ... el dinero secreto bajo el mantel.'::text,'había escondido'::text,'ha escondido'::text,'esconde'::text,'Antes de darse la mano, el hombre había escondido el dinero secreto bajo el mantel.'::text),
(384593,42733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant qu''ils se serrent la main, l''homme ... l''argent secret sous la nappe.'::text,'avait caché'::text,'a caché'::text,'cache'::text,'Avant qu''ils se serrent la main, l''homme avait caché l''argent secret sous la nappe.'::text),
(384596,42733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sıkışmadan önce adam gizli parayı masa örtüsünün altına ...'::text,'saklamıştı'::text,'sakladı'::text,'saklıyor'::text,'El sıkışmadan önce adam gizli parayı masa örtüsünün altına saklamıştı.'::text),
(384597,42733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt kezet fogtak, a férfi ... a titkos pénzt az abrosz alá.'::text,'elrejtette'::text,'elrejtette'::text,'elrejti'::text,'Mielőtt kezet fogtak, a férfi elrejtette a titkos pénzt az abrosz alá.'::text),
(384609,42735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Deal, ... sie unter dem Tisch machen, ist geheim, weil er unter dem Tisch ist.'::text,'den'::text,'wer'::text,'dessen'::text,'Der Deal, den sie unter dem Tisch machen, ist geheim, weil er unter dem Tisch ist.'::text),
(384613,42735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Угода, ... вони укладають під столом, таємна, бо вона під столом.'::text,'яку'::text,'хто'::text,'чия'::text,'Угода, яку вони укладають під столом, таємна, бо вона під столом.'::text),
(384612,42735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El trato ... hacen debajo de la mesa es secreto, porque está debajo de la mesa.'::text,'que'::text,'quien'::text,'cuyo'::text,'El trato que hacen debajo de la mesa es secreto, porque está debajo de la mesa.'::text),
(384611,42735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''accord ... ils concluent sous la table est secret, parce qu''il est sous la table.'::text,'que'::text,'qui'::text,'dont'::text,'L''accord que ils concluent sous la table est secret, parce qu''il est sous la table.'::text),
(384614,42735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Masanın altında yaptıkları anlaşma gizli, çünkü masanın altında.'::text,''::text,NULL::text,NULL::text,'Masanın altında yaptıkları anlaşma gizli, çünkü masanın altında.'::text),
(384615,42735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üzlet, ... az asztal alatt kötnek, titkos, mert az asztal alatt van.'::text,'amit'::text,'aki'::text,'aminek a'::text,'Az üzlet, amit az asztal alatt kötnek, titkos, mert az asztal alatt van.'::text),
(384618,42736,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann erklärte, dass das Geschäft geheim ..., wie es bei solchen Vereinbarungen typischerweise der Fall ist.'::text,'bleiben würde'::text,'bleiben wird'::text,'bleiben'::text,'Der Mann erklärte, dass das Geschäft geheim bleiben würde, wie es bei solchen Vereinbarungen typischerweise der Fall ist.'::text),
(384622,42736,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік заявив, що угода ... таємною, як це зазвичай буває з такими домовленостями.'::text,'залишиться'::text,'залишиться'::text,'залишатися'::text,'Чоловік заявив, що угода залишиться таємною, як це зазвичай буває з такими домовленостями.'::text),
(384621,42736,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre afirmó que el trato ... en secreto, como suele ocurrir con tales acuerdos.'::text,'seguiría'::text,'seguirá'::text,'seguir'::text,'El hombre afirmó que el trato seguiría en secreto, como suele ocurrir con tales acuerdos.'::text),
(384620,42736,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme a déclaré que l''accord ... secret, comme c''est généralement le cas pour ce type d''accords.'::text,'resterait'::text,'restera'::text,'rester'::text,'L''homme a déclaré que l''accord resterait secret, comme c''est généralement le cas pour ce type d''accords.'::text),
(384623,42736,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam, bu tür anlaşmalarda genellikle olduğu gibi anlaşmanın gizli ... belirtti.'::text,'kalacağını'::text,'kalacağını'::text,'kalmak'::text,'Adam, bu tür anlaşmalarda genellikle olduğu gibi anlaşmanın gizli kalacağını belirtti.'::text),
(384624,42736,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi kijelentette, hogy az üzlet titokban ..., ahogy az ilyen megállapodásoknál jellemző.'::text,'marad'::text,'fog maradni'::text,'maradni'::text,'A férfi kijelentette, hogy az üzlet titokban marad, ahogy az ilyen megállapodásoknál jellemző.'::text),
(384627,42737,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Früher ... sie ihre Deals geheim, aber diese Schubkarre voller Geld macht alles kaputt!'::text,'hielten'::text,'hielten'::text,'hielten'::text,'Früher hielten sie ihre Deals geheim, aber diese Schubkarre voller Geld macht alles kaputt!'::text),
(384631,42737,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше вони ... свої угоди в таємниці, але ця тачка з готівкою все руйнує!'::text,'тримали'::text,'тримали'::text,'звикли тримати'::text,'Раніше вони тримали свої угоди в таємниці, але ця тачка з готівкою все руйнує!'::text),
(384630,42737,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Antes ... mantener sus tratos en secreto, pero esa carretilla de dinero lo arruina todo!'::text,'solían'::text,'solían'::text,'estaban acostumbrados a'::text,'¡Antes solían mantener sus tratos en secreto, pero esa carretilla de dinero lo arruina todo!'::text),
(384629,42737,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, ils ... garder leurs accords secrets, mais cette brouette de billets gâche tout !'::text,'avaient l''habitude de'::text,'avaient l''habitude de'::text,'étaient habitués à'::text,'Avant, ils avaient l''habitude de garder leurs accords secrets, mais cette brouette de billets gâche tout !'::text),
(384632,42737,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden anlaşmalarını gizli ..., ama o el arabası dolusu para her şeyi mahvediyor!'::text,'tutarlardı'::text,'tutarlardı'::text,'tutmaya alışkınlardı'::text,'Eskiden anlaşmalarını gizli tutarlardı, ama o el arabası dolusu para her şeyi mahvediyor!'::text),
(384633,42737,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régen titokban ... az üzleteiket, de az a talicska pénz mindent tönkretesz!'::text,'tartották'::text,'tartották'::text,'szokták tartani'::text,'Régen titokban tartották az üzleteiket, de az a talicska pénz mindent tönkretesz!'::text),
(384636,42738,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie einen geheimen Deal über einer Schubkarre voller Geld ab. Das ist komplett irre!'::text,'schließen'::text,'schließen'::text,'haben'::text,'Gerade schließen sie einen geheimen Deal über einer Schubkarre voller Geld ab. Das ist komplett irre!'::text),
(384640,42738,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прямо зараз вони ... таємну угоду над тачкою з готівкою. Це повне божевілля!'::text,'укладають'::text,'укладають'::text,'уклали'::text,'Прямо зараз вони укладають таємну угоду над тачкою з готівкою. Це повне божевілля!'::text),
(384639,42738,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... un trato secreto sobre una carretilla de dinero. ¡Esto es una locura total!'::text,'están cerrando'::text,'cierran'::text,'han cerrado'::text,'Ahora mismo están cerrando un trato secreto sobre una carretilla de dinero. ¡Esto es una locura total!'::text),
(384638,42738,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, ils ... un accord secret au-dessus d''une brouette de billets. C''est complètement dingue !'::text,'sont en train de conclure'::text,'concluent'::text,'ont conclu'::text,'En ce moment, ils sont en train de conclure un accord secret au-dessus d''une brouette de billets. C''est complètement dingue !'::text),
(384641,42738,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an ... gizli bir anlaşma, bir el arabası dolusu paranın başında. Bu tamamen çılgınlık!'::text,'yapıyorlar'::text,'yaparlar'::text,'yaptılar'::text,'Şu an yapıyorlar gizli bir anlaşma, bir el arabası dolusu paranın başında. Bu tamamen çılgınlık!'::text),
(384642,42738,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... egy titkos üzletet egy talicska pénz fölött. Ez teljesen őrület!'::text,'kötnek'::text,'kötnek'::text,'kötöttek'::text,'Épp most kötnek egy titkos üzletet egy talicska pénz fölött. Ez teljesen őrület!'::text),
(343542,38172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass die ummauerte Stadt unter ihr vor Jahrhunderten die Hauptstadt des Landes ...'::text,'gewesen ist'::text,'ist'::text,'sei'::text,'Man glaubt, dass die ummauerte Stadt unter ihr vor Jahrhunderten die Hauptstadt des Landes gewesen ist.'::text),
(343546,38172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що обнесене мурами місто під нею ... столицею країни багато століть тому.'::text,'було'::text,'є'::text,'є'::text,'Вважається, що обнесене мурами місто під нею було столицею країни багато століть тому.'::text),
(343545,38172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la ciudad amurallada que está a sus pies ... la capital del país hace siglos.'::text,'fue'::text,'es'::text,'siendo'::text,'Se cree que la ciudad amurallada que está a sus pies fue la capital del país hace siglos.'::text),
(343544,38172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la ville fortifiée en contrebas ... la capitale du pays il y a des siècles.'::text,'a été'::text,'est'::text,'étant'::text,'On pense que la ville fortifiée en contrebas a été la capitale du pays il y a des siècles.'::text),
(343547,38172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aşağıdaki surlu kasabanın yüzyıllar önce ülkenin başkenti ... düşünülüyor.'::text,'olduğu'::text,'olduğu'::text,'olması'::text,'Aşağıdaki surlu kasabanın yüzyıllar önce ülkenin başkenti olduğu düşünülüyor.'::text),
(343548,38172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az alatta fekvő, fallal körülvett város évszázadokkal ezelőtt az ország fővárosa ...'::text,'volt'::text,NULL::text,NULL::text,'Úgy tartják, hogy az alatta fekvő, fallal körülvett város évszázadokkal ezelőtt az ország fővárosa volt.'::text),
(368238,40916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, nächsten Sommer um diese Zeit ... er sie wieder mit dem Lineal, echt.'::text,'misst'::text,'misst'::text,'misst'::text,'Bro, nächsten Sommer um diese Zeit misst er sie wieder mit dem Lineal, echt.'::text),
(368242,40916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, наступного літа в цей час він знову ... їх тією лінійкою, реально.'::text,'мірятиме'::text,'поміряє'::text,'міряє'::text,'Бро, наступного літа в цей час він знову мірятиме їх тією лінійкою, реально.'::text),
(368241,40916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el verano que viene a estas alturas, ... otra vez con esa regla, en serio.'::text,'los estará midiendo'::text,'los medirá'::text,'los mide'::text,'Bro, el verano que viene a estas alturas, los estará midiendo otra vez con esa regla, en serio.'::text),
(368240,40916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, l''été prochain à la même époque, il ... encore avec cette règle, sérieux.'::text,'sera en train de les mesurer'::text,'les mesurera'::text,'les mesure'::text,'Frérot, l''été prochain à la même époque, il sera en train de les mesurer encore avec cette règle, sérieux.'::text),
(368243,40916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, gelecek yaz bu zamanlar onları yine o cetvelle ..., cidden.'::text,'ölçüyor olacak'::text,'ölçecek'::text,'ölçüyor'::text,'Kanka, gelecek yaz bu zamanlar onları yine o cetvelle ölçüyor olacak, cidden.'::text),
(368244,40916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, jövő nyáron ilyenkor megint ... őket azzal a vonalzóval, komolyan.'::text,'mérni fogja'::text,'megméri'::text,'méri'::text,'Tesó, jövő nyáron ilyenkor megint mérni fogja őket azzal a vonalzóval, komolyan.'::text),
(368247,40917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Erwachsene verspricht, dass er alle 12 Kinder vor der Kuchen-Deadline ...'::text,'messen wird'::text,'messen wird'::text,'misst'::text,'Der Erwachsene verspricht, dass er alle 12 Kinder vor der Kuchen-Deadline messen wird.'::text),
(368251,40917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорослий обіцяє, що ... всіх 12 дітей до дедлайну з тортом.'::text,'поміряє'::text,'мірятиме'::text,'міряє'::text,'Дорослий обіцяє, що поміряє всіх 12 дітей до дедлайну з тортом.'::text),
(368250,40917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El adulto promete que ... a los 12 niños antes de la hora límite de la tarta.'::text,'medirá'::text,'estará midiendo'::text,'mide'::text,'El adulto promete que medirá a los 12 niños antes de la hora límite de la tarta.'::text),
(368249,40917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''adulte promet qu''il ... les 12 enfants avant la deadline du gâteau.'::text,'mesurera'::text,'sera en train de mesurer'::text,'mesure'::text,'L''adulte promet qu''il mesurera les 12 enfants avant la deadline du gâteau.'::text),
(368252,40917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetişkin, pasta saatinden önce 12 çocuğun hepsini ... söz veriyor.'::text,'ölçeceğine'::text,'ölçüyor olacağına'::text,'ölçtüğüne'::text,'Yetişkin, pasta saatinden önce 12 çocuğun hepsini ölçeceğine söz veriyor.'::text),
(368253,40917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felnőtt megígéri, hogy a tortás határidő előtt mind a 12 gyereket ...'::text,'megméri'::text,'mérni fogja'::text,'méri'::text,'A felnőtt megígéri, hogy a tortás határidő előtt mind a 12 gyereket megméri.'::text),
(368265,40919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Erwachsene versucht, beide Kinder mit einem flachen Lineal zu ..., eine Methode, die typischerweise funktioniert.'::text,'messen'::text,'messen'::text,'messen'::text,'Der Erwachsene versucht, beide Kinder mit einem flachen Lineal zu messen, eine Methode, die typischerweise funktioniert.'::text),
(368269,40919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорослий намагається ... обох дітей однією пласкою лінійкою — метод, який зазвичай працює.'::text,'поміряти'::text,'поміряти'::text,'поміряти'::text,'Дорослий намагається поміряти обох дітей однією пласкою лінійкою — метод, який зазвичай працює.'::text),
(368268,40919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El adulto intenta ... a los dos niños con una regla plana, un método que suele funcionar.'::text,'medir'::text,'medir'::text,'medir'::text,'El adulto intenta medir a los dos niños con una regla plana, un método que suele funcionar.'::text),
(368267,40919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''adulte tente de ... les deux enfants avec une seule règle plate, une méthode qui fonctionne généralement.'::text,'mesurer'::text,'mesurer'::text,'mesurer'::text,'L''adulte tente de mesurer les deux enfants avec une seule règle plate, une méthode qui fonctionne généralement.'::text),
(368270,40919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetişkin iki çocuğu tek bir düz cetvelle ... çalışıyor; bu, genellikle işe yarayan bir yöntem.'::text,'ölçmeye'::text,'ölçmeye'::text,'ölçmeye'::text,'Yetişkin iki çocuğu tek bir düz cetvelle ölçmeye çalışıyor; bu, genellikle işe yarayan bir yöntem.'::text),
(368271,40919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felnőtt megpróbálja egyetlen lapos vonalzóval ... mindkét gyereket, ami jellemzően működő módszer.'::text,'megmérni'::text,'megmérni'::text,'megmérni'::text,'A felnőtt megpróbálja egyetlen lapos vonalzóval megmérni mindkét gyereket, ami jellemzően működő módszer.'::text),
(368274,40920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die können doch nicht beide gleich groß sein, ...? Messt nochmal, das ist eine totale Katastrophe!'::text,'oder'::text,'oder'::text,'oder'::text,'Die können doch nicht beide gleich groß sein, oder? Messt nochmal, das ist eine totale Katastrophe!'::text),
(368278,40920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ж не можуть бути однакового зросту, ...? Поміряйте ще раз, це повна катастрофа!'::text,'правда'::text,'правда'::text,'правда'::text,'Вони ж не можуть бути однакового зросту, правда? Поміряйте ще раз, це повна катастрофа!'::text),
(368277,40920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No pueden medir lo mismo los dos, ¿...? ¡Medid otra vez, esto es un desastre total!'::text,'verdad'::text,'verdad'::text,'verdad'::text,'No pueden medir lo mismo los dos, ¿verdad? ¡Medid otra vez, esto es un desastre total!'::text),
(368276,40920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ne peuvent pas faire la même taille tous les deux, ... ? Mesurez encore, c''est une catastrophe totale !'::text,'hein'::text,'hein'::text,'hein'::text,'Ils ne peuvent pas faire la même taille tous les deux, hein ? Mesurez encore, c''est une catastrophe totale !'::text),
(368279,40920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İkisi aynı boyda olamaz, ...? Tekrar ölçün, bu tam bir felaket!'::text,'değil mi'::text,'değil mi'::text,'değil mi'::text,'İkisi aynı boyda olamaz, değil mi? Tekrar ölçün, bu tam bir felaket!'::text),
(368280,40920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem lehetnek egyformán magasak, ...? Mérjétek meg újra, ez totális katasztrófa!'::text,'ugye'::text,'ugye'::text,'ugye'::text,'Nem lehetnek egyformán magasak, ugye? Mérjétek meg újra, ez totális katasztrófa!'::text),
(368283,40921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge wurde nicht als Erster gemessen, und ...'::text,'das Mädchen auch nicht'::text,'das Mädchen auch nicht'::text,'das Mädchen schon'::text,'Der Junge wurde nicht als Erster gemessen, und das Mädchen auch nicht.'::text),
(368287,40921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопчика не поміряли першим, і ...'::text,'дівчинку теж ні'::text,'дівчинку теж ні'::text,'дівчинку теж'::text,'Хлопчика не поміряли першим, і дівчинку теж ні.'::text),
(368286,40921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al niño no lo midieron primero, y ...'::text,'a la niña tampoco'::text,'a la niña tampoco'::text,'a la niña también'::text,'Al niño no lo midieron primero, y a la niña tampoco.'::text),
(368285,40921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon n''a pas été mesuré en premier, et ...'::text,'la fille non plus'::text,'la fille non plus'::text,'la fille aussi'::text,'Le garçon n''a pas été mesuré en premier, et la fille non plus.'::text),
(368288,40921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce oğlan ölçülmedi, ...'::text,'kız da ölçülmedi'::text,'kız da ölçülmedi'::text,'kız ölçüldü'::text,'Önce oğlan ölçülmedi, kız da ölçülmedi.'::text),
(368289,40921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem a fiút mérték meg elsőként, és ...'::text,'a lányt sem'::text,'a lányt sem'::text,'a lányt igen'::text,'Nem a fiút mérték meg elsőként, és a lányt sem.'::text),
(368292,40922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis nächsten Sommer wird die Familie beide Kinder wieder ...'::text,'gemessen haben'::text,'messen'::text,'messen'::text,'Bis nächsten Sommer wird die Familie beide Kinder wieder gemessen haben.'::text),
(368296,40922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До наступного літа родина знову ... обох дітей.'::text,'поміряє'::text,'поміряє'::text,'мірятиме'::text,'До наступного літа родина знову поміряє обох дітей.'::text),
(368295,40922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el próximo verano, la familia ... de nuevo a los dos niños.'::text,'habrá medido'::text,'medirá'::text,'estará midiendo'::text,'Para el próximo verano, la familia habrá medido de nuevo a los dos niños.'::text),
(368294,40922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici l''été prochain, la famille ... à nouveau les deux enfants.'::text,'aura mesuré'::text,'mesurera'::text,'sera en train de mesurer'::text,'D''ici l''été prochain, la famille aura mesuré à nouveau les deux enfants.'::text),
(368297,40922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelecek yaza kadar aile iki çocuğu yeniden ...'::text,'ölçmüş olacak'::text,'ölçecek'::text,'ölçüyor olacak'::text,'Gelecek yaza kadar aile iki çocuğu yeniden ölçmüş olacak.'::text),
(368298,40922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő nyárra a család újra ... mindkét gyereket.'::text,'megméri'::text,'megméri'::text,'mérni fogja'::text,'Jövő nyárra a család újra megméri mindkét gyereket.'::text),
(368301,40923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Erwachsene sie nicht gemessen hätte, ... sie nicht gewusst, wer größer ist.'::text,'hätten'::text,'werden'::text,'haben'::text,'Wenn der Erwachsene sie nicht gemessen hätte, hätten sie nicht gewusst, wer größer ist.'::text),
(368305,40923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби дорослий їх не поміряв, вони ..., хто вищий.'::text,'не знали б'::text,'не знатимуть'::text,'не знали'::text,'Якби дорослий їх не поміряв, вони не знали б, хто вищий.'::text),
(368304,40923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el adulto no los hubiera medido, no ... quién era más alto.'::text,'habrían sabido'::text,'sabrán'::text,'sabían'::text,'Si el adulto no los hubiera medido, no habrían sabido quién era más alto.'::text),
(368303,40923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''adulte ne les avait pas mesurés, ils ne ... pas qui était le plus grand.'::text,'auraient su'::text,'sauront'::text,'savaient'::text,'Si l''adulte ne les avait pas mesurés, ils ne auraient su pas qui était le plus grand.'::text),
(368306,40923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetişkin onları ölçmeseydi, kimin daha uzun olduğunu ...'::text,'bilmezlerdi'::text,'bilmeyecekler'::text,'bilmiyorlardı'::text,'Yetişkin onları ölçmeseydi, kimin daha uzun olduğunu bilmezlerdi.'::text),
(368307,40923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a felnőtt nem mérte volna meg őket, ..., ki a magasabb.'::text,'nem tudták volna'::text,'nem fogják tudni'::text,'nem tudták'::text,'Ha a felnőtt nem mérte volna meg őket, nem tudták volna, ki a magasabb.'::text),
(368319,40925,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Erwachsene ... sie, während hinter ihnen andere Kinder vorbeirennen. Leicht chaotisch.'::text,'misst'::text,'misst'::text,'hat gemessen'::text,'Der Erwachsene misst sie, während hinter ihnen andere Kinder vorbeirennen. Leicht chaotisch.'::text),
(368323,40925,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорослий ... їх, поки позаду пробігають інші діти. Трохи хаотично.'::text,'міряє'::text,'міряє'::text,'поміряв'::text,'Дорослий міряє їх, поки позаду пробігають інші діти. Трохи хаотично.'::text),
(368322,40925,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El adulto los ... mientras otros niños pasan corriendo por detrás. Ligeramente caótico.'::text,'está midiendo'::text,'mide'::text,'ha medido'::text,'El adulto los está midiendo mientras otros niños pasan corriendo por detrás. Ligeramente caótico.'::text),
(368321,40925,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''adulte les ... pendant que d''autres enfants passent en courant derrière. Légèrement chaotique.'::text,'mesure'::text,'mesure'::text,'a mesurés'::text,'L''adulte les mesure pendant que d''autres enfants passent en courant derrière. Légèrement chaotique.'::text),
(368324,40925,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yetişkin onları ..., arkadan başka çocuklar koşarak geçerken. Hafif kaotik.'::text,'ölçüyor'::text,'ölçer'::text,'ölçtü'::text,'Yetişkin onları ölçüyor, arkadan başka çocuklar koşarak geçerken. Hafif kaotik.'::text),
(368325,40925,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A felnőtt ... őket, miközben mögöttük más gyerekek rohangálnak. Enyhén kaotikus.'::text,'méri'::text,'méri'::text,'megmérte'::text,'A felnőtt méri őket, miközben mögöttük más gyerekek rohangálnak. Enyhén kaotikus.'::text),
(368328,40926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die ... sich ewig umarmt, bevor sie jemand gemessen hat, irgendwie süß.'::text,'hatten'::text,'haben'::text,'wurden'::text,'Bro, die hatten sich ewig umarmt, bevor sie jemand gemessen hat, irgendwie süß.'::text),
(368332,40926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони ... цілу вічність, поки їх хтось не поміряв, так мило.'::text,'обіймалися'::text,'обіймаються'::text,'були обійняті'::text,'Бро, вони обіймалися цілу вічність, поки їх хтось не поміряв, так мило.'::text),
(368331,40926,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... durante siglos antes de que alguien los midiera, qué monos.'::text,'se habían estado abrazando'::text,'se han estado abrazando'::text,'fueron abrazados'::text,'Bro, se habían estado abrazando durante siglos antes de que alguien los midiera, qué monos.'::text),
(368330,40926,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ils ... pendant des plombes avant que quelqu''un les mesure, trop mignon.'::text,'s''étaient fait des câlins'::text,'se font des câlins'::text,'ont été câlinés'::text,'Frérot, ils s''étaient fait des câlins pendant des plombes avant que quelqu''un les mesure, trop mignon.'::text),
(368333,40926,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, biri onları ölçene kadar uzun süre ..., çok tatlı ya.'::text,'sarılıp durmuşlardı'::text,'sarılıp duruyorlar'::text,'sarılınmışlardı'::text,'Kanka, biri onları ölçene kadar uzun süre sarılıp durmuşlardı, çok tatlı ya.'::text),
(368334,40926,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ők egy örökkévalóságig ..., mielőtt bárki megmérte volna őket, elég cuki.'::text,'ölelkeztek'::text,'ölelkeznek'::text,'meg lettek ölelve'::text,'Tesó, ők egy örökkévalóságig ölelkeztek, mielőtt bárki megmérte volna őket, elég cuki.'::text),
(337341,37483,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... zum Ball, als er sich die Wade verletzte, also ging er nicht.'::text,'rannte gerade'::text,'rannte'::text,'ist gerannt'::text,'Er rannte gerade zum Ball, als er sich die Wade verletzte, also ging er nicht.'::text),
(337345,37483,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... за м''ячем, коли пошкодив литку, тож він не ходив.'::text,'біг'::text,'побіг'::text,'побіг'::text,'Він біг за м''ячем, коли пошкодив литку, тож він не ходив.'::text),
(337344,37483,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... hacia el balón cuando se hizo daño en el gemelo, así que no caminaba.'::text,'estaba corriendo'::text,'corrió'::text,'ha corrido'::text,'Él estaba corriendo hacia el balón cuando se hizo daño en el gemelo, así que no caminaba.'::text),
(337343,37483,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... vers le ballon quand il s''est blessé au mollet, donc il ne marchait pas.'::text,'courait'::text,'a couru'::text,'a couru'::text,'Il courait vers le ballon quand il s''est blessé au mollet, donc il ne marchait pas.'::text),
(337346,37483,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baldırını sakatladığında topa doğru ..., bu yüzden yürümüyordu.'::text,'koşuyordu'::text,'koştu'::text,'koştu'::text,'Baldırını sakatladığında topa doğru koşuyordu, bu yüzden yürümüyordu.'::text),
(337347,37483,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A labda felé ..., amikor megsérült a vádlija, szóval nem sétált.'::text,'épp futott'::text,'futott'::text,'futott'::text,'A labda felé épp futott, amikor megsérült a vádlija, szóval nem sétált.'::text),
(337350,37484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Trainer ... die verletzte Wade seit ungefähr zwei Minuten.'::text,'dehnt'::text,'dehnt'::text,'dehnt'::text,'Der Trainer dehnt die verletzte Wade seit ungefähr zwei Minuten.'::text),
(337354,37484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренер ... пошкоджену литку приблизно дві хвилини.'::text,'розтягує'::text,'розтягує'::text,'розтягує'::text,'Тренер розтягує пошкоджену литку приблизно дві хвилини.'::text),
(337353,37484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El entrenador ... el gemelo lesionado desde hace aproximadamente dos minutos.'::text,'estira'::text,'está estirando'::text,'estira'::text,'El entrenador estira el gemelo lesionado desde hace aproximadamente dos minutos.'::text),
(337352,37484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entraîneur ... le mollet blessé depuis environ deux minutes.'::text,'étire'::text,'étire'::text,'étire'::text,'L''entraîneur étire le mollet blessé depuis environ deux minutes.'::text),
(337355,37484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör yaklaşık iki dakikadır sakat baldırı ...'::text,'esnetiyor'::text,'esnetiyor'::text,'esnetir'::text,'Antrenör yaklaşık iki dakikadır sakat baldırı esnetiyor.'::text),
(337356,37484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző körülbelül két perce ... a sérült vádlit.'::text,'nyújtja'::text,'nyújtja'::text,'nyújtja'::text,'Az edző körülbelül két perce nyújtja a sérült vádlit.'::text),
(337359,37485,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sprintete zum Ball, da ... er sich plötzlich an die Wade. Katastrophe!'::text,'griff'::text,'griff gerade'::text,'hat gegriffen'::text,'Er sprintete zum Ball, da griff er sich plötzlich an die Wade. Katastrophe!'::text),
(337363,37485,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він мчав до м''яча, коли раптом ... за литку. Катастрофа!'::text,'схопився'::text,'хапався'::text,'схопився'::text,'Він мчав до м''яча, коли раптом схопився за литку. Катастрофа!'::text),
(337362,37485,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba esprintando hacia el balón cuando de repente se ... el gemelo. ¡Desastre!'::text,'agarró'::text,'estaba agarrando'::text,'ha agarrado'::text,'Estaba esprintando hacia el balón cuando de repente se agarró el gemelo. ¡Desastre!'::text),
(337361,37485,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il sprintait vers le ballon quand soudain il ... son mollet. La cata !'::text,'a attrapé'::text,'attrapait'::text,'a attrapé'::text,'Il sprintait vers le ballon quand soudain il a attrapé son mollet. La cata !'::text),
(337364,37485,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topa doğru depar atıyordu ki birden ... baldırını. Felaket!'::text,'tuttu'::text,'tutuyordu'::text,'tuttu'::text,'Topa doğru depar atıyordu ki birden tuttu baldırını. Felaket!'::text),
(337365,37485,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a labda felé sprintelt, amikor hirtelen ... a vádliját. Katasztrófa!'::text,'megragadta'::text,'fogta'::text,'megragadta'::text,'Épp a labda felé sprintelt, amikor hirtelen megragadta a vádliját. Katasztrófa!'::text),
(337368,37486,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Trainer ... seine Wade schon dreimal gedehnt, und es ist immer noch ein Albtraum!'::text,'hat'::text,'hat'::text,'hat'::text,'Der Trainer hat seine Wade schon dreimal gedehnt, und es ist immer noch ein Albtraum!'::text),
(337372,37486,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренер уже тричі ... йому литку, а це досі жах!'::text,'розтягнув'::text,'розтягував'::text,'розтягує'::text,'Тренер уже тричі розтягнув йому литку, а це досі жах!'::text),
(337371,37486,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El entrenador ya le ... el gemelo tres veces, y sigue siendo una pesadilla!'::text,'ha estirado'::text,'ha estado estirando'::text,'está estirando'::text,'¡El entrenador ya le ha estirado el gemelo tres veces, y sigue siendo una pesadilla!'::text),
(337370,37486,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entraîneur lui ... le mollet trois fois déjà, et c''est toujours un cauchemar !'::text,'a étiré'::text,'a étiré'::text,'étire'::text,'L''entraîneur lui a étiré le mollet trois fois déjà, et c''est toujours un cauchemar !'::text),
(337373,37486,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör baldırını şimdiden üç kez ... ve hâlâ tam bir kâbus!'::text,'esnetti'::text,'esnetip duruyor'::text,'esnetiyor'::text,'Antrenör baldırını şimdiden üç kez esnetti ve hâlâ tam bir kâbus!'::text),
(337374,37486,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző már háromszor ... a vádliját, és még mindig rémálom!'::text,'megnyújtotta'::text,'nyújtotta'::text,'nyújtja'::text,'Az edző már háromszor megnyújtotta a vádliját, és még mindig rémálom!'::text),
(337377,37487,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Trainer aufs Feld lief, ... sich der Spieler schon an die Rückseite seiner Wade gegriffen.'::text,'hatte'::text,'hat'::text,'hat'::text,'Als der Trainer aufs Feld lief, hatte sich der Spieler schon an die Rückseite seiner Wade gegriffen.'::text),
(337381,37487,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки тренер вибіг на поле, гравець уже ... за задню частину литки.'::text,'схопився'::text,'схопився'::text,'хапається'::text,'Поки тренер вибіг на поле, гравець уже схопився за задню частину литки.'::text),
(337380,37487,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el entrenador salió al campo, el jugador ya se ... la parte de atrás del gemelo.'::text,'había agarrado'::text,'ha agarrado'::text,'agarra'::text,'Cuando el entrenador salió al campo, el jugador ya se había agarrado la parte de atrás del gemelo.'::text),
(337379,37487,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand l''entraîneur est arrivé sur le terrain, le joueur ... déjà l''arrière de son mollet.'::text,'avait attrapé'::text,'a attrapé'::text,'attrape'::text,'Quand l''entraîneur est arrivé sur le terrain, le joueur avait attrapé déjà l''arrière de son mollet.'::text),
(337382,37487,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenör sahaya koşup gelene kadar oyuncu baldırının arkasını ...'::text,'tutmuştu'::text,'tuttu'::text,'tutuyor'::text,'Antrenör sahaya koşup gelene kadar oyuncu baldırının arkasını tutmuştu.'::text),
(337383,37487,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az edző befutott, a játékos már ... a vádlija hátsó részét.'::text,'megragadta'::text,'megragadta'::text,'megragadja'::text,'Mire az edző befutott, a játékos már megragadta a vádlija hátsó részét.'::text),
(337395,37489,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Spieler wünschte, er ... seine Wade vor dem Spiel gedehnt.'::text,'hätte'::text,'hätte'::text,'würde'::text,'Der Spieler wünschte, er hätte seine Wade vor dem Spiel gedehnt.'::text),
(337399,37489,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гравець шкодує, що не ... литку перед матчем.'::text,'розтягнув'::text,'розтягнув'::text,'розтягне'::text,'Гравець шкодує, що не розтягнув литку перед матчем.'::text),
(337398,37489,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador desearía ... el gemelo antes del partido.'::text,'haber estirado'::text,'estirar'::text,'estirar'::text,'El jugador desearía haber estirado el gemelo antes del partido.'::text),
(337397,37489,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur aimerait ... son mollet avant le match.'::text,'avoir étiré'::text,'étirer'::text,'étirer'::text,'Le joueur aimerait avoir étiré son mollet avant le match.'::text),
(337400,37489,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu maçtan önce baldırını ... diliyor.'::text,'esnetmiş olmayı'::text,'esnetmeyi'::text,'esnetmeyi'::text,'Oyuncu maçtan önce baldırını esnetmiş olmayı diliyor.'::text),
(337401,37489,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A játékos azt kívánja, bárcsak ... a vádliját a meccs előtt.'::text,'megnyújtotta volna'::text,'megnyújtaná'::text,'megnyújtaná'::text,'A játékos azt kívánja, bárcsak megnyújtotta volna a vádliját a meccs előtt.'::text),
(337413,37491,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Trainer dehnt ..., während der Spieler auf dem Rasen liegt.'::text,'den Wadenmuskel'::text,'einen Wadenmuskel'::text,'Wadenmuskel'::text,'Der Trainer dehnt den Wadenmuskel, während der Spieler auf dem Rasen liegt.'::text),
(337417,37491,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тренер розтягує ... м''яз, поки гравець лежить на траві.'::text,'литковий'::text,'литковий'::text,'литковий'::text,'Тренер розтягує литковий м''яз, поки гравець лежить на траві.'::text),
(337416,37491,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El entrenador estira ... mientras el jugador está tumbado en el césped.'::text,'el gemelo'::text,'un gemelo'::text,'gemelo'::text,'El entrenador estira el gemelo mientras el jugador está tumbado en el césped.'::text),
(337415,37491,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''entraîneur étire ... pendant que le joueur est allongé sur la pelouse.'::text,'le muscle du mollet'::text,'un muscle du mollet'::text,'muscle du mollet'::text,'L''entraîneur étire le muscle du mollet pendant que le joueur est allongé sur la pelouse.'::text),
(337418,37491,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncu çimlerde yatarken antrenör ... kasını esnetiyor.'::text,'baldır'::text,'bir baldır'::text,'baldır'::text,'Oyuncu çimlerde yatarken antrenör baldır kasını esnetiyor.'::text),
(337419,37491,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző ... nyújtja, miközben a játékos a füvön fekszik.'::text,'a vádliizmot'::text,'egy vádliizmot'::text,'vádliizmot'::text,'Az edző a vádliizmot nyújtja, miközben a játékos a füvön fekszik.'::text),
(337422,37492,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... der Schmerzen in seiner Wade konnte der Spieler nicht aufstehen.'::text,'Wegen'::text,'Trotz'::text,'Obwohl'::text,'Wegen der Schmerzen in seiner Wade konnte der Spieler nicht aufstehen.'::text),
(337426,37492,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... біль у литці гравець не міг підвестися.'::text,'Через'::text,'Попри'::text,'Хоча'::text,'Через біль у литці гравець не міг підвестися.'::text),
(337425,37492,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el dolor en el gemelo, el jugador no podía levantarse.'::text,'Por'::text,'A pesar de'::text,'Aunque'::text,'Por el dolor en el gemelo, el jugador no podía levantarse.'::text),
(337424,37492,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... la douleur au mollet, le joueur ne pouvait pas se relever.'::text,'À cause de'::text,'Malgré'::text,'Bien que'::text,'À cause de la douleur au mollet, le joueur ne pouvait pas se relever.'::text),
(337427,37492,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Baldırındaki ağrı ... oyuncu ayağa kalkamadı.'::text,'yüzünden'::text,'rağmen'::text,'olsa da'::text,'Baldırındaki ağrı yüzünden oyuncu ayağa kalkamadı.'::text),
(337428,37492,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vádlijában érzett fájdalom ... a játékos nem tudott felállni.'::text,'miatt'::text,'ellenére'::text,'bár'::text,'A vádlijában érzett fájdalom miatt a játékos nem tudott felállni.'::text),
(337431,37493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laut dem Bericht des Trainers wird seine Wade bis Freitag 80 % ihrer Kraft ...'::text,'zurückgewonnen haben'::text,'zurückgewinnen'::text,'zurückgewinnen'::text,'Laut dem Bericht des Trainers wird seine Wade bis Freitag 80 % ihrer Kraft zurückgewonnen haben.'::text),
(337435,37493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Згідно зі звітом тренера, до п''ятниці його литка ... 80 % своєї сили.'::text,'відновить'::text,'відновить'::text,'відновлює'::text,'Згідно зі звітом тренера, до п''ятниці його литка відновить 80 % своєї сили.'::text),
(337434,37493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según el informe del entrenador, para el viernes su gemelo ... el 80 % de su fuerza.'::text,'habrá recuperado'::text,'recuperará'::text,'recupera'::text,'Según el informe del entrenador, para el viernes su gemelo habrá recuperado el 80 % de su fuerza.'::text),
(337433,37493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''après le rapport de l''entraîneur, d''ici vendredi son mollet ... 80 % de sa force.'::text,'aura retrouvé'::text,'retrouvera'::text,'retrouve'::text,'D''après le rapport de l''entraîneur, d''ici vendredi son mollet aura retrouvé 80 % de sa force.'::text),
(337436,37493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antrenörün raporuna göre cumaya kadar baldırı gücünün %80''ini ...'::text,'geri kazanmış olacak'::text,'geri kazanacak'::text,'geri kazanıyor'::text,'Antrenörün raporuna göre cumaya kadar baldırı gücünün %80''ini geri kazanmış olacak.'::text),
(337437,37493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az edző jelentése szerint péntekre a vádlija ... ereje 80%-át.'::text,'visszanyeri'::text,'visszanyeri'::text,'visszanyeri'::text,'Az edző jelentése szerint péntekre a vádlija visszanyeri ereje 80%-át.'::text),
(397920,44214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tatsächlich wird die nächste Welle die Spur der Jungtiere im Sand ...'::text,'wegspülen'::text,'gerade wegspülen'::text,'wegspülen'::text,'Tatsächlich wird die nächste Welle die Spur der Jungtiere im Sand wegspülen.'::text),
(397924,44214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Насправді наступна хвиля ... слід черепашенят на піску.'::text,'змиє'::text,'змиватиме'::text,'змиває'::text,'Насправді наступна хвиля змиє слід черепашенят на піску.'::text),
(397923,44214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De hecho, la próxima ola ... el rastro de las crías en la arena.'::text,'borrará'::text,'estará borrando'::text,'borra'::text,'De hecho, la próxima ola borrará el rastro de las crías en la arena.'::text),
(397922,44214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En fait, la prochaine vague ... la trace des bébés tortues dans le sable.'::text,'effacera'::text,'sera en train d''effacer'::text,'efface'::text,'En fait, la prochaine vague effacera la trace des bébés tortues dans le sable.'::text),
(397925,44214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aslında bir sonraki dalga yavruların kumdaki izini ...'::text,'silecek'::text,'siliyor olacak'::text,'siler'::text,'Aslında bir sonraki dalga yavruların kumdaki izini silecek.'::text),
(397926,44214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Valójában a következő hullám ... a kis teknősök nyomát a homokban.'::text,'el fogja mosni'::text,'épp mossa el'::text,'elmossa'::text,'Valójában a következő hullám el fogja mosni a kis teknősök nyomát a homokban.'::text),
(397929,44215,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Welle die Spur ..., verschwinden die winzigen Abdrücke für immer!'::text,'erreicht'::text,'erreichte'::text,'erreichen wird'::text,'Wenn eine Welle die Spur erreicht, verschwinden die winzigen Abdrücke für immer!'::text),
(397933,44215,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо хвиля ... слід, крихітні відбитки зникають назавжди!'::text,'досягає'::text,'досягла'::text,'досягне'::text,'Якщо хвиля досягає слід, крихітні відбитки зникають назавжди!'::text),
(397932,44215,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si una ola ... el rastro, las pequeñas huellas desaparecen para siempre!'::text,'alcanza'::text,'alcanzó'::text,'alcanzará'::text,'¡Si una ola alcanza el rastro, las pequeñas huellas desaparecen para siempre!'::text),
(397931,44215,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une vague ... la trace, les minuscules empreintes disparaissent pour toujours !'::text,'atteint'::text,'atteignait'::text,'atteindra'::text,'Si une vague atteint la trace, les minuscules empreintes disparaissent pour toujours !'::text),
(397934,44215,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dalga ize ..., minicik ayak izleri sonsuza dek kayboluyor!'::text,'ulaşırsa'::text,'ulaştıysa'::text,'ulaşacaksa'::text,'Bir dalga ize ulaşırsa, minicik ayak izleri sonsuza dek kayboluyor!'::text),
(397935,44215,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy hullám ... a nyomot, az apró lábnyomok örökre eltűnnek!'::text,'eléri'::text,'elérte'::text,'el fogja érni'::text,'Ha egy hullám eléri a nyomot, az apró lábnyomok örökre eltűnnek!'::text),
(397947,44217,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Schildkröten größer wären, ... ihre Spur im Sand tiefer.'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn die Schildkröten größer wären, wäre ihre Spur im Sand tiefer.'::text),
(397951,44217,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби черепахи були більшими, їхній слід на піску ... глибшим.'::text,'був би'::text,'буде'::text,'є'::text,'Якби черепахи були більшими, їхній слід на піску був би глибшим.'::text),
(397950,44217,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las tortugas fueran más grandes, su rastro en la arena ... más profundo.'::text,'sería'::text,'será'::text,'es'::text,'Si las tortugas fueran más grandes, su rastro en la arena sería más profundo.'::text),
(397949,44217,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les tortues étaient plus grosses, leur trace dans le sable ... plus profonde.'::text,'serait'::text,'sera'::text,'est'::text,'Si les tortues étaient plus grosses, leur trace dans le sable serait plus profonde.'::text),
(397952,44217,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaplumbağalar daha büyük olsaydı, kumdaki izleri daha derin ...'::text,'olurdu'::text,'olacak'::text,NULL::text,'Kaplumbağalar daha büyük olsaydı, kumdaki izleri daha derin olurdu.'::text),
(397953,44217,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a teknősök nagyobbak lennének, a nyomuk a homokban mélyebb ...'::text,'lenne'::text,'lesz'::text,NULL::text,'Ha a teknősök nagyobbak lennének, a nyomuk a homokban mélyebb lenne.'::text),
(397956,44218,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In der letzten Einstellung ... die lange Spur vom Schaum einer Welle bedeckt.'::text,'wurde'::text,'wird'::text,'hat'::text,'In der letzten Einstellung wurde die lange Spur vom Schaum einer Welle bedeckt.'::text),
(397960,44218,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'В останньому кадрі довгий слід ... піною хвилі.'::text,'накрило'::text,'накриває'::text,'накрив'::text,'В останньому кадрі довгий слід накрило піною хвилі.'::text),
(397959,44218,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la última toma, el largo rastro ... por la espuma de una ola.'::text,'fue cubierto'::text,'es cubierto'::text,'cubrió'::text,'En la última toma, el largo rastro fue cubierto por la espuma de una ola.'::text),
(397958,44218,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans le dernier plan, la longue trace ... par l''écume d''une vague.'::text,'a été recouverte'::text,'est recouverte'::text,'a recouvert'::text,'Dans le dernier plan, la longue trace a été recouverte par l''écume d''une vague.'::text),
(397961,44218,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son çekimde uzun iz bir dalganın köpüğüyle ...'::text,'kaplandı'::text,'kaplanıyor'::text,'kapladı'::text,'Son çekimde uzun iz bir dalganın köpüğüyle kaplandı.'::text),
(397962,44218,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az utolsó jelenetben a hosszú nyomot ... egy hullám habja.'::text,'elborította'::text,'elborítja'::text,'elborította'::text,'Az utolsó jelenetben a hosszú nyomot elborította egy hullám habja.'::text),
(397965,44219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das erste Jungtier ... eine lange Spur hinter sich im nassen Sand.'::text,'hinterließ'::text,'wurde hinterlassen'::text,'hinterlassend'::text,'Das erste Jungtier hinterließ eine lange Spur hinter sich im nassen Sand.'::text),
(397969,44219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перше черепашеня ... за собою довгий слід на мокрому піску.'::text,'залишило'::text,'було залишене'::text,'залишаючи'::text,'Перше черепашеня залишило за собою довгий слід на мокрому піску.'::text),
(397968,44219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La primera cría ... un largo rastro tras ella en la arena mojada.'::text,'dejó'::text,'fue dejada'::text,'dejando'::text,'La primera cría dejó un largo rastro tras ella en la arena mojada.'::text),
(397967,44219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le premier bébé tortue ... une longue trace derrière lui dans le sable mouillé.'::text,'a laissé'::text,'a été laissé'::text,'laissant'::text,'Le premier bébé tortue a laissé une longue trace derrière lui dans le sable mouillé.'::text),
(397970,44219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İlk yavru ıslak kumda arkasında uzun bir iz ...'::text,'bıraktı'::text,'bırakıldı'::text,'bırakarak'::text,'İlk yavru ıslak kumda arkasında uzun bir iz bıraktı.'::text),
(397971,44219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az első kis teknős hosszú nyomot ... maga után a nedves homokban.'::text,'hagyott'::text,'hagyva lett'::text,'hagyva'::text,'Az első kis teknős hosszú nyomot hagyott maga után a nedves homokban.'::text),
(397974,44220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gute Arbeit, Detektiv: Diese Spur ... von den Babyschildkröten sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Gute Arbeit, Detektiv: Diese Spur muss von den Babyschildkröten sein.'::text),
(397978,44220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, детективе: цей слід ... бути від маленьких черепашок.'::text,'напевно, мусить'::text,'не може'::text,'мав би'::text,'Чудова робота, детективе: цей слід напевно, мусить бути від маленьких черепашок.'::text),
(397977,44220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, detective: ese rastro ... ser de las tortuguitas.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Buen trabajo, detective: ese rastro debe de ser de las tortuguitas.'::text),
(397976,44220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, détective : cette trace ... venir des bébés tortues.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Bravo, détective : cette trace doit venir des bébés tortues.'::text),
(397979,44220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aferin dedektif: o iz yavru kaplumbağalardan ...'::text,'olmalı'::text,'olamaz'::text,'olması gerek'::text,'Aferin dedektif: o iz yavru kaplumbağalardan olmalı.'::text),
(397980,44220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, nyomozó: az a nyom ... a teknősbébiktől származik.'::text,'biztosan'::text,'biztosan nem'::text,'elvileg'::text,'Szép munka, nyomozó: az a nyom biztosan a teknősbébiktől származik.'::text),
(397983,44221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Spur, ... die Babyschildkröten hinterlassen haben, ist irgendwie voll süß.'::text,'die'::text,'wer'::text,'deren'::text,'Bro, die Spur, die die Babyschildkröten hinterlassen haben, ist irgendwie voll süß.'::text),
(397987,44221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, слід, ... залишили черепашенята, чесно, такий милий.'::text,'який'::text,'хто'::text,'чий'::text,'Бро, слід, який залишили черепашенята, чесно, такий милий.'::text),
(397986,44221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el rastro ... dejaron las tortuguitas es, en plan, supermono.'::text,'que'::text,'quien'::text,'cuyo'::text,'Bro, el rastro que dejaron las tortuguitas es, en plan, supermono.'::text),
(397985,44221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la trace ... les bébés tortues ont laissée est trop mignonne, genre.'::text,'que'::text,'qui'::text,'dont'::text,'Frérot, la trace que les bébés tortues ont laissée est trop mignonne, genre.'::text),
(397988,44221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... yavru kaplumbağaların bıraktığı iz resmen çok tatlı.'::text,''::text,NULL::text,NULL::text,'Kanka, yavru kaplumbağaların bıraktığı iz resmen çok tatlı.'::text),
(397989,44221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a nyom, ... a teknősbébik hagytak, amúgy nagyon cuki.'::text,'amit'::text,'aki'::text,'aminek a'::text,'Tesó, a nyom, amit a teknősbébik hagytak, amúgy nagyon cuki.'::text),
(397992,44222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie meinte, die Schildkröten ... eine Spur den Strand runter hinterlassen, ohne Scheiß.'::text,'hätten'::text,'haben'::text,'haben'::text,'Alter, sie meinte, die Schildkröten hätten eine Spur den Strand runter hinterlassen, ohne Scheiß.'::text),
(397996,44222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона сказала, що черепахи ... слід аж донизу пляжем, без жартів.'::text,'залишили'::text,'залишили'::text,'залишають'::text,'Чувак, вона сказала, що черепахи залишили слід аж донизу пляжем, без жартів.'::text),
(397995,44222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, dijo que las tortugas ... un rastro playa abajo, sin mentir.'::text,'habían dejado'::text,'han dejado'::text,'dejan'::text,'Tío, dijo que las tortugas habían dejado un rastro playa abajo, sin mentir.'::text),
(397994,44222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle a dit que les tortues ... une trace jusqu''en bas de la plage, sans mentir.'::text,'avaient laissé'::text,'ont laissé'::text,'laissent'::text,'Mec, elle a dit que les tortues avaient laissé une trace jusqu''en bas de la plage, sans mentir.'::text),
(397997,44222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kaplumbağaların plaj boyunca bir iz ... söyledi, yemin ederim.'::text,'bıraktığını'::text,'bıraktığını'::text,'bıraktığını'::text,'Kanka, kaplumbağaların plaj boyunca bir iz bıraktığını söyledi, yemin ederim.'::text),
(397998,44222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azt mondta, hogy a teknősök ... egy nyomot le a partig, komolyan.'::text,'hagytak'::text,'hagytak'::text,'hagynak'::text,'Tesó, azt mondta, hogy a teknősök hagytak egy nyomot le a partig, komolyan.'::text),
(398001,44223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Strand ... früher nur 30 Schildkrötenspuren pro Nacht, deutlich unter dem Ziel.'::text,'hatte'::text,'hatte'::text,'hatte'::text,'Dieser Strand hatte früher nur 30 Schildkrötenspuren pro Nacht, deutlich unter dem Ziel.'::text),
(398005,44223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На цьому пляжі ... лише 30 черепашачих слідів за ніч — значно нижче від цілі.'::text,'бувало'::text,'бувало'::text,'звикли мати'::text,'На цьому пляжі бувало лише 30 черепашачих слідів за ніч — значно нижче від цілі.'::text),
(398004,44223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta playa ... tener solo 30 rastros de tortuga por noche, muy por debajo del objetivo.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Esta playa solía tener solo 30 rastros de tortuga por noche, muy por debajo del objetivo.'::text),
(398003,44223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette plage ... seulement 30 traces de tortues par nuit, bien en dessous de l''objectif.'::text,'avait'::text,'avait'::text,'avait l''habitude d''avoir'::text,'Cette plage avait seulement 30 traces de tortues par nuit, bien en dessous de l''objectif.'::text),
(398006,44223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu plajda eskiden gecede sadece 30 kaplumbağa izi ..., hedefin çok altında.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Bu plajda eskiden gecede sadece 30 kaplumbağa izi olurdu, hedefin çok altında.'::text),
(398007,44223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen a strandon régen csak 30 teknősnyom ... éjszakánként, jóval a cél alatt.'::text,'volt'::text,'volt'::text,'volt'::text,'Ezen a strandon régen csak 30 teknősnyom volt éjszakánként, jóval a cél alatt.'::text),
(398010,44224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Schildkröten ... der Spur immer weiter, weil die Spur dahin führt, wo sie hingehen.'::text,'folgen'::text,'folgen'::text,'folgen'::text,'Die Schildkröten folgen der Spur immer weiter, weil die Spur dahin führt, wo sie hingehen.'::text),
(398014,44224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Черепахи все ... по сліду, бо слід веде туди, куди вони йдуть.'::text,'ідуть'::text,'ідуть'::text,'ідуть'::text,'Черепахи все ідуть по сліду, бо слід веде туди, куди вони йдуть.'::text),
(398013,44224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las tortugas siguen ... el rastro porque el rastro va adonde ellas van.'::text,'siguiendo'::text,'siguiendo'::text,'siguiendo'::text,'Las tortugas siguen siguiendo el rastro porque el rastro va adonde ellas van.'::text),
(398012,44224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tortues continuent de ... la trace parce que la trace va là où elles vont.'::text,'suivre'::text,'suivre'::text,'suivre'::text,'Les tortues continuent de suivre la trace parce que la trace va là où elles vont.'::text),
(398015,44224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kaplumbağalar izi ... duruyor, çünkü iz onların gittiği yere gidiyor.'::text,'takip edip'::text,'takip edip'::text,'takip edip'::text,'Kaplumbağalar izi takip edip duruyor, çünkü iz onların gittiği yere gidiyor.'::text),
(398016,44224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A teknősök folyamatosan ... a nyomot, mert a nyom oda vezet, ahová mennek.'::text,'követik'::text,'követik'::text,'követik'::text,'A teknősök folyamatosan követik a nyomot, mert a nyom oda vezet, ahová mennek.'::text),
(344496,38278,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade über den Boulevard, als sich dir die ganze Menge anschloss. Ikonisch.'::text,'gingst'::text,'gingst'::text,'bist gegangen'::text,'Du gingst gerade über den Boulevard, als sich dir die ganze Menge anschloss. Ikonisch.'::text),
(344500,38278,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти якраз ... бульвар, коли до тебе приєдналася вся юрба. Культово.'::text,'переходила'::text,'перейшла'::text,'перейшла'::text,'Ти якраз переходила бульвар, коли до тебе приєдналася вся юрба. Культово.'::text),
(344499,38278,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el bulevar cuando toda la multitud se unió a ti. Icónico.'::text,'Estabas cruzando'::text,'Cruzaste'::text,'Has cruzado'::text,'Estabas cruzando el bulevar cuando toda la multitud se unió a ti. Icónico.'::text),
(344498,38278,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... le boulevard quand toute la foule t''a rejointe. Iconique.'::text,'traversais'::text,'as traversé'::text,'as traversé'::text,'Tu traversais le boulevard quand toute la foule t''a rejointe. Iconique.'::text),
(344501,38278,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bulvarı ... ki bütün kalabalık sana katıldı. İkonik.'::text,'geçiyordun'::text,'geçtin'::text,'geçtin'::text,'Sen bulvarı geçiyordun ki bütün kalabalık sana katıldı. İkonik.'::text),
(344502,38278,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a sugárúton, amikor az egész tömeg csatlakozott hozzád. Ikonikus.'::text,'Épp átkeltél'::text,'Átkeltél'::text,'Átkeltél'::text,'Épp átkeltél a sugárúton, amikor az egész tömeg csatlakozott hozzád. Ikonikus.'::text),
(344505,38279,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich jede Überquerung mit deinem Selbstbewusstsein machen würde, ... ich auch ein Baguette dabei.'::text,'hätte'::text,'habe'::text,'habe'::text,'Wenn ich jede Überquerung mit deinem Selbstbewusstsein machen würde, hätte ich auch ein Baguette dabei.'::text),
(344509,38279,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я кожен перехід робив з твоєю впевненістю, я теж ... багет.'::text,'носив би'::text,'носитиму'::text,'ношу'::text,'Якби я кожен перехід робив з твоєю впевненістю, я теж носив би багет.'::text),
(344508,38279,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hiciera cada cruce con tu seguridad, yo también ... una baguette.'::text,'llevaría'::text,'llevaré'::text,'llevo'::text,'Si hiciera cada cruce con tu seguridad, yo también llevaría una baguette.'::text),
(344507,38279,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si je faisais chaque traversée avec ton assurance, moi aussi je ... une baguette.'::text,'porterais'::text,'porterai'::text,'porte'::text,'Si je faisais chaque traversée avec ton assurance, moi aussi je porterais une baguette.'::text),
(344510,38279,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her karşıya geçişi senin özgüveninle yapsaydım, ben de bir baget ...'::text,'taşırdım'::text,'taşıyacağım'::text,'taşıyorum'::text,'Her karşıya geçişi senin özgüveninle yapsaydım, ben de bir baget taşırdım.'::text),
(344511,38279,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha minden átkelést a te magabiztosságoddal csinálnék, én is ... egy bagettet.'::text,'hordanék'::text,'fogok hordani'::text,'hordok'::text,'Ha minden átkelést a te magabiztosságoddal csinálnék, én is hordanék egy bagettet.'::text),
(344514,38280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Überquerung des breiten Boulevards ... von der gegenüberliegenden Seite gefilmt.'::text,'wurde'::text,'hat'::text,'wird'::text,'Ihre Überquerung des breiten Boulevards wurde von der gegenüberliegenden Seite gefilmt.'::text),
(344518,38280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як вона переходить широкий бульвар, ... з протилежного боку.'::text,'зняли'::text,'зняв'::text,'знімає'::text,'Як вона переходить широкий бульвар, зняли з протилежного боку.'::text),
(344517,38280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su cruce del ancho bulevar ... desde el otro lado.'::text,'fue grabado'::text,'grabó'::text,'está grabando'::text,'Su cruce del ancho bulevar fue grabado desde el otro lado.'::text),
(344516,38280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa traversée du large boulevard ... depuis l''autre côté.'::text,'a été filmée'::text,'a filmé'::text,'est en train de filmer'::text,'Sa traversée du large boulevard a été filmée depuis l''autre côté.'::text),
(344519,38280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun geniş bulvardan karşıya geçişi karşı taraftan ...'::text,'çekildi'::text,'çekti'::text,'çekiyor'::text,'Onun geniş bulvardan karşıya geçişi karşı taraftan çekildi.'::text),
(344520,38280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A széles sugárúton való átkelését a túloldalról ...'::text,'filmezték'::text,'filmezte'::text,'filmezi'::text,'A széles sugárúton való átkelését a túloldalról filmezték.'::text),
(344523,38281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Autos ... während der ganzen Überquerung, solange die Ampel grün war.'::text,'warteten'::text,'wurden gewartet'::text,'wartend'::text,'Die Autos warteten während der ganzen Überquerung, solange die Ampel grün war.'::text),
