(344528,38281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık yeşilken arabalar geçiş boyunca ...'::text,'bekledi'::text,'beklendi'::text,'bekleyerek'::text,'Işık yeşilken arabalar geçiş boyunca bekledi.'::text),
