(344532,38282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Überquerung ... ihr täglicher Heimweg sein, aber niemand weiß es sicher.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Diese Überquerung könnte ihr täglicher Heimweg sein, aber niemand weiß es sicher.'::text),
(344536,38282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цей перехід ... бути її щоденною дорогою додому, але ніхто не знає напевно.'::text,'може'::text,'мусить'::text,'не може'::text,'Цей перехід може бути її щоденною дорогою додому, але ніхто не знає напевно.'::text),
(344535,38282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este cruce ... ser su camino diario a casa, pero nadie lo sabe seguro.'::text,'podría'::text,'debe de'::text,'no puede'::text,'Este cruce podría ser su camino diario a casa, pero nadie lo sabe seguro.'::text),
